UPDATE rooms SET name = 'The Track Head', description = 'The made road ends. Not at a wall or a gate or anything that decided it — the last of the laid stone simply stops being laid, and what continues east is a worn place in the turf of exactly the same width. Somebody''s responsibility finished here and nobody''s began. From this step on, everything under your boots got that way by being walked on.', is_entry = 0, is_safe = 0,
