UPDATE rooms SET name = 'The Boulder Beach', description = 'The shingle coarsens westward into stones you could not lift, then into stones the size of carts, and the tideline goes over and around them without ever getting up onto the land properly. These did not come from the sea. They came down, a long time ago, and the water has been failing to move them ever since.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 68, map_y = 10 WHERE id = 'the-boulder-beach';
DELETE FROM exits WHERE room_id = 'the-boulder-beach';
