UPDATE rooms SET name = 'The Burn Mouth', description = 'Water comes out of the hill here and goes into the sea across forty feet of gravel, in a dozen shallow braids that shift with every spate. It is loud out of all proportion to its size. Follow it up and it will take you as far as it comes from, which is further than it looks.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 69, map_y = 10 WHERE id = 'the-burn-mouth';
