UPDATE rooms SET name = 'The Cobble Bank', description = 'A long low bank of rounded stone thrown up where the burn meets the tide, every cobble grey and identical and perfectly smooth. Standing on it you sink and slide with each step and the whole bank talks under you. Nothing grows on it. Nothing has time to.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 69, map_y = 11 WHERE id = 'the-cobble-bank';
DELETE FROM exits WHERE room_id = 'the-cobble-bank';
