UPDATE rooms SET name = 'The First Rise', description = 'The ground tilts. It is not steep and it does not look like anything, but your breathing changes within a dozen strides and does not change back. Behind you the water is already lower than you are. Ahead the slope goes up and up in the same unremarkable way for longer than you can see.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 70, map_y = 9 WHERE id = 'the-first-rise';
