UPDATE rooms SET name = 'The Wind Flat', description = 'A shelf of level ground with nothing on it but wind-cropped grass an inch high, lying so flat and cut so even it looks mown. Nothing has mown it. The wind comes off the water and over this shelf without meeting anything at all, and it has been doing that long enough to decide what grows and how tall.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 70, map_y = 8 WHERE id = 'the-wind-flat';
