UPDATE rooms SET name = 'The Thorn Scrub', description = 'Blackthorn grown into a low dense mat, waist high and impassable except where the animals have driven tunnels through it. The tunnels are the right height for something on four legs and the wrong height for you. Everything in here has spines and everything leans the same way, away from the sea.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 70, map_y = 10 WHERE id = 'the-thorn-scrub';
