UPDATE rooms SET name = 'The Lower Beck', description = 'The burn runs in a shallow trough of its own making, between banks of turf it has undercut and dropped in. The water is peat-brown in the deep parts and clear over the gravel and cold enough to ache your hands within a count of ten. There is no path along it. There is just the side of it, which is where you walk.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 70, map_y = 11 WHERE id = 'the-lower-beck';
