UPDATE rooms SET name = 'The Alder Thicket', description = 'Alders standing in the wet, close together and none of them tall, with their roots out of the ground in grey knuckled tangles where the burn has taken the soil from under them. It is dark in here at midday. Everything is either water or root and there is no ground between the two you can trust.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 70, map_y = 12 WHERE id = 'the-alder-thicket';
