UPDATE rooms SET name = 'The Turf Wall', description = 'A wall built of turf sods laid like bricks, chest high once and thigh high now, running away north and south along the contour until it fades into the slope. It is not keeping anything in or out. It marks where the grazing was worth walling, and the fact that it stops means somebody decided, precisely, where that was.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 71, map_y = 8 WHERE id = 'the-turf-wall';
