INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turf-wall', 'west', 'the-wind-flat', NULL);

UPDATE rooms SET name = 'The Shieling', description = 'A single hut of stone and turf built into the slope with its back to the weather, low enough that you duck, and dry inside, which is more than the mountain offers anywhere else. People came up here with the animals for the summer months and went down again before the weather turned, every year, for a very long time, and then one year did not come. Somebody is here now. He does not say who or why, and the fire is lit.', is_entry = 1, is_safe = 0,
  region = 'mountain', is_spawn = 1, map_x = 71, map_y = 7 WHERE id = 'the-shieling';
