INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shieling', 'east', 'the-milking-fold', NULL);

UPDATE rooms SET name = 'The Milking Fold', description = 'A small round pen of dry stone, waist high, with a gap in it and a flat worn slab beside the gap where somebody sat. Beasts were brought in here twice a day and let out again and the ground inside is still a different colour from the ground outside. It will be a different colour for another hundred years.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 72, map_y = 7 WHERE id = 'the-milking-fold';
