UPDATE rooms SET name = 'The Nettle Ground', description = 'Nettles, shoulder high, in a dense stand about the size of a house and nowhere else on this hillside. Nettles grow where people lived — on old middens, on the ground by a door, wherever the dung went. The people are two hundred years gone and the nettles have not noticed and will not.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 71, map_y = 6 WHERE id = 'the-nettle-ground';
