UPDATE rooms SET name = 'The Hearth Stone', description = 'A hearth without a house: one broad flat stone with a ring of smaller ones round it, reddened right through by more fires than anybody could count, sitting in open grass with no wall or post or footing anywhere near it. Whatever stood over it went back into the ground. The stone will not. You could light a fire on it tonight and it would work.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 72, map_y = 6 WHERE id = 'the-hearth-stone';
