UPDATE rooms SET name = 'The Last Pasture', description = 'Grass — real grass, green and thick and worth something — in a long sloping field with the wall below it and the hill above. This is the top of the good ground and everybody who ever came up here knew it. Above this the grass gets thinner every fifty feet and stops being a crop and starts being whatever will hold on.', is_entry = 0, is_safe = 0,
