UPDATE rooms SET name = 'The Rush Hollow', description = 'A dip holding water it cannot drain, gone entirely to soft rush in dark clumps you step between rather than through. Underfoot it is black and gives. Something has been lying up here: there is a pressed oval in the rushes, big enough to matter, and the stems in it have not sprung back yet.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 71, map_y = 9 WHERE id = 'the-rush-hollow';
