UPDATE rooms SET name = 'The Stell', description = 'A circular dry-stone shelter built in a ring so that beasts inside it could always get out of the wind whichever way it blew — a piece of very good thinking done by somebody with nothing but stone and a lot of time. Half of it has been roofed over since, badly, with poles and turf and a stretched hide, and there is a fire under the roofed half and a man keeping it. He came up with the last of the summer people and did not go down with them.', is_entry = 1, is_safe = 0,
  region = 'mountain', is_spawn = 1, map_x = 72, map_y = 9 WHERE id = 'the-stell';
