UPDATE rooms SET name = 'The Bracken Slope', description = 'Bracken to the chest, unbroken across the whole face of the slope, hiding the ground and every hole and stone in it completely. It comes in where grazing stops and it does not go out again. Walking through it you cannot see your own feet, and you can hear things moving that you will not see at all.', is_entry = 0, is_safe = 0,
