UPDATE rooms SET name = 'The Cotton Grass', description = 'Bog cotton, thousands of it, each on its own thin stalk, all leaning together and letting go together when the wind comes over. From below it reads as a white haze lying on the hill. Up close it is a signal you should read: it grows where the ground will not hold you.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 73, map_y = 7 WHERE id = 'the-cotton-grass';
