UPDATE rooms SET name = 'The Peat Hags', description = 'The peat has torn open into a maze of steep black-sided channels, six feet deep, with flat-topped islands of heather standing between them. You go down into one and along it and up out of it, or you go round, and either way you cannot see over the tops while you are in there. Old wood sticks out of the cut faces — whole trunks, black and sound, from a forest that stood here before any of this was peat.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 73, map_y = 6 WHERE id = 'the-peat-hags';
DELETE FROM exits WHERE room_id = 'the-peat-hags';
