UPDATE rooms SET name = 'The Peat Pool', description = 'A pool in the peat, small and perfectly still and the colour of strong tea held to a candle, with no inlet and no outlet and no bottom you can see. Nothing lives in it — the water is too sour. Things that go into water like this do not rot. They keep.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 74, map_y = 6 WHERE id = 'the-peat-pool';
