UPDATE rooms SET name = 'The Drowned Fence', description = 'A line of fence posts walking away up the slope and into the bog, each one shorter than the last as the ground swallows them, until the last two show as knuckles of grey wood in the moss and then there are no more. Whoever set these was fencing ground that has since eaten the fence. There is wire still strung between the first four.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 74, map_y = 7 WHERE id = 'the-drowned-fence';
