UPDATE rooms SET name = 'The Clapper', description = 'Three slabs of stone laid end to end across the burn on two piers of stacked rock — the simplest bridge there is, and the oldest kind, and it has not moved. Nobody signs a thing like this. Somebody needed to get across with something heavy, once, and solved it, and the solution is still solving it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 71, map_y = 11 WHERE id = 'the-clapper';
