UPDATE rooms SET name = 'The Beck Narrows', description = 'The burn goes into a slot barely wider than your shoulders, walled in rock on both sides and roofed in places by boulders that fell in and jammed. The noise in here doubles. You can bridge the whole burn with one stride and you can also not see the sky.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 71, map_y = 12 WHERE id = 'the-beck-narrows';
DELETE FROM exits WHERE room_id = 'the-beck-narrows';
