UPDATE rooms SET name = 'The Plunge Pool', description = 'A round green pool scoured out under a fall of about the height of two men, deep enough in the middle that the bottom goes from gravel to nothing. The spray keeps a ring of ground round it permanently wet, and the moss on that ring is the brightest thing in this whole valley.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 72, map_y = 12 WHERE id = 'the-plunge-pool';
