UPDATE rooms SET name = 'The Water Slide', description = 'A long smooth tongue of bare rock the burn runs down in a sheet an inch deep, polished over centuries into something you could genuinely slide on, and will if you put a foot wrong. There is nothing to hold. The rock is not sharp anywhere and that is precisely the problem.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 72, map_y = 11 WHERE id = 'the-water-slide';
