UPDATE rooms SET name = 'The Gravel Race', description = 'The burn spreads and shallows over a bed of loose gravel that shifts audibly as the water works it, a low grinding under the water noise. Every stone here is on its way down. Stand in it long enough and you can feel the bed moving under your boots.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 73, map_y = 11 WHERE id = 'the-gravel-race';
DELETE FROM exits WHERE room_id = 'the-gravel-race';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-race', 'south', 'the-fallen-birch', NULL);
