UPDATE rooms SET name = 'The Fallen Birch', description = 'A birch came down across the water some years ago and has stayed, wedged, with the burn running under it and a raft of everything the burn has carried since piled against its upstream side. The trunk is slick and green. It is the only easy crossing for a long way and it is not easy.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 73, map_y = 12 WHERE id = 'the-fallen-birch';
DELETE FROM exits WHERE room_id = 'the-fallen-birch';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-birch', 'north', 'the-gravel-race', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-birch', 'east', 'the-dry-course', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-birch', 'west', 'the-plunge-pool', NULL);

UPDATE rooms SET name = 'The Beck Fork', description = 'Two waters meet, and you can see that they are not the same water: one comes down clear and quick off the rock, the other comes brown and slow out of the peat, and for thirty feet below the junction they run side by side in the same channel without mixing. Then they mix.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 74, map_y = 11 WHERE id = 'the-beck-fork';
DELETE FROM exits WHERE room_id = 'the-beck-fork';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-fork', 'north', 'the-hollow-under', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-fork', 'south', 'the-dry-course', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-fork', 'east', 'the-spring-eye', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beck-fork', 'west', 'the-gravel-race', NULL);

UPDATE rooms SET name = 'The Dry Course', description = 'A stream bed with no stream in it: clean scoured rock, banks cut square, gravel graded and sorted exactly as running water sorts it, and not a drop anywhere. It runs when the hill is full and it is not full now. Everything about this place says water and there is none, and that should tell you what it is like when there is.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 74, map_y = 12 WHERE id = 'the-dry-course';
DELETE FROM exits WHERE room_id = 'the-dry-course';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-course', 'north', 'the-beck-fork', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-course', 'east', 'the-flood-gravel', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-course', 'west', 'the-fallen-birch', NULL);

UPDATE rooms SET name = 'The Spring Eye', description = 'Water comes straight up out of flat ground here through a bed of pale sand, and the sand boils and settles and boils again where it rises, and the whole thing is about the size of a shield. It is doing this constantly and has been for longer than anything else in view has existed. It is the coldest water on this hill.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 75, map_y = 11 WHERE id = 'the-spring-eye';
DELETE FROM exits WHERE room_id = 'the-spring-eye';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-eye', 'south', 'the-flood-gravel', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-eye', 'east', 'the-lower-force', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-eye', 'west', 'the-beck-fork', NULL);

UPDATE rooms SET name = 'The Flood Gravel', description = 'An apron of raw gravel and torn turf spread thirty yards wide across ground the burn does not normally reach, with boulders sitting on the surface where the water dropped them and stopped. This happened in one afternoon, some year, and the mountain has not tidied it and will not.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 75, map_y = 12 WHERE id = 'the-flood-gravel';
DELETE FROM exits WHERE room_id = 'the-flood-gravel';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flood-gravel', 'north', 'the-spring-eye', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flood-gravel', 'east', 'the-force-pool', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flood-gravel', 'west', 'the-dry-course', NULL);

UPDATE rooms SET name = 'The Lower Force', description = 'The burn comes over a lip of hard rock in one drop, twice your height, into the pool below, and the fall is narrow and heavy and hits like something solid. Standing beside it you cannot make yourself heard. There is a way up beside it if you use your hands.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 11 WHERE id = 'the-lower-force';
DELETE FROM exits WHERE room_id = 'the-lower-force';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-force', 'south', 'the-force-pool', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-force', 'west', 'the-spring-eye', NULL);

UPDATE rooms SET name = 'The Force Pool', description = 'The catch-basin under the fall, black and turning slowly and colder than the air, walled on three sides by wet rock that never sees the sun. Things that come down the burn end up circling in here for a while before they go on. Some of them do not go on.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 12 WHERE id = 'the-force-pool';
DELETE FROM exits WHERE room_id = 'the-force-pool';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-force-pool', 'north', 'the-lower-force', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-force-pool', 'south', 'the-black-runnel', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-force-pool', 'west', 'the-flood-gravel', NULL);

UPDATE rooms SET name = 'The Boulder Field', description = 'Rock, from head-sized to house-sized, dumped across the whole width of the valley in no order whatever and left. There is no path through and no path round; you go over it, boulder to boulder, and the gaps between them go down further than you want to look. Every one of these came from somewhere higher up.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 73, map_y = 9 WHERE id = 'the-boulder-field';
DELETE FROM exits WHERE room_id = 'the-boulder-field';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-field', 'north', 'the-bracken-slope', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-field', 'east', 'the-erratic', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-field', 'west', 'the-stell', NULL);

UPDATE rooms SET name = 'The Erratic', description = 'One boulder standing by itself on open ground, the size of a small house, of a stone that matches nothing anywhere near it. It was carried here and set down. The thing that carried it was ice, and the ice is gone, and this is what it left behind to say so.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 74, map_y = 9 WHERE id = 'the-erratic';
DELETE FROM exits WHERE room_id = 'the-erratic';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-erratic', 'south', 'the-hollow-under', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-erratic', 'east', 'the-moraine-bank', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-erratic', 'west', 'the-boulder-field', NULL);

UPDATE rooms SET name = 'The Hollow Under', description = 'The erratic sits on three points and the fourth corner is off the ground, and under it there is a dry floor of sand the size of a small room, out of the wind and out of the rain and out of the sight of everything. Somebody lived in here. There is a ring of stones for a fire with nothing in it but old ash, and the sand was swept once, long enough ago that the swept edge has gone soft and the wind has put a drift across the doorway.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 74, map_y = 10 WHERE id = 'the-hollow-under';
DELETE FROM exits WHERE room_id = 'the-hollow-under';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-under', 'north', 'the-erratic', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-under', 'south', 'the-beck-fork', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-under', 'east', 'the-stone-river', NULL);

UPDATE rooms SET name = 'The Moraine Bank', description = 'A long even ridge of mixed rubble running across the slope, out of place in a landscape of curves — too straight, too regular, sides at the same angle the whole length of it. It is the exact shape of the front of something that stopped here for a long time and then went back up.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 75, map_y = 9 WHERE id = 'the-moraine-bank';
DELETE FROM exits WHERE room_id = 'the-moraine-bank';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-bank', 'north', 'the-scree-toe', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-bank', 'south', 'the-stone-river', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-bank', 'east', 'the-sorted-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-bank', 'west', 'the-erratic', NULL);

UPDATE rooms SET name = 'The Stone River', description = 'A band of loose rock a hundred feet wide winding down the slope between banks of turf, for all the world like a watercourse with the water taken out. It moves. Not while you are watching, but the turf at its edges is torn and freshly buried and the whole thing is a foot further down the hill each year.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 75, map_y = 10 WHERE id = 'the-stone-river';
DELETE FROM exits WHERE room_id = 'the-stone-river';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-river', 'north', 'the-moraine-bank', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-river', 'east', 'the-lichen-boulders', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-river', 'west', 'the-hollow-under', NULL);

UPDATE rooms SET name = 'The Sorted Ground', description = 'The stones here have arranged themselves into rings and stripes — coarse rock in the lines, fine gravel between — over an area the size of a field, as neatly as if someone had raked it. Nobody raked it. Frost did it, lifting and dropping and lifting again, ten thousand winters of doing the same small thing.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 9 WHERE id = 'the-sorted-ground';
DELETE FROM exits WHERE room_id = 'the-sorted-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sorted-ground', 'south', 'the-lichen-boulders', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sorted-ground', 'east', 'the-cold-hollow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sorted-ground', 'west', 'the-moraine-bank', NULL);

UPDATE rooms SET name = 'The Lichen Boulders', description = 'Every stone here carries a crust of lichen in grey-green plates and rings, and the biggest rings are the size of a spread hand. They grow about the width of a hair in a year. Doing the arithmetic on the one by your knee is not a comfortable way to spend a minute.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 10 WHERE id = 'the-lichen-boulders';
DELETE FROM exits WHERE room_id = 'the-lichen-boulders';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lichen-boulders', 'north', 'the-sorted-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lichen-boulders', 'east', 'the-glacier-mouth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lichen-boulders', 'west', 'the-stone-river', NULL);

UPDATE rooms SET name = 'The Glacier Mouth', description = 'A dark arched hole at the foot of the rock where the burn comes out from under the mountain, wide enough to walk into and low enough that you would not for long. The air coming out is colder than the day. This is where the water starts being water, and the way in goes back further than the light does.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 10 WHERE id = 'the-glacier-mouth';
DELETE FROM exits WHERE room_id = 'the-glacier-mouth';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-mouth', 'north', 'the-cold-hollow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-mouth', 'west', 'the-lichen-boulders', NULL);

UPDATE rooms SET name = 'The Cold Hollow', description = 'A basin in the rock that the sun does not reach at any hour, holding a floor of grey rubble and a skin of old snow that has been there since some winter nobody remembers. It is markedly colder standing here than ten steps away, and you feel it as soon as you cross the line.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 9 WHERE id = 'the-cold-hollow';
DELETE FROM exits WHERE room_id = 'the-cold-hollow';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-hollow', 'south', 'the-glacier-mouth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-hollow', 'east', 'the-crag-shadow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-hollow', 'west', 'the-sorted-ground', NULL);

UPDATE rooms SET name = 'The Scree Toe', description = 'The bottom of a scree, where the falling stone has run out of slope and spread into a flat tongue over the turf. Down here the pieces are the biggest — they roll furthest — and they are locked together and stable and quiet. Everything above this line is not.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 75, map_y = 8 WHERE id = 'the-scree-toe';
DELETE FROM exits WHERE room_id = 'the-scree-toe';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-toe', 'south', 'the-moraine-bank', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-toe', 'east', 'the-loose-slope', NULL);

UPDATE rooms SET name = 'The Loose Slope', description = 'Scree at the angle it wants to be at, which is exactly as steep as loose rock can stand before it stops standing. Every step you take sends a small run of it away downhill, and every small run takes a little longer than the last to stop. You do not so much climb this as negotiate with it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 8 WHERE id = 'the-loose-slope';
DELETE FROM exits WHERE room_id = 'the-loose-slope';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-loose-slope', 'north', 'the-fan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-loose-slope', 'east', 'the-shifting-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-loose-slope', 'west', 'the-scree-toe', NULL);

UPDATE rooms SET name = 'The Fan', description = 'A perfect spreading cone of stone poured out of a gully above and laid down over the slope in a fan, sorted fine at the edges and coarse up the middle. It is beautiful from a distance and it is the single most tiring ground on this hill to cross.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 7 WHERE id = 'the-fan';
DELETE FROM exits WHERE room_id = 'the-fan';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fan', 'north', 'the-shattered-rib', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fan', 'south', 'the-loose-slope', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fan', 'east', 'the-rock-glacier', NULL);

UPDATE rooms SET name = 'The Shifting Ground', description = 'Big blocks resting on smaller ones, so that a slab the size of a door will tilt under your weight and settle back when you are off it. There is no way to tell which ones will do it. The noise a hillside makes when you cross it like this carries a very long way in this air.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 8 WHERE id = 'the-shifting-ground';
DELETE FROM exits WHERE room_id = 'the-shifting-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shifting-ground', 'north', 'the-rock-glacier', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shifting-ground', 'east', 'the-boulder-choke', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shifting-ground', 'west', 'the-loose-slope', NULL);

UPDATE rooms SET name = 'The Rock Glacier', description = 'A tongue of rubble with ridges across it like ripples, bulging out from the foot of the crag, and it is not a heap — it is flowing, with ice inside it doing the flowing, slower than anything you could measure in a life. It is going downhill. It will get there.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 7 WHERE id = 'the-rock-glacier';
DELETE FROM exits WHERE room_id = 'the-rock-glacier';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rock-glacier', 'south', 'the-shifting-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rock-glacier', 'east', 'the-first-crag', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rock-glacier', 'west', 'the-fan', NULL);

UPDATE rooms SET name = 'The Boulder Choke', description = 'The gully above has jammed solid with fallen blocks, wedged one against another and holding each other up over gaps you could fall the length of your body into. There is a way through it at the back on hands and knees. Everything here is holding everything else here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 8 WHERE id = 'the-boulder-choke';
DELETE FROM exits WHERE room_id = 'the-boulder-choke';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-choke', 'north', 'the-first-crag', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-choke', 'south', 'the-crag-shadow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-choke', 'east', 'the-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-choke', 'west', 'the-shifting-ground', NULL);

UPDATE rooms SET name = 'The First Crag', description = 'The first honest rock: a wall of it, wet, black, and going up out of sight past where the mist takes it. Up to now the mountain has been ground you could walk over given enough patience. This is the end of that argument.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 7 WHERE id = 'the-first-crag';
DELETE FROM exits WHERE room_id = 'the-first-crag';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-crag', 'south', 'the-boulder-choke', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-crag', 'west', 'the-rock-glacier', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-crag', 'up', 'the-brink', NULL);

UPDATE rooms SET name = 'The Crag Shadow', description = 'The strip of ground along the base of the wall, in permanent shade, floored with everything the crag has dropped — flakes, blocks, a few things that were once whole. Nothing grows on it. There is a sound, every so often, of one more piece arriving somewhere along the line.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 9 WHERE id = 'the-crag-shadow';
DELETE FROM exits WHERE room_id = 'the-crag-shadow';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crag-shadow', 'north', 'the-boulder-choke', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crag-shadow', 'south', 'the-gully-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crag-shadow', 'west', 'the-cold-hollow', NULL);

UPDATE rooms SET name = 'The Notch', description = 'A slot in the crag line, no wider than a cart, with the ground rising through it and out the other side. It is the only break in the wall for as far as you can see in either direction, and everything that goes up this side of the mountain goes through here. There are tracks in the wet grit, and none of them are boots.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 79, map_y = 8 WHERE id = 'the-notch';
DELETE FROM exits WHERE room_id = 'the-notch';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-notch', 'west', 'the-boulder-choke', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-notch', 'up', 'the-gully-head', NULL);

UPDATE rooms SET name = 'The Shattered Rib', description = 'A rib of harder rock standing proud of the slope and split from top to bottom by frost into slabs that lean apart like a book fanned open. You can walk into the gaps a little way. They are the width of a body and they do not go anywhere.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 6 WHERE id = 'the-shattered-rib';
DELETE FROM exits WHERE room_id = 'the-shattered-rib';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shattered-rib', 'north', 'the-raven-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shattered-rib', 'south', 'the-fan', NULL);

UPDATE rooms SET name = 'The Gully Foot', description = 'Where a gully in the crag comes down and delivers, onto a heap of its own leavings — grit, splinters, and one or two things heavy enough to have come down fast. The gully goes up into the dark of the rock and narrows and you cannot see the top of it from here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 10 WHERE id = 'the-gully-foot';
DELETE FROM exits WHERE room_id = 'the-gully-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-foot', 'north', 'the-crag-shadow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-foot', 'south', 'the-cleft', NULL);

UPDATE rooms SET name = 'The Goat Track', description = 'A path a hand''s breadth wide traversing the slope on the level, worn into the turf by something going single file to the same place every day. It contours instead of climbing, which is how you know nothing with two legs made it. Follow it and it will take you somewhere worth going, by their reckoning.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 72, map_y = 5 WHERE id = 'the-goat-track';
DELETE FROM exits WHERE room_id = 'the-goat-track';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-goat-track', 'south', 'the-hearth-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-goat-track', 'east', 'the-hanging-turf', NULL);

UPDATE rooms SET name = 'The Hanging Turf', description = 'The turf ends at a clean edge and drops, undercut, with the roots showing in a mat a foot thick and the bare slope falling away underneath. The whole skin of the hillside is peeling off here, from the bottom up. You can stand on the edge of it and feel it give very slightly.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 73, map_y = 5 WHERE id = 'the-hanging-turf';
DELETE FROM exits WHERE room_id = 'the-hanging-turf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-turf', 'south', 'the-peat-hags', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-turf', 'east', 'the-wether-ledge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-turf', 'west', 'the-goat-track', NULL);

UPDATE rooms SET name = 'The Wether Ledge', description = 'A wide grass ledge across the face, sheltered from the north, with the drop below it and the rock above it, and the grass on it cropped as short as a lawn. Everything that lives up here comes to this ledge. It is the best ground on this side of the mountain and it is not big.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 74, map_y = 5 WHERE id = 'the-wether-ledge';
DELETE FROM exits WHERE room_id = 'the-wether-ledge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wether-ledge', 'north', 'the-high-fold', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wether-ledge', 'east', 'the-shelter-crag', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wether-ledge', 'west', 'the-hanging-turf', NULL);

UPDATE rooms SET name = 'The High Fold', description = 'Somebody built a wall across the neck of a natural corrie up here, once, in dry stone, to make a pen out of a shape the mountain had already made. It is the highest built thing on this hill. It is also barely a wall now, and the beasts it was for walk over it without breaking stride.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 74, map_y = 4 WHERE id = 'the-high-fold';
DELETE FROM exits WHERE room_id = 'the-high-fold';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-fold', 'south', 'the-wether-ledge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-fold', 'east', 'the-north-scree', NULL);

UPDATE rooms SET name = 'The Shelter Crag', description = 'An overhang of rock leaning far enough out that the ground beneath it is dry in any weather, and everything on this mountain has stood under here at some point. Somebody has walled the windward end with stacked slabs and moved in, which is the obvious thing to do and is the reason nothing else uses this end any more. There is a smell. Some of it is his.', is_entry = 1, is_safe = 0,
  region = 'mountain', is_spawn = 1, map_x = 75, map_y = 5 WHERE id = 'the-shelter-crag';
DELETE FROM exits WHERE room_id = 'the-shelter-crag';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelter-crag', 'north', 'the-north-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelter-crag', 'east', 'the-raven-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelter-crag', 'west', 'the-wether-ledge', NULL);

UPDATE rooms SET name = 'The North Scree', description = 'Scree on the shadowed side, wet, dark, and greasy with a film that never dries, growing nothing anywhere. It is colder here by a coat. Stones on this face are furred with a thin black crust that comes off on your hands.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 75, map_y = 4 WHERE id = 'the-north-scree';
DELETE FROM exits WHERE room_id = 'the-north-scree';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-scree', 'south', 'the-shelter-crag', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-scree', 'east', 'the-cairn-line', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-scree', 'west', 'the-high-fold', NULL);

UPDATE rooms SET name = 'The Raven Stone', description = 'A blunt tower of rock standing clear of the slope, whitened down one whole side, with the ledges on it packed and trampled and the ground beneath it full of small bones and the wrappings of pellets. It is occupied. It has been occupied continuously for longer than the fortress has stood, and the tenants have never once been asked.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 5 WHERE id = 'the-raven-stone';
DELETE FROM exits WHERE room_id = 'the-raven-stone';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-raven-stone', 'north', 'the-cairn-line', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-raven-stone', 'south', 'the-shattered-rib', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-raven-stone', 'east', 'the-wind-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-raven-stone', 'west', 'the-shelter-crag', NULL);

UPDATE rooms SET name = 'The Cairn Line', description = 'Small heaps of stone, three or four courses each, set at intervals across the shoulder and running away over the rise. They are not graves and they are not boundaries. Somebody put them here to be followed in bad weather, and the arrangement only makes sense if you are walking toward the pass, which means somebody had a reason to.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 4 WHERE id = 'the-cairn-line';
DELETE FROM exits WHERE room_id = 'the-cairn-line';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cairn-line', 'south', 'the-raven-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cairn-line', 'east', 'the-bealach', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cairn-line', 'west', 'the-north-scree', NULL);

UPDATE rooms SET name = 'The Wind Notch', description = 'A gap in the shoulder that the wind uses. Even on a still day there is air moving through here hard enough to lean into, and the grass either side of the gap lies permanently flat and combed one way. Standing in it you cannot hear anything else at all.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 5 WHERE id = 'the-wind-notch';
DELETE FROM exits WHERE room_id = 'the-wind-notch';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-notch', 'north', 'the-bealach', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-notch', 'west', 'the-raven-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-notch', 'up', 'the-slant', NULL);

UPDATE rooms SET name = 'The Bealach', description = 'The pass: the low point of the ridge, a saddle of bare ground between two rises, with the whole far side of the mountain opening beyond it and going up again out of sight. This is the way through for everything that lives here, and the ground is beaten to bare stone by the traffic of it. The cairns end here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 4 WHERE id = 'the-bealach';
DELETE FROM exits WHERE room_id = 'the-bealach';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bealach', 'south', 'the-wind-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bealach', 'west', 'the-cairn-line', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bealach', 'up', 'the-pass-head', NULL);

UPDATE rooms SET name = 'The Sphagnum Flat', description = 'Moss in one continuous saturated carpet, ankle deep and holding many times its own weight in water, in colours from pale green to a deep red that reads as dried blood at a distance. Step on it and water comes up round your boot from a foot away. This is where the mountain keeps what it does not shed.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 72, map_y = 13 WHERE id = 'the-sphagnum-flat';
DELETE FROM exits WHERE room_id = 'the-sphagnum-flat';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sphagnum-flat', 'north', 'the-plunge-pool', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sphagnum-flat', 'east', 'the-quaking-moss', NULL);

UPDATE rooms SET name = 'The Quaking Moss', description = 'The moss here has grown out over standing water rather than ground, so the whole surface moves in a slow swell when you walk on it, out to a distance of several yards. There is nothing underneath but depth. People who know this ground do not cross it and there is no sign to tell you that.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 73, map_y = 13 WHERE id = 'the-quaking-moss';
DELETE FROM exits WHERE room_id = 'the-quaking-moss';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quaking-moss', 'east', 'the-sunk-boulders', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quaking-moss', 'west', 'the-sphagnum-flat', NULL);

UPDATE rooms SET name = 'The Sunk Boulders', description = 'Boulders sitting in the bog with only their crowns showing, each one ringed by the moss that has crept up and over its sides. They came down the hill and stopped when they met ground that would not carry them, and they have been going down ever since, very slowly.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 74, map_y = 13 WHERE id = 'the-sunk-boulders';
DELETE FROM exits WHERE room_id = 'the-sunk-boulders';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-boulders', 'east', 'the-mire-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-boulders', 'west', 'the-quaking-moss', NULL);

UPDATE rooms SET name = 'The Mire Foot', description = 'Where the mire runs out against rising ground, in a fringe of black water and old heather stems and hoofprints filled to the brim. Everything that crosses this flank crosses here, because it is the only edge, and the prints are layered over each other past counting.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 75, map_y = 13 WHERE id = 'the-mire-foot';
DELETE FROM exits WHERE room_id = 'the-mire-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mire-foot', 'east', 'the-black-runnel', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mire-foot', 'west', 'the-sunk-boulders', NULL);

UPDATE rooms SET name = 'The Black Runnel', description = 'A narrow deep channel of peat-black water cut down through the bog, four feet deep and two feet wide with vertical sides, running fast and silent. There is no way to see the bottom and no easy way across. It comes from the force pool and it is going somewhere lower.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 13 WHERE id = 'the-black-runnel';
DELETE FROM exits WHERE room_id = 'the-black-runnel';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-runnel', 'north', 'the-force-pool', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-runnel', 'east', 'the-wet-slabs', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-runnel', 'west', 'the-mire-foot', NULL);

UPDATE rooms SET name = 'The Slabs', description = 'Bare rock in great tilted sheets, swept clean by the water that comes over them when the hill is full, with the joints between them opened into cracks you could put an arm down. Dry, they are the fastest walking on the mountain, and they are not often dry. The widest joint has been roofed: a slab levered flat across it and packed at the ends, with a hole for smoke and smoke coming out of it. Whoever did that picked the one place on this hillside the water goes past instead of over.', is_entry = 1, is_safe = 0,
  region = 'mountain', is_spawn = 1, map_x = 77, map_y = 12 WHERE id = 'the-slabs';
DELETE FROM exits WHERE room_id = 'the-slabs';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slabs', 'south', 'the-wet-slabs', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slabs', 'east', 'the-south-shoulder', NULL);

UPDATE rooms SET name = 'The Wet Slabs', description = 'The same rock, lower, with a permanent film of water moving across it and a growth of black algae under the film that is as slick as anything in the world. There is no technique for this. There is only choosing whether to go on it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 13 WHERE id = 'the-wet-slabs';
DELETE FROM exits WHERE room_id = 'the-wet-slabs';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-slabs', 'north', 'the-slabs', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-slabs', 'west', 'the-black-runnel', NULL);

UPDATE rooms SET name = 'The South Shoulder', description = 'The flank turns here and you come round onto ground that faces the sun, and it is a different mountain on this side: drier, browner, with heather instead of moss and the rock showing warm. You can see a great distance south. There is nothing in any of it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 12 WHERE id = 'the-south-shoulder';
DELETE FROM exits WHERE room_id = 'the-south-shoulder';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-shoulder', 'north', 'the-cleft', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-shoulder', 'west', 'the-slabs', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-shoulder', 'up', 'the-sun-shoulder', NULL);

UPDATE rooms SET name = 'The Cleft', description = 'A fissure in the rock, a stride across at the top and narrowing out of sight, running back into the mountain further than the daylight goes. Cold air comes out of it steadily. Something has been dragging things in there — there is a scored track through the grit at the lip, going one way.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 11 WHERE id = 'the-cleft';
DELETE FROM exits WHERE room_id = 'the-cleft';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cleft', 'north', 'the-gully-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cleft', 'south', 'the-south-shoulder', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cleft', 'up', 'the-wedge', NULL);

UPDATE rooms SET name = 'The Brink', description = 'A ledge on the face of the first crag, reached by the one line of holds that goes anywhere, with the whole foot of the mountain laid out underneath and nothing between you and it. It is not a way anything with four legs can come. That is the entire reason it is worth knowing about: everything else on this hill uses the notch or the pass, and nothing at all uses this.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 6 WHERE id = 'the-brink';
DELETE FROM exits WHERE room_id = 'the-brink';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brink', 'east', 'the-corrie-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brink', 'down', 'the-first-crag', NULL);

UPDATE rooms SET name = 'The Gully Head', description = 'You come out of the notch and the ground opens without warning into a bowl a half-mile across, walled on three sides, with the floor of it well below you and a black lochan sitting in the middle. It is the first thing on this mountain that has a shape. Everything below was slope; this was made, by something, on purpose, and then abandoned.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 6 WHERE id = 'the-gully-head';
DELETE FROM exits WHERE room_id = 'the-gully-head';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-head', 'north', 'the-corrie-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-head', 'south', 'the-fallen-block', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-head', 'east', 'the-corrie-mouth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-head', 'down', 'the-notch', NULL);

UPDATE rooms SET name = 'The Corrie Mouth', description = 'The lip of the bowl, where the ground stops falling away and starts falling in. Grass runs right to the edge and then there is nothing under it. From here you can see the whole floor at once, and how much of it is water, and how little of it is anywhere you could stand.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 79, map_y = 6 WHERE id = 'the-corrie-mouth';
DELETE FROM exits WHERE room_id = 'the-corrie-mouth';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-mouth', 'north', 'the-black-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-mouth', 'south', 'the-corrie-floor', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-mouth', 'east', 'the-lochan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-mouth', 'west', 'the-gully-head', NULL);

UPDATE rooms SET name = 'The Lochan', description = 'Black water, perfectly still, and so dark that the reflection of the back wall in it is better lit than the wall itself. It has no inflow you can find and one thin outflow at the far end. Nothing rises in it. Nothing rises in water this cold and this deep and this poor.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 80, map_y = 6 WHERE id = 'the-lochan';
DELETE FROM exits WHERE room_id = 'the-lochan';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan', 'north', 'the-drift-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan', 'south', 'the-lochan-shore', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan', 'east', 'the-back-wall', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan', 'west', 'the-corrie-mouth', NULL);

UPDATE rooms SET name = 'The Lochan Shore', description = 'A strand of grey grit round the water''s edge, wide in places and nothing at all in others, with the wall going straight up out of it further round. There are tracks in the grit — deer, and something with pads, and the pads are following the deer.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 80, map_y = 7 WHERE id = 'the-lochan-shore';
DELETE FROM exits WHERE room_id = 'the-lochan-shore';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan-shore', 'north', 'the-lochan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan-shore', 'east', 'the-water-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lochan-shore', 'west', 'the-corrie-floor', NULL);

UPDATE rooms SET name = 'The Back Wall', description = 'The head wall of the corrie, seven hundred feet of wet black rock leaning very slightly over you, streaked white where water comes down it and green-black where it does not. Looking up it for any length of time is unpleasant in a way that has nothing to do with the height. There is no way up this.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 81, map_y = 6 WHERE id = 'the-back-wall';
DELETE FROM exits WHERE room_id = 'the-back-wall';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-wall', 'north', 'the-old-snow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-wall', 'south', 'the-water-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-wall', 'east', 'the-hanging-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-wall', 'west', 'the-lochan', NULL);

UPDATE rooms SET name = 'The Corrie Floor', description = 'Flat ground, or nearly, floored with everything the walls have shed and gone over with moss between the blocks. It is out of the wind entirely — the first still air since the shore — and the quiet in here is total and takes some getting used to.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 79, map_y = 7 WHERE id = 'the-corrie-floor';
DELETE FROM exits WHERE room_id = 'the-corrie-floor';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-floor', 'north', 'the-corrie-mouth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-floor', 'east', 'the-lochan-shore', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-floor', 'west', 'the-fallen-block', NULL);

UPDATE rooms SET name = 'The Drift Edge', description = 'The old snow ends here in a wall waist high, undercut and blue in the shadow of its own overhang, with a foot of bare stony ground between it and the grass. That gap is where the drift used to be a month ago. It has been the same gap for longer than a month.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 80, map_y = 5 WHERE id = 'the-drift-edge';
DELETE FROM exits WHERE room_id = 'the-drift-edge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-edge', 'south', 'the-lochan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-edge', 'east', 'the-old-snow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-edge', 'west', 'the-black-scree', NULL);

UPDATE rooms SET name = 'The Old Snow', description = 'Snow that has been here through at least one summer, packed to something between ice and stone, grey on top with a season''s grit and dead insects. It rings under a boot heel. Whatever fell into this is still in it, at whatever depth the year it fell put it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 81, map_y = 5 WHERE id = 'the-old-snow';
DELETE FROM exits WHERE room_id = 'the-old-snow';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-snow', 'south', 'the-back-wall', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-snow', 'east', 'the-upper-drift', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-snow', 'west', 'the-drift-edge', NULL);

UPDATE rooms SET name = 'The Black Scree', description = 'Scree the colour of coal, small and sharp and endlessly loose, running from the corrie rim down to the floor in one unbroken sheet. Nothing has ever grown on it and nothing will; there is no ground in it, only pieces. It moves under you and keeps moving after you stop.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 79, map_y = 5 WHERE id = 'the-black-scree';
DELETE FROM exits WHERE room_id = 'the-black-scree';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-scree', 'south', 'the-corrie-mouth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-scree', 'east', 'the-drift-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-scree', 'west', 'the-corrie-lip', NULL);

UPDATE rooms SET name = 'The Fallen Block', description = 'A slab the size of a barn came off the wall at some point and landed on its edge, and it has stood that way ever since with a wedge of dry ground under its lean. You can get right in under it. It is out of the wind, out of the wet, out of the sight of anything above, and it is the only such place in this bowl.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 5 WHERE id = 'the-fallen-block';
DELETE FROM exits WHERE room_id = 'the-fallen-block';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-block', 'north', 'the-gully-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-block', 'east', 'the-corrie-floor', NULL);

UPDATE rooms SET name = 'The Corrie Lip', description = 'The rim, on the north side, where the ground rolls over and goes. Standing on it you have the bowl on one hand and the whole open shoulder on the other, and the wind that has been absent down in the corrie is suddenly back and hard. Everything crossing between the two goes over this line.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 4 WHERE id = 'the-corrie-lip';
DELETE FROM exits WHERE room_id = 'the-corrie-lip';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-lip', 'north', 'the-corrie-rim', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-lip', 'south', 'the-gully-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-lip', 'east', 'the-black-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-lip', 'west', 'the-brink', NULL);

UPDATE rooms SET name = 'The Water Lip', description = 'The one place the lochan lets anything out: a notch in the rock a yard wide with the water going over it flat and silent and then falling out of sight. There is no noise from it at all until you look over, and then there is, a long way down.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 81, map_y = 7 WHERE id = 'the-water-lip';
DELETE FROM exits WHERE room_id = 'the-water-lip';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-lip', 'north', 'the-back-wall', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-lip', 'west', 'the-lochan-shore', NULL);

UPDATE rooms SET name = 'The Hanging Step', description = 'A shelf running out from the corner of the back wall, wide enough to walk and narrowing as it goes, carrying you out onto the face above the drop. It is the way out of the bowl that is not the way you came in. It does not feel like one for the first hundred yards.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 82, map_y = 6 WHERE id = 'the-hanging-step';
DELETE FROM exits WHERE room_id = 'the-hanging-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-step', 'south', 'the-lower-band', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-step', 'west', 'the-back-wall', NULL);

UPDATE rooms SET name = 'The Corrie Rim', description = 'The very edge of the bowl, a knife of turf and stone with the corrie on one side and the shoulder falling away on the other, and about two strides of level ground to do it on. Both drops are serious. The wind cannot decide which way it is going through here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 3 WHERE id = 'the-corrie-rim';
DELETE FROM exits WHERE room_id = 'the-corrie-rim';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-rim', 'north', 'the-north-corrie', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-corrie-rim', 'south', 'the-corrie-lip', NULL);

UPDATE rooms SET name = 'The Upper Drift', description = 'Where the snowfield thins to a tongue and gives up, in a run of wet grit and old grey ice with stones sitting proud of it, each one in its own little melted cup. Everything on the surface here arrived from above and is waiting for the ice to let it down.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 82, map_y = 5 WHERE id = 'the-upper-drift';
DELETE FROM exits WHERE room_id = 'the-upper-drift';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-drift', 'north', 'the-melt-runnel', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-drift', 'west', 'the-old-snow', NULL);

UPDATE rooms SET name = 'The Pass Head', description = 'Out of the bealach and onto the shoulder proper, and the whole north side of the mountain arrives at once: a long bare rise going up to a level skyline, with nothing on it. No rock big enough to shelter behind, no dip, no cover of any kind. Anything up here can see you and you can see it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 3 WHERE id = 'the-pass-head';
DELETE FROM exits WHERE room_id = 'the-pass-head';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pass-head', 'east', 'the-shoulder-walk', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pass-head', 'down', 'the-bealach', NULL);

UPDATE rooms SET name = 'The Shoulder Walk', description = 'The easy line along the shoulder, on ground cropped to nothing and firm as a road, which is the one gift this side of the mountain gives. It is also completely exposed for its entire length. Both of those are the same fact.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 3 WHERE id = 'the-shoulder-walk';
DELETE FROM exits WHERE room_id = 'the-shoulder-walk';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-walk', 'south', 'the-shoulder-drop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-walk', 'east', 'the-wind-scour', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-walk', 'west', 'the-pass-head', NULL);

UPDATE rooms SET name = 'The Wind Scour', description = 'The turf has been stripped off in a long patch, the way skin comes off, leaving bare gravel with the roots of what used to grow here still showing at the torn edges. The wind did this. It is still doing it, and the edge of the scour is a little further out every year.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 2 WHERE id = 'the-wind-scour';
DELETE FROM exits WHERE room_id = 'the-wind-scour';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-scour', 'north', 'the-wind-lane', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-scour', 'south', 'the-north-corrie', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-scour', 'east', 'the-stone-stripes', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-scour', 'west', 'the-shoulder-walk', NULL);

UPDATE rooms SET name = 'The Stone Stripes', description = 'The ground here has sorted itself into long parallel lines of stone running straight down the slope, with fine gravel between them, as regular as ploughing and going on for hundreds of yards. Frost did it, over a very long time, and it will keep doing it. There is no ploughman.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 2 WHERE id = 'the-stone-stripes';
DELETE FROM exits WHERE room_id = 'the-stone-stripes';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-stripes', 'north', 'the-blown-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-stripes', 'south', 'the-snow-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-stripes', 'east', 'the-frost-shatter', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-stripes', 'west', 'the-wind-scour', NULL);

UPDATE rooms SET name = 'The Frost Shatter', description = 'Rock broken into angular plates by nothing but water getting in and freezing, over and over, until the whole surface is a rubble of fragments still lying where they cracked apart. You can fit pieces back together with your hands. Nothing has moved them; they simply came to bits in place.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 79, map_y = 2 WHERE id = 'the-frost-shatter';
DELETE FROM exits WHERE room_id = 'the-frost-shatter';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-shatter', 'north', 'the-bare-plateau', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-shatter', 'south', 'the-cold-face', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-shatter', 'east', 'the-high-cairn', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-shatter', 'west', 'the-stone-stripes', NULL);

UPDATE rooms SET name = 'The High Cairn', description = 'The last cairn. Four courses of flat stone, the same as the ones down on the shoulder at the foot, set in the same careful way — and beyond it, in every direction, there is not another. Whoever built this line built it to here and then either turned back or did not need it any more. The stones are seated. It has not fallen in a very long time.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 80, map_y = 2 WHERE id = 'the-high-cairn';
DELETE FROM exits WHERE room_id = 'the-high-cairn';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-cairn', 'north', 'the-flat-top', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-cairn', 'south', 'the-plateau-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-cairn', 'west', 'the-frost-shatter', NULL);

UPDATE rooms SET name = 'The Shoulder Drop', description = 'The shoulder''s south edge, where the level ground ends and the whole side falls away into the corrie in one sweep of grass and scree. You can sit here with your legs over and see the lochan directly below, small and black and completely still. A ramp comes up onto the edge from the west, tilted and narrow, and it is not a thing you would notice from above.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 75, map_y = 2 WHERE id = 'the-shoulder-drop';
DELETE FROM exits WHERE room_id = 'the-shoulder-drop';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-drop', 'north', 'the-shoulder-walk', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-drop', 'east', 'the-north-corrie', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-drop', 'west', 'the-slant', NULL);

UPDATE rooms SET name = 'The North Corrie', description = 'A second, smaller bowl bitten out of the shoulder''s flank, holding nothing but shadow and a floor of wet stone. The sun reaches it for perhaps an hour in high summer. It is a cold place to walk through and a colder one to be in when the light goes off it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 76, map_y = 2 WHERE id = 'the-north-corrie';
DELETE FROM exits WHERE room_id = 'the-north-corrie';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-corrie', 'north', 'the-wind-scour', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-corrie', 'south', 'the-corrie-rim', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-corrie', 'east', 'the-snow-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-corrie', 'west', 'the-shoulder-drop', NULL);

UPDATE rooms SET name = 'The Snow Gully', description = 'A steep groove holding a tongue of hard old snow that runs a good way up the slope, blue-white and grooved down its length where meltwater has cut it. It is the fast way up if you have something to cut steps with and the fast way down if you do not.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 79, map_y = 3 WHERE id = 'the-snow-gully';
DELETE FROM exits WHERE room_id = 'the-snow-gully';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-gully', 'north', 'the-stone-stripes', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-gully', 'east', 'the-cold-face', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-gully', 'west', 'the-north-corrie', NULL);

UPDATE rooms SET name = 'The Cold Face', description = 'North-facing rock, wet at all hours, with a black film on it that never dries and a fringe of ice at the top of every ledge for most of the year. Nothing grows on it but a rusty lichen that comes off on your palms. It is markedly colder here than fifty yards either side.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 79, map_y = 4 WHERE id = 'the-cold-face';
DELETE FROM exits WHERE room_id = 'the-cold-face';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-face', 'north', 'the-frost-shatter', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-face', 'east', 'the-plateau-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-face', 'west', 'the-snow-gully', NULL);

UPDATE rooms SET name = 'The Plateau Edge', description = 'Where the shoulder''s top flattens out and stops being a slope at all, at a rim you can walk right up to without noticing you have arrived. Behind you the ground is level. In front of it there is a great deal of air and then the corrie floor.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 80, map_y = 3 WHERE id = 'the-plateau-edge';
DELETE FROM exits WHERE room_id = 'the-plateau-edge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plateau-edge', 'north', 'the-high-cairn', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plateau-edge', 'east', 'the-cold-shadow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plateau-edge', 'west', 'the-cold-face', NULL);

UPDATE rooms SET name = 'The Flat Top', description = 'Level ground, genuinely level, a plain of frost-shattered stone lying to the horizon with the sky sitting on it. There is no reference for distance up here and nothing to judge scale against, and something a hundred yards off and something a mile off look exactly alike.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 80, map_y = 1 WHERE id = 'the-flat-top';
DELETE FROM exits WHERE room_id = 'the-flat-top';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flat-top', 'south', 'the-high-cairn', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flat-top', 'west', 'the-bare-plateau', NULL);

UPDATE rooms SET name = 'The Bare Plateau', description = 'Stone pavement with a skin of gravel over it and about one plant to the square yard, each one flattened to a cushion and hard to the touch. This is what the top of the world is: not dramatic, just extremely poor. Everything here is small on purpose.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 79, map_y = 1 WHERE id = 'the-bare-plateau';
DELETE FROM exits WHERE room_id = 'the-bare-plateau';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-plateau', 'south', 'the-frost-shatter', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-plateau', 'east', 'the-flat-top', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-plateau', 'west', 'the-blown-ground', NULL);

UPDATE rooms SET name = 'The Blown Ground', description = 'The gravel here has been sorted by wind rather than frost, into a rippled surface like the bottom of a stream, with the fine stuff gone entirely and only the pieces too heavy to lift left behind. There is no shelter within sight in any direction, and you can feel exactly how much that matters.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 1 WHERE id = 'the-blown-ground';
DELETE FROM exits WHERE room_id = 'the-blown-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blown-ground', 'south', 'the-stone-stripes', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blown-ground', 'east', 'the-bare-plateau', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blown-ground', 'west', 'the-wind-lane', NULL);

UPDATE rooms SET name = 'The Wind Lane', description = 'A shallow trough across the plateau that the wind uses and has widened by using, so that the air in it moves visibly faster than the air on either side. Grit travels along it at ankle height in a continuous low stream. Standing across it is like standing in a river.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 1 WHERE id = 'the-wind-lane';
DELETE FROM exits WHERE room_id = 'the-wind-lane';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-lane', 'south', 'the-wind-scour', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-lane', 'east', 'the-blown-ground', NULL);

UPDATE rooms SET name = 'The Lower Band', description = 'The face is built in horizontal bands — a wall of rock, a ledge of grass, a wall, a ledge — and this is the bottom one, a shelf a few strides wide running away east under an overhang. The ledges are the only walking there is on this side, and they do not connect where you want them to.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 82, map_y = 7 WHERE id = 'the-lower-band';
DELETE FROM exits WHERE room_id = 'the-lower-band';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-band', 'north', 'the-hanging-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-band', 'east', 'the-terrace', NULL);

UPDATE rooms SET name = 'The Terrace', description = 'A wide grass ledge with the wall above and the wall below, level and green and improbably pleasant, going for two hundred yards and then simply stopping at a corner. Everything up here that eats grass comes to these, and everything that eats those knows it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 83, map_y = 7 WHERE id = 'the-terrace';
DELETE FROM exits WHERE room_id = 'the-terrace';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace', 'north', 'the-ledge-walk', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace', 'east', 'the-broken-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace', 'west', 'the-lower-band', NULL);

UPDATE rooms SET name = 'The Ledge Walk', description = 'The ledge narrows to a foot''s width round a rib of rock, with a good hold at chest height for the six paces that matter and nothing at all below. It is not difficult. It is only difficult if you think about it, which is a distinction the mountain does not make and you will.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 83, map_y = 6 WHERE id = 'the-ledge-walk';
DELETE FROM exits WHERE room_id = 'the-ledge-walk';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ledge-walk', 'north', 'the-chimney-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ledge-walk', 'south', 'the-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ledge-walk', 'east', 'the-second-band', NULL);

UPDATE rooms SET name = 'The Second Band', description = 'The next shelf up, drier and stonier than the one below it, with the wall behind it undercut enough to sit in out of the rain. There are droppings along the back of it in a line, all along, from something that walks this ledge regularly and rests in the same places every time.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 6 WHERE id = 'the-second-band';
DELETE FROM exits WHERE room_id = 'the-second-band';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-band', 'north', 'the-chimney', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-band', 'south', 'the-broken-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-band', 'east', 'the-third-band', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-band', 'west', 'the-ledge-walk', NULL);

UPDATE rooms SET name = 'The Broken Terrace', description = 'This shelf has come away in sections, so that what is left is a series of grass islands with gaps of steep bare rock between them, each gap a stride or a scramble. It was one continuous ledge once. You can see where it went, in a fan of turf and rubble on the ground far below.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 7 WHERE id = 'the-broken-terrace';
DELETE FROM exits WHERE room_id = 'the-broken-terrace';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-terrace', 'north', 'the-second-band', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-terrace', 'east', 'the-slab-nose', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-terrace', 'west', 'the-terrace', NULL);

UPDATE rooms SET name = 'The Chimney Foot', description = 'The bottom of a vertical cleft splitting the wall from the ledge to the skyline, wide enough at the base to walk into and narrowing to a slot above. It is dark inside and there is a permanent trickle down the back of it. This is the way up through the bands and there is no other.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 83, map_y = 5 WHERE id = 'the-chimney-foot';
DELETE FROM exits WHERE room_id = 'the-chimney-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney-foot', 'north', 'the-snow-bed', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney-foot', 'south', 'the-ledge-walk', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney-foot', 'east', 'the-chimney', NULL);

UPDATE rooms SET name = 'The Chimney', description = 'Inside the cleft: two walls a body''s width apart, wet, and holds enough to get up if you brace your back on one and your boots on the other. Somebody''s hands have polished the two obvious holds smooth. Somebody, at some point, more than once.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 5 WHERE id = 'the-chimney';
DELETE FROM exits WHERE room_id = 'the-chimney';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney', 'south', 'the-second-band', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney', 'east', 'the-airy-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chimney', 'west', 'the-chimney-foot', NULL);

UPDATE rooms SET name = 'The Third Band', description = 'The highest of the shelves and the narrowest, with a great deal of nothing below it and the summit crags starting directly above. The grass on it is finer and shorter than the ledges below and there is very little of it. Everything up here is running out of everything.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 85, map_y = 6 WHERE id = 'the-third-band';
DELETE FROM exits WHERE room_id = 'the-third-band';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-band', 'north', 'the-airy-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-band', 'south', 'the-slab-nose', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-band', 'east', 'the-band-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-band', 'west', 'the-second-band', NULL);

UPDATE rooms SET name = 'The Slab Nose', description = 'A prow of clean rock pushing out from the face where the bands run into it and stop, with the ledge dying away to nothing on either side. Round the front of it there is a step across a gap onto ground you cannot see until you are committed to it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 85, map_y = 7 WHERE id = 'the-slab-nose';
DELETE FROM exits WHERE room_id = 'the-slab-nose';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slab-nose', 'north', 'the-third-band', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slab-nose', 'west', 'the-broken-terrace', NULL);

UPDATE rooms SET name = 'The Airy Step', description = 'Two strides on a ledge the width of a boot, with the wall pushing your shoulder out and six hundred feet under your heels, and good holds the whole way. It is genuinely safe and it does not feel remotely safe. Ravens use the ledge above and drop things off it, occasionally, on purpose.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 85, map_y = 5 WHERE id = 'the-airy-step';
DELETE FROM exits WHERE room_id = 'the-airy-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-airy-step', 'north', 'the-late-field', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-airy-step', 'south', 'the-third-band', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-airy-step', 'east', 'the-rake', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-airy-step', 'west', 'the-chimney', NULL);

UPDATE rooms SET name = 'The Band End', description = 'The bands run out here against a buttress that cuts across them all, and the shelves simply end at it, one above another, like shelves in a broken cupboard. There is no way round at this level. Everything that comes along these ledges turns here, or goes up.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 86, map_y = 6 WHERE id = 'the-band-end';
DELETE FROM exits WHERE room_id = 'the-band-end';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-band-end', 'north', 'the-rake', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-band-end', 'west', 'the-third-band', NULL);

UPDATE rooms SET name = 'The Rake', description = 'A long ramp of broken ground running diagonally up the face from the end of the bands, loose in places and grassy in others and always steeper than it looks from below. It is the mountain''s one concession on this side. It goes somewhere, which is more than the rest of this face does.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 86, map_y = 5 WHERE id = 'the-rake';
DELETE FROM exits WHERE room_id = 'the-rake';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rake', 'south', 'the-band-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rake', 'west', 'the-airy-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rake', 'up', 'the-rake-top', NULL);

UPDATE rooms SET name = 'The Snow Bed', description = 'A field of old snow lying in a hollow that faces away from every hour of sun there is, dirty on top, dense as packed sand underneath, and cold enough to feel from ten feet off. It has been getting a little smaller for a hundred years and it has not gone.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 83, map_y = 4 WHERE id = 'the-snow-bed';
DELETE FROM exits WHERE room_id = 'the-snow-bed';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-bed', 'north', 'the-moat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-bed', 'south', 'the-chimney-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-bed', 'east', 'the-firn', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-bed', 'west', 'the-melt-runnel', NULL);

UPDATE rooms SET name = 'The Firn', description = 'Snow gone halfway to ice: grainy, granular, so hard that it takes a heel to mark it, and blue where a crack goes down into it. Somewhere below this it stops being anything you could call snow. Nobody has ever needed to find out how far down that is.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 4 WHERE id = 'the-firn';
DELETE FROM exits WHERE room_id = 'the-firn';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-firn', 'north', 'the-grey-ice', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-firn', 'east', 'the-late-field', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-firn', 'west', 'the-snow-bed', NULL);

UPDATE rooms SET name = 'The Melt Runnel', description = 'A channel cut into the snow itself by its own melting, waist deep and smooth-sided and running with clear water all day and nothing at all by first light. Follow it and it goes under the field and you cannot. The noise of water underneath carries for a good way.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 82, map_y = 4 WHERE id = 'the-melt-runnel';
DELETE FROM exits WHERE room_id = 'the-melt-runnel';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-runnel', 'north', 'the-cold-shadow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-runnel', 'south', 'the-upper-drift', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-runnel', 'east', 'the-snow-bed', NULL);

UPDATE rooms SET name = 'The Grey Ice', description = 'Not snow any more: a lens of grey bubbled ice standing proud of the slope, with grit frozen into it in layers you can count. Each dark line is a summer. There are more of them than seems reasonable and they get thinner toward the bottom.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 3 WHERE id = 'the-grey-ice';
DELETE FROM exits WHERE room_id = 'the-grey-ice';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-ice', 'north', 'the-shattered-crown', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-ice', 'south', 'the-firn', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-ice', 'east', 'the-white-hollow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-ice', 'west', 'the-moat', NULL);

UPDATE rooms SET name = 'The Moat', description = 'The gap between the snowfield and the rock behind it, where the warmth coming off the stone has melted a trench you could lose a horse in — vertical snow on one side, wet rock on the other, and no telling how deep the bottom is under the fallen stuff bridging it. You go round. Everything goes round.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 83, map_y = 3 WHERE id = 'the-moat';
DELETE FROM exits WHERE room_id = 'the-moat';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moat', 'north', 'the-snow-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moat', 'south', 'the-snow-bed', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moat', 'east', 'the-grey-ice', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moat', 'west', 'the-cold-shadow', NULL);

UPDATE rooms SET name = 'The Cold Shadow', description = 'Ground that has not had direct sun on it within living memory, walled to the south and floored with damp grey rubble and a moss that is nearly black. The temperature drops as you cross into it, sharply, in one step, and your breath shows.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 82, map_y = 3 WHERE id = 'the-cold-shadow';
DELETE FROM exits WHERE room_id = 'the-cold-shadow';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shadow', 'north', 'the-old-drift', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shadow', 'south', 'the-melt-runnel', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shadow', 'east', 'the-moat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shadow', 'west', 'the-plateau-edge', NULL);

UPDATE rooms SET name = 'The Old Drift', description = 'A drift that formed in the lee of the crest and has been renewed every winter for so long that it has become a permanent feature of the mountain, with its own shape and its own edges and a hard scoured hollow in front of it. The wind builds it in the same place, the same way, every year.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 82, map_y = 2 WHERE id = 'the-old-drift';
DELETE FROM exits WHERE room_id = 'the-old-drift';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-drift', 'south', 'the-cold-shadow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-drift', 'east', 'the-snow-edge', NULL);

UPDATE rooms SET name = 'The Snow Edge', description = 'The lip where the drift breaks off, overhanging its own undercut face in a curl you could walk out onto without knowing it was there. It has broken before: there are blocks the size of carts lying below it, rounded and grey and slowly going.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 83, map_y = 2 WHERE id = 'the-snow-edge';
DELETE FROM exits WHERE room_id = 'the-snow-edge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-edge', 'south', 'the-moat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-edge', 'east', 'the-shattered-crown', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-edge', 'west', 'the-old-drift', NULL);

UPDATE rooms SET name = 'The Shattered Crown', description = 'The crest above the snow, a comb of rock split into standing plates by frost, leaning apart with gaps between them you can see the sky through. It looks deliberate from below, like something built and then ruined. It is neither.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 2 WHERE id = 'the-shattered-crown';
DELETE FROM exits WHERE room_id = 'the-shattered-crown';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shattered-crown', 'south', 'the-grey-ice', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shattered-crown', 'west', 'the-snow-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shattered-crown', 'north', 'the-crown-step', NULL);

UPDATE rooms SET name = 'The White Hollow', description = 'A scoop of rock behind the ice with dry gravel in the bottom of it, sheltered from three sides and floored with a drift of small bones and old feathers a foot deep in places. Nothing here died today. Something has been carrying its dinner in here for a very, very long time.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 85, map_y = 3 WHERE id = 'the-white-hollow';
DELETE FROM exits WHERE room_id = 'the-white-hollow';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-hollow', 'south', 'the-late-field', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-hollow', 'west', 'the-grey-ice', NULL);

UPDATE rooms SET name = 'The Late Field', description = 'The last of the snow, in a thin sheet holding on in the shade of the crest, going soft at the edges and undercut to a lace of white over black stone. In another month it will be gone. It will be back before it is properly gone.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 85, map_y = 4 WHERE id = 'the-late-field';
DELETE FROM exits WHERE room_id = 'the-late-field';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-late-field', 'north', 'the-white-hollow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-late-field', 'south', 'the-airy-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-late-field', 'west', 'the-firn', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-late-field', 'up', 'the-cold-ramp', NULL);

UPDATE rooms SET name = 'The Sun Shoulder', description = 'Round the corner and everything changes: the wind drops, the rock is warm to the hand, and the ground goes from grey to brown and red. It is the same mountain and it is not the same mountain. All the living on this hill that can choose is on this side of it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 78, map_y = 13 WHERE id = 'the-sun-shoulder';
DELETE FROM exits WHERE room_id = 'the-sun-shoulder';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-shoulder', 'east', 'the-heather-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-shoulder', 'down', 'the-south-shoulder', NULL);

UPDATE rooms SET name = 'The Heather Shelf', description = 'Old heather, woody at the base and deep enough to hide anything lying down in it, growing on a broad terrace that runs along the flank at a comfortable angle for the first time since the shore. It smells of resin in the sun. Walking through it is loud and there is no way to make it not.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 79, map_y = 11 WHERE id = 'the-heather-shelf';
DELETE FROM exits WHERE room_id = 'the-heather-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heather-shelf', 'north', 'the-rowan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heather-shelf', 'east', 'the-dry-corrie', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heather-shelf', 'west', 'the-sun-shoulder', NULL);

UPDATE rooms SET name = 'The Dry Corrie', description = 'A bowl the same shape as the one on the cold side and nothing at all like it: no water, no snow, a floor of dry grass and gravel, and the whole thing holding the afternoon heat like a wall. Things come here to lie up. You can see where, and the grass is still flat.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 80, map_y = 11 WHERE id = 'the-dry-corrie';
DELETE FROM exits WHERE room_id = 'the-dry-corrie';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-corrie', 'north', 'the-deer-lawn-high', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-corrie', 'south', 'the-hidden-burn', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-corrie', 'east', 'the-warm-slabs', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-corrie', 'west', 'the-heather-shelf', NULL);

UPDATE rooms SET name = 'The Warm Slabs', description = 'Tilted sheets of bare rock that take the sun all day and hold it well past dark, with the heat coming up off them in the evening and everything cold-blooded on this mountain arranged on them accordingly. Step carefully. Some of what is on the rock is exactly the colour of the rock.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 81, map_y = 11 WHERE id = 'the-warm-slabs';
DELETE FROM exits WHERE room_id = 'the-warm-slabs';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-slabs', 'north', 'the-wallow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-slabs', 'south', 'the-cut', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-slabs', 'east', 'the-basking-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-slabs', 'west', 'the-dry-corrie', NULL);

UPDATE rooms SET name = 'The Basking Stone', description = 'One flat boulder standing clear of the slope, worn shiny across the top of it, and warmer than the air by a noticeable margin from the moment the sun gets round to it. Something big lies on this. The wear on it is not weather.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 82, map_y = 11 WHERE id = 'the-basking-stone';
DELETE FROM exits WHERE room_id = 'the-basking-stone';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-stone', 'north', 'the-thin-turf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-stone', 'south', 'the-pothole', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-stone', 'east', 'the-broken-ground-high', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-stone', 'west', 'the-warm-slabs', NULL);

UPDATE rooms SET name = 'The Deer Lawn', description = 'A patch of short bright green grass in the middle of the heather, kept that way by being eaten to the root every day for centuries. It is the best few hundred yards of grazing above the treeline and it is entirely surrounded by ground you cannot see through. Everything comes here. Everything knows everything comes here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 80, map_y = 10 WHERE id = 'the-deer-lawn-high';
DELETE FROM exits WHERE room_id = 'the-deer-lawn-high';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-lawn-high', 'south', 'the-dry-corrie', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-lawn-high', 'east', 'the-wallow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-lawn-high', 'west', 'the-rowan', NULL);

UPDATE rooms SET name = 'The Wallow', description = 'A hollow of black peaty mud churned to soup and stinking, with the heather round it broken down and the mud thrown up the stems for a yard in every direction. Deer roll in this in the summer to get the flies off. It has been used this morning.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 81, map_y = 10 WHERE id = 'the-wallow';
DELETE FROM exits WHERE room_id = 'the-wallow';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wallow', 'south', 'the-warm-slabs', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wallow', 'east', 'the-thin-turf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wallow', 'west', 'the-deer-lawn-high', NULL);

UPDATE rooms SET name = 'The Thin Turf', description = 'Grass hanging on over rock with barely a finger of soil under it, so that whole sheets of it lift at the edges where feet have caught them and the rock shows through in patches like a worn coat. It is drying out. It has been drying out for a long time and it is nearly done.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 82, map_y = 10 WHERE id = 'the-thin-turf';
DELETE FROM exits WHERE room_id = 'the-thin-turf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-turf', 'south', 'the-basking-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-turf', 'east', 'the-gravel-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-turf', 'west', 'the-wallow', NULL);

UPDATE rooms SET name = 'The Rowan', description = 'One rowan tree growing out of a cleft in the rock, the only tree above the shore and by some distance the most improbable living thing on this mountain, with its roots gone down the crack and its head bent permanently downhill by the wind. Nothing planted it. A bird ate a berry somewhere lower and sat here, once, and that is the entire history of the only tree on this mountain.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 79, map_y = 10 WHERE id = 'the-rowan';
DELETE FROM exits WHERE room_id = 'the-rowan';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rowan', 'south', 'the-heather-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rowan', 'east', 'the-deer-lawn-high', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rowan', 'west', 'the-wedge', NULL);

UPDATE rooms SET name = 'The Gravel Shelf', description = 'A wide terrace of loose sun-bleached gravel with almost nothing growing in it, hot underfoot by noon and completely bare of cover. Crossing it you are visible from the whole of the flank above, and there is no faster way across than walking.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 83, map_y = 10 WHERE id = 'the-gravel-shelf';
DELETE FROM exits WHERE room_id = 'the-gravel-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-shelf', 'south', 'the-broken-ground-high', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-shelf', 'east', 'the-hot-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-shelf', 'west', 'the-thin-turf', NULL);

UPDATE rooms SET name = 'The Broken Ground', description = 'Blocks and hollows and small cliffs three feet high, all through each other with no pattern, so that you are constantly stepping up or down and can never see more than twenty yards. It is exhausting and it is the best cover on this side of the hill, and those two facts are why things use it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 83, map_y = 11 WHERE id = 'the-broken-ground-high';
DELETE FROM exits WHERE room_id = 'the-broken-ground-high';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-ground-high', 'north', 'the-gravel-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-ground-high', 'east', 'the-sun-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-ground-high', 'west', 'the-basking-stone', NULL);

UPDATE rooms SET name = 'The Sun Gully', description = 'A dry gully running down the flank, floored with baked gravel and walled with warm rock, holding the heat like an oven and utterly still. Nothing moves in here in the middle of the day. Everything moves in here at dusk.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 11 WHERE id = 'the-sun-gully';
DELETE FROM exits WHERE room_id = 'the-sun-gully';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-gully', 'north', 'the-hot-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-gully', 'east', 'the-resurgence', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-gully', 'west', 'the-broken-ground-high', NULL);

UPDATE rooms SET name = 'The Hot Scree', description = 'Scree on the sun side, pale and dry and shifting, with the heat coming off it in a shimmer that makes the ground above look like it is moving. It is hard to judge anything through that. Things standing still in it are very hard to see at all.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 10 WHERE id = 'the-hot-scree';
DELETE FROM exits WHERE room_id = 'the-hot-scree';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hot-scree', 'south', 'the-sun-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hot-scree', 'west', 'the-gravel-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hot-scree', 'up', 'the-hot-ledge', NULL);

UPDATE rooms SET name = 'The Hidden Burn', description = 'Water running under the heather rather than through it, audible the whole length of this hollow and visible almost nowhere, so that you walk along the sound of a stream you cannot find. Where it does show it is a hand''s width across and a foot deep and very fast.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 80, map_y = 12 WHERE id = 'the-hidden-burn';
DELETE FROM exits WHERE room_id = 'the-hidden-burn';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hidden-burn', 'north', 'the-dry-corrie', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hidden-burn', 'east', 'the-cut', NULL);

UPDATE rooms SET name = 'The Cut', description = 'The burn has sawn itself a slot four feet deep and two wide in the solid rock, straight-sided, with the water at the bottom of it out of reach. You can stand astride it. Something has fallen in it further along — there is wool caught on the lip and a dark shape wedged below.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 81, map_y = 12 WHERE id = 'the-cut';
DELETE FROM exits WHERE room_id = 'the-cut';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut', 'north', 'the-warm-slabs', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut', 'east', 'the-pothole', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut', 'west', 'the-hidden-burn', NULL);

UPDATE rooms SET name = 'The Pothole', description = 'A shaft in the bed of the cut, round and smooth and drilled straight down by a single stone turning in it for however long that takes, with the whole burn going into it and no sound of it landing. The stone that did the drilling is presumably still down there, still turning.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 82, map_y = 12 WHERE id = 'the-pothole';
DELETE FROM exits WHERE room_id = 'the-pothole';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pothole', 'north', 'the-basking-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pothole', 'east', 'the-sink', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pothole', 'west', 'the-cut', NULL);

UPDATE rooms SET name = 'The Sink', description = 'The burn goes underground here, entirely, into a gap under a jammed boulder, and the streambed below it is dry gravel with dry weed lying combed along it. The change happens in one stride: water, then no water, and the noise going down and away under your feet.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 83, map_y = 12 WHERE id = 'the-sink';
DELETE FROM exits WHERE room_id = 'the-sink';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sink', 'east', 'the-dry-gorge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sink', 'west', 'the-pothole', NULL);

UPDATE rooms SET name = 'The Dry Gorge', description = 'A gorge with no river in it: forty feet deep, walls scoured smooth and undercut, potholes drilled in the floor and dry to the bottom of them, and old flood-wrack jammed in the crevices well above your head. It is doing nothing at all today. It has done a great deal.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 12 WHERE id = 'the-dry-gorge';
DELETE FROM exits WHERE room_id = 'the-dry-gorge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-gorge', 'east', 'the-upper-force', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-gorge', 'west', 'the-sink', NULL);

UPDATE rooms SET name = 'The Resurgence', description = 'The water comes back out of the hill through a low arch, at pressure, cold enough to take your breath, having gone in half a mile back and a hundred feet higher. Nothing that goes into the sink has ever been seen to come out here. That is worth knowing before you decide the two are connected.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 85, map_y = 11 WHERE id = 'the-resurgence';
DELETE FROM exits WHERE room_id = 'the-resurgence';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-resurgence', 'south', 'the-upper-force', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-resurgence', 'east', 'the-boulder-gate', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-resurgence', 'west', 'the-sun-gully', NULL);

UPDATE rooms SET name = 'The Upper Force', description = 'The reborn burn goes over a lip in a single fall into a bowl of its own making, and the noise fills the whole gorge and comes back off both walls. There is a permanent rainbow in the spray on a good afternoon and there is nothing up here to see it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 85, map_y = 12 WHERE id = 'the-upper-force';
DELETE FROM exits WHERE room_id = 'the-upper-force';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-force', 'north', 'the-resurgence', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-force', 'east', 'the-water-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-force', 'west', 'the-dry-gorge', NULL);

UPDATE rooms SET name = 'The Boulder Gate', description = 'Two blocks the size of houses came down at some point and landed leaning against each other, and the gap under them is a doorway with a dry floor and a roof that has held for a very long time. Something has been sleeping in the back of it. There is no smell of anything recent.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 86, map_y = 11 WHERE id = 'the-boulder-gate';
DELETE FROM exits WHERE room_id = 'the-boulder-gate';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-gate', 'south', 'the-water-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-gate', 'east', 'the-mid-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-gate', 'west', 'the-resurgence', NULL);

UPDATE rooms SET name = 'The Water Notch', description = 'A slot the burn goes through where the gorge narrows to a stride, with the rock polished to a shine on both sides at chest height and everything below that scoured white. When it runs high this notch is the whole river and nobody is standing in it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 86, map_y = 12 WHERE id = 'the-water-notch';
DELETE FROM exits WHERE room_id = 'the-water-notch';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-notch', 'north', 'the-boulder-gate', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-notch', 'west', 'the-upper-force', NULL);

UPDATE rooms SET name = 'The Mid Shelf', description = 'A broad shelf where the ground eases at last, with the gorge behind you and the ground above rearing back up into crags and snowfields you have not been near yet. It is a natural place to stop and it feels like one. Everything above this line is steeper than everything below it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 87, map_y = 11 WHERE id = 'the-mid-shelf';
DELETE FROM exits WHERE room_id = 'the-mid-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-shelf', 'west', 'the-boulder-gate', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-shelf', 'up', 'the-shelf-head', NULL);

UPDATE rooms SET name = 'The Slant', description = 'A ramp of turf and broken rock slanting up under the wall of the pass, wide enough to walk and too tilted to stand still on, with the whole weight of the crag leaning over it. Nothing made this and nothing maintains it. It is simply the one line across this face that does not require hands, and everything with four legs on this hill has known that for longer than there have been people to not know it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 74, map_y = 2 WHERE id = 'the-slant';
DELETE FROM exits WHERE room_id = 'the-slant';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slant', 'east', 'the-shoulder-drop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slant', 'down', 'the-wind-notch', NULL);

UPDATE rooms SET name = 'The Wedge', description = 'A block the size of a cart jammed in the fissure at head height, and above it the crack goes on and lets you out on the shelf. Getting past the block is a squeeze with your back on one wall and your boots on the other, and there is nothing to hold on the way through. Something with a wide skull has been through here often enough to polish both sides.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 77, map_y = 11 WHERE id = 'the-wedge';
DELETE FROM exits WHERE room_id = 'the-wedge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wedge', 'east', 'the-rowan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wedge', 'down', 'the-cleft', NULL);

UPDATE rooms SET name = 'The Rake Top', description = 'The ramp runs out onto a shelf under the first of the great ribs, and the ground you have been climbing for two days becomes, in one step, the bottom of something else. The buttress goes up out of the shelf and into cloud about two hundred feet above your head and does not come out of it. You cannot see how much more there is.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 86, map_y = 3 WHERE id = 'the-rake-top';
DELETE FROM exits WHERE room_id = 'the-rake-top';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rake-top', 'north', 'the-rib-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rake-top', 'south', 'the-under-rib', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rake-top', 'east', 'the-first-buttress', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rake-top', 'down', 'the-rake', NULL);

UPDATE rooms SET name = 'The First Buttress', description = 'A rib of rock standing out from the face like a flying wall, sixty feet through at the base and going up until the cloud takes it. It is the first of five you will pass and it is not the largest. Standing at the foot and looking along the line of them is the first time this mountain has shown you its size on purpose.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 87, map_y = 3 WHERE id = 'the-first-buttress';
DELETE FROM exits WHERE room_id = 'the-first-buttress';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-buttress', 'north', 'the-rib-gap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-buttress', 'south', 'the-hanging-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-buttress', 'east', 'the-scoop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-buttress', 'west', 'the-rake-top', NULL);

UPDATE rooms SET name = 'The Rib Foot', description = 'Where the buttress meets the mountain, in a corner choked with everything the rib has shed, some of it very large and none of it settled. There is a constant small trickle of grit down the back of this corner. It stops when you stop moving and starts again a moment later.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 86, map_y = 2 WHERE id = 'the-rib-foot';
DELETE FROM exits WHERE room_id = 'the-rib-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rib-foot', 'south', 'the-rake-top', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rib-foot', 'east', 'the-rib-gap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rib-foot', 'west', 'the-cold-ramp', NULL);

UPDATE rooms SET name = 'The Rib Gap', description = 'A gap between two ribs, floored with jammed blocks and roofed, in one place, by a boulder that fell in and stuck twenty feet up. It is the only shade on this face and the light in it is green. You go through it single file and you go through it quickly.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 87, map_y = 2 WHERE id = 'the-rib-gap';
DELETE FROM exits WHERE room_id = 'the-rib-gap';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rib-gap', 'south', 'the-first-buttress', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rib-gap', 'east', 'the-second-rib', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rib-gap', 'west', 'the-rib-foot', NULL);

UPDATE rooms SET name = 'The Second Rib', description = 'The second buttress, thinner than the first and more broken, with ledges on its flank at intervals all the way up like rungs. Somebody could climb this. Nobody has: there is nothing at the top of it that anybody wanted, and that is the whole reason this mountain has never been climbed.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 88, map_y = 2 WHERE id = 'the-second-rib';
DELETE FROM exits WHERE room_id = 'the-second-rib';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-rib', 'south', 'the-scoop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-rib', 'east', 'the-arete-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-rib', 'west', 'the-rib-gap', NULL);

UPDATE rooms SET name = 'The Scoop', description = 'A rounded hollow bitten out of the face between two ribs, floored with fine grit and completely out of the wind. Things come in here to be out of the weather and the grit is churned with the marks of them. None of the marks were made by anything with two feet.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 88, map_y = 3 WHERE id = 'the-scoop';
DELETE FROM exits WHERE room_id = 'the-scoop';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scoop', 'north', 'the-second-rib', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scoop', 'south', 'the-fall-line', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scoop', 'west', 'the-first-buttress', NULL);

UPDATE rooms SET name = 'The Hanging Scree', description = 'Scree lying at the absolute limit of what scree will lie at, on a shelf with a drop at the bottom of it, so that everything that starts moving here does not stop until it has gone over. Crossing it is a question of not starting anything. It is not steep enough to be frightening and it is exactly steep enough to be fatal.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 87, map_y = 4 WHERE id = 'the-hanging-scree';
DELETE FROM exits WHERE room_id = 'the-hanging-scree';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-scree', 'north', 'the-first-buttress', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-scree', 'east', 'the-fall-line', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-scree', 'west', 'the-under-rib', NULL);

UPDATE rooms SET name = 'The Under-Rib', description = 'A dry cave of sorts where the first buttress overhangs its own foot — not deep, but roofed, floored in soft dust, and with a wall of rock between you and everything above. Nothing can come at you from over your head in here, which is a comfort you did not know you needed until this tier.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 86, map_y = 4 WHERE id = 'the-under-rib';
DELETE FROM exits WHERE room_id = 'the-under-rib';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-rib', 'north', 'the-rake-top', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-rib', 'east', 'the-hanging-scree', NULL);

UPDATE rooms SET name = 'The Fall Line', description = 'The natural line down the face: a shallow trough scoured clean and polished, where everything that comes off the mountain above comes through. It is the fastest way down and the reason you would not stand in it. There is fresh debris at the bottom of the visible section and it was not there yesterday.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 88, map_y = 4 WHERE id = 'the-fall-line';
DELETE FROM exits WHERE room_id = 'the-fall-line';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fall-line', 'north', 'the-scoop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fall-line', 'east', 'the-valley-mouth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fall-line', 'west', 'the-hanging-scree', NULL);

UPDATE rooms SET name = 'The Arete Foot', description = 'The ribs converge and become one, and the one goes up as a wall barely wider than a path with the whole north face falling away on one hand and the whole east face on the other. From here it looks impossible and from the top of it it will look like a path. It is a path. That is what makes it bad.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 89, map_y = 2 WHERE id = 'the-arete-foot';
DELETE FROM exits WHERE room_id = 'the-arete-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arete-foot', 'north', 'the-first-tower', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arete-foot', 'east', 'the-drop-either-side', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arete-foot', 'west', 'the-second-rib', NULL);

UPDATE rooms SET name = 'The First Tower', description = 'A pinnacle on the ridge, thirty feet of standing rock you go round rather than over, on a ledge on the north side that is out of the sun and iced for most of the year. The rock is sound. The ice on it is not, and it is not always where you can see it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 89, map_y = 1 WHERE id = 'the-first-tower';
DELETE FROM exits WHERE room_id = 'the-first-tower';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-tower', 'south', 'the-arete-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-tower', 'east', 'the-notch-of-air', NULL);

UPDATE rooms SET name = 'The Notch of Air', description = 'A gap in the ridge where the rock has failed on both sides at once, leaving a saddle a stride wide with several hundred feet of nothing under each end of the stride. The wind comes up through it from below rather than across it, which is a thing you feel through your boots before you understand it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 90, map_y = 1 WHERE id = 'the-notch-of-air';
DELETE FROM exits WHERE room_id = 'the-notch-of-air';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-notch-of-air', 'north', 'the-arete-walk', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-notch-of-air', 'east', 'the-second-tower', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-notch-of-air', 'west', 'the-first-tower', NULL);

UPDATE rooms SET name = 'The Second Tower', description = 'The larger of the two pinnacles, split from crown to base by a crack you can see daylight through, and leaning. It has been leaning a long time and it will lean a while longer. Going round it puts you on the exposed side for eight paces.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 91, map_y = 1 WHERE id = 'the-second-tower';
DELETE FROM exits WHERE room_id = 'the-second-tower';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-tower', 'north', 'the-bad-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-tower', 'south', 'the-blade', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-tower', 'east', 'the-arete-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-tower', 'west', 'the-notch-of-air', NULL);

UPDATE rooms SET name = 'The Arete Walk', description = 'The ridge at its kindest: four feet wide, level, sound underfoot, and with a view down both faces at once that would be worth the walk if you were able to look at it. In cloud it is simply a strip of rock going into white, with the ground gone from both sides, and the temptation to crawl is considerable and correct.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 90, map_y = 0 WHERE id = 'the-arete-walk';
DELETE FROM exits WHERE room_id = 'the-arete-walk';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arete-walk', 'north', 'the-spur-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arete-walk', 'south', 'the-notch-of-air', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arete-walk', 'east', 'the-bad-step', NULL);

UPDATE rooms SET name = 'The Bad Step', description = 'The ridge narrows to a rib the width of a hand, for about the length of a body, with a step down onto it and a step up off it. There are good holds. It is short. Everything about it is manageable and it has still killed things, because managing it requires a decision and the wind up here makes decisions for you.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 91, map_y = 0 WHERE id = 'the-bad-step';
DELETE FROM exits WHERE room_id = 'the-bad-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bad-step', 'south', 'the-second-tower', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bad-step', 'east', 'the-horns', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bad-step', 'west', 'the-arete-walk', NULL);

UPDATE rooms SET name = 'The Horns', description = 'Two blades of rock standing up off the ridge side by side, of a stone harder than what was round them, left behind when everything softer went. They are the shape the mountain shows from thirty miles away — the thing that makes it recognisable on the horizon — and up close they are two rocks.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 92, map_y = 0 WHERE id = 'the-horns';
DELETE FROM exits WHERE room_id = 'the-horns';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-horns', 'south', 'the-arete-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-horns', 'west', 'the-bad-step', NULL);

UPDATE rooms SET name = 'The Arete End', description = 'The ridge runs into the mountain''s mass and stops being a ridge, in a jumble of broken blocks with the ice beginning just beyond them. Behind you the whole arete goes down and out and disappears into cloud partway. It looks entirely impassable from this end too.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 92, map_y = 1 WHERE id = 'the-arete-end';
DELETE FROM exits WHERE room_id = 'the-arete-end';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arete-end', 'north', 'the-horns', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arete-end', 'east', 'the-neve', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-arete-end', 'west', 'the-second-tower', NULL);

UPDATE rooms SET name = 'The Drop Either Side', description = 'A stretch of the ridge with nothing to hold and nothing to do but walk it, six feet wide and dead level, with the ground simply absent to left and right. It is the safest ten paces on the arete by any measure you could take. It does not feel like it and it never will.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 90, map_y = 2 WHERE id = 'the-drop-either-side';
DELETE FROM exits WHERE room_id = 'the-drop-either-side';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drop-either-side', 'south', 'the-valley-shoulder', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drop-either-side', 'east', 'the-blade', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drop-either-side', 'west', 'the-arete-foot', NULL);

UPDATE rooms SET name = 'The Blade', description = 'The ridge here is a single sheet of rock stood on its edge, weathered to a knife along the top, with the sides falling away smooth and unbroken. You do not walk on the top. There is a line of holds a body''s length down the east side and that is the way past.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 91, map_y = 2 WHERE id = 'the-blade';
DELETE FROM exits WHERE room_id = 'the-blade';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blade', 'north', 'the-second-tower', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blade', 'west', 'the-drop-either-side', NULL);

UPDATE rooms SET name = 'The Valley Mouth', description = 'The ground opens sideways into a valley that has no business being here — a full glen, floor and walls and a stream in the bottom of it, hanging in the side of the mountain with its lower end simply stopping in mid-air above the drop. The stream goes over that end and is gone as spray before it lands.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 89, map_y = 4 WHERE id = 'the-valley-mouth';
DELETE FROM exits WHERE room_id = 'the-valley-mouth';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-valley-mouth', 'south', 'the-outwash', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-valley-mouth', 'east', 'the-hanging-floor', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-valley-mouth', 'west', 'the-fall-line', NULL);

UPDATE rooms SET name = 'The Hanging Floor', description = 'Flat ground, and after two tiers of slope it is disorienting rather than restful: gravel and short grass and braided water, walled a thousand feet on both sides, and level enough to run on. It is the largest flat place on this mountain and there is nothing on it that needs the space.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 90, map_y = 4 WHERE id = 'the-hanging-floor';
DELETE FROM exits WHERE room_id = 'the-hanging-floor';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-floor', 'north', 'the-valley-shoulder', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-floor', 'south', 'the-moraine-loop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-floor', 'east', 'the-upper-lochan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-floor', 'west', 'the-valley-mouth', NULL);

UPDATE rooms SET name = 'The Upper Lochan', description = 'A second lochan, higher and smaller and paler than the one in the corrie below, floored with grey silt that comes up in clouds if anything disturbs it and takes an hour to settle. You can see the bottom, which the lower one never allowed. There is nothing on the bottom.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 91, map_y = 4 WHERE id = 'the-upper-lochan';
DELETE FROM exits WHERE room_id = 'the-upper-lochan';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-lochan', 'north', 'the-north-bank', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-lochan', 'south', 'the-braided-flats', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-lochan', 'east', 'the-far-shore-high', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-lochan', 'west', 'the-hanging-floor', NULL);

UPDATE rooms SET name = 'The Far Shore', description = 'The head end of the water, where the valley''s stream comes in over a fan of its own gravel in a dozen shifting channels. The fan is bare, pale, and completely without cover, and it is a hundred yards across. Everything that crosses this valley crosses here or goes the long way round.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 92, map_y = 4 WHERE id = 'the-far-shore-high';
DELETE FROM exits WHERE room_id = 'the-far-shore-high';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-shore-high', 'north', 'the-south-bank', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-shore-high', 'south', 'the-till', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-shore-high', 'east', 'the-valley-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-shore-high', 'west', 'the-upper-lochan', NULL);

UPDATE rooms SET name = 'The Valley Head', description = 'The back of the hanging valley, walled by a headwall with the ice above it, and the stream coming down that wall in a thread that is blown sideways to nothing halfway. Only about half the water that leaves the top of it arrives at the bottom. The rest goes into the air.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = 4 WHERE id = 'the-valley-head';
DELETE FROM exits WHERE room_id = 'the-valley-head';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-valley-head', 'north', 'the-cloud-base', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-valley-head', 'south', 'the-step-in-the-floor', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-valley-head', 'east', 'the-grey-nothing', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-valley-head', 'west', 'the-far-shore-high', NULL);

UPDATE rooms SET name = 'The Moraine Loop', description = 'A crescent bank of rubble looping across the valley floor, twenty feet high and as regular as an earthwork, marking exactly where something stopped and sat for a long time before going back. It is the tidiest thing on this mountain and nothing tidied it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 90, map_y = 5 WHERE id = 'the-moraine-loop';
DELETE FROM exits WHERE room_id = 'the-moraine-loop';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-loop', 'north', 'the-hanging-floor', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-loop', 'east', 'the-braided-flats', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moraine-loop', 'west', 'the-outwash', NULL);

UPDATE rooms SET name = 'The Outwash', description = 'A plain of sorted sand and gravel where the valley''s water spreads and drops what it is carrying before going over the lip. It is soft walking, the only soft walking up here, and it takes a print beautifully. There are prints in it now, deep, crossing, and larger than a hand.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 89, map_y = 5 WHERE id = 'the-outwash';
DELETE FROM exits WHERE room_id = 'the-outwash';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-outwash', 'north', 'the-valley-mouth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-outwash', 'east', 'the-moraine-loop', NULL);

UPDATE rooms SET name = 'The Braided Flats', description = 'The stream splits into a dozen shallow channels across a bed of pale gravel, each one an inch deep and running fast, rejoining and splitting again. It is loud. Standing in the middle of it you cannot hear anything else at all, and there is no cover in any direction.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 91, map_y = 5 WHERE id = 'the-braided-flats';
DELETE FROM exits WHERE room_id = 'the-braided-flats';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-braided-flats', 'north', 'the-upper-lochan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-braided-flats', 'east', 'the-till', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-braided-flats', 'west', 'the-moraine-loop', NULL);

UPDATE rooms SET name = 'The Till', description = 'Unsorted ground: clay, sand, gravel and boulders all through each other in no order, dumped in a heap and left, with the stream cutting a raw face into one side of it. Things stick out of that face. Bone, mostly, and a good deal of it, all of it very old.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 92, map_y = 5 WHERE id = 'the-till';
DELETE FROM exits WHERE room_id = 'the-till';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-till', 'north', 'the-far-shore-high', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-till', 'east', 'the-step-in-the-floor', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-till', 'west', 'the-braided-flats', NULL);

UPDATE rooms SET name = 'The Step in the Floor', description = 'The valley floor is not one floor: it goes up a rock step forty feet high, worn smooth and rounded, with the stream coming down a groove in it. Above the step there is another flat, and above that another step. The whole valley is a stair for something that was very much larger than the stream.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = 5 WHERE id = 'the-step-in-the-floor';
DELETE FROM exits WHERE room_id = 'the-step-in-the-floor';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-step-in-the-floor', 'north', 'the-valley-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-step-in-the-floor', 'west', 'the-till', NULL);

UPDATE rooms SET name = 'The Valley Shoulder', description = 'The rim of the hanging valley, on the north side, where the flat floor stops and the ground goes up to the arete. From here you can see the whole valley at once, and the drop it hangs above, and the country far below the drop. On a clear hour it is the best view on the mountain. There are perhaps six clear hours a month.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 90, map_y = 3 WHERE id = 'the-valley-shoulder';
DELETE FROM exits WHERE room_id = 'the-valley-shoulder';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-valley-shoulder', 'north', 'the-drop-either-side', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-valley-shoulder', 'south', 'the-hanging-floor', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-valley-shoulder', 'east', 'the-north-bank', NULL);

UPDATE rooms SET name = 'The North Bank', description = 'The shaded side of the valley, under the arete, with the ground stony and the snow lying in patches well into the summer and the grass giving out entirely. Nothing grazes on this side. Things cross it, and they cross it fast.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 91, map_y = 3 WHERE id = 'the-north-bank';
DELETE FROM exits WHERE room_id = 'the-north-bank';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-bank', 'south', 'the-upper-lochan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-bank', 'east', 'the-south-bank', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-bank', 'west', 'the-valley-shoulder', NULL);

UPDATE rooms SET name = 'The South Bank', description = 'The sunny side, which up here means merely that it is not frozen, with a thin grass in the hollows and small flowers flat against the ground in the sheltered spots. There is more living on this bank than on the whole north side of the valley put together, and it is not much.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 92, map_y = 3 WHERE id = 'the-south-bank';
DELETE FROM exits WHERE room_id = 'the-south-bank';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-bank', 'south', 'the-far-shore-high', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-bank', 'east', 'the-cloud-base', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-bank', 'west', 'the-north-bank', NULL);

UPDATE rooms SET name = 'The Cloud Base', description = 'A line across the mountain, sharp enough to walk through in one step, where the air gives up its water and everything above is inside the cloud. Below the line: rock, distance, weather happening elsewhere. Above it: your own hands and about eight feet of grey. The line moves up and down through the day and nobody consults you.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = 3 WHERE id = 'the-cloud-base';
DELETE FROM exits WHERE room_id = 'the-cloud-base';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cloud-base', 'north', 'the-inversion', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cloud-base', 'south', 'the-valley-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cloud-base', 'east', 'the-white-out', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cloud-base', 'west', 'the-south-bank', NULL);

UPDATE rooms SET name = 'The White Out', description = 'Cloud on snow, and the two are the same colour and the same brightness, and the ground and the air stop being different things. You cannot see the slope you are standing on. You find out which way is downhill by falling over, and that is not a joke — it is the recommended method.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = 3 WHERE id = 'the-white-out';
DELETE FROM exits WHERE room_id = 'the-white-out';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-out', 'north', 'the-brocken', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-out', 'south', 'the-grey-nothing', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-out', 'east', 'the-standing-cloud', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-out', 'west', 'the-cloud-base', NULL);

UPDATE rooms SET name = 'The Grey Nothing', description = 'Inside the cloud on bare rock, where there is no horizon, no sky, no ground beyond your boots, and no sound except your own. Distance stops working: something ten feet away and something a mile away look identical, which is to say both look like nothing at all.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = 4 WHERE id = 'the-grey-nothing';
DELETE FROM exits WHERE room_id = 'the-grey-nothing';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-nothing', 'north', 'the-white-out', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-nothing', 'south', 'the-rising-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-nothing', 'east', 'the-cloud-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-nothing', 'west', 'the-valley-head', NULL);

UPDATE rooms SET name = 'The Inversion', description = 'You come up out of the cloud, and it is below you: a floor of white lying flat across the whole country from horizon to horizon, with two or three other summits standing out of it like islands and nothing else in the world existing at all. It is the most beautiful thing anybody up here has ever seen and there has never been anybody up here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = 2 WHERE id = 'the-inversion';
DELETE FROM exits WHERE room_id = 'the-inversion';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-inversion', 'north', 'the-neve', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-inversion', 'south', 'the-cloud-base', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-inversion', 'east', 'the-brocken', NULL);

UPDATE rooms SET name = 'The Brocken', description = 'Standing with the sun behind you and the cloud in front, your own shadow is thrown onto the cloud enormously, with a ring of light round its head, and it moves when you move. Everything about it is explicable. Knowing that does not help as much as you would expect.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = 2 WHERE id = 'the-brocken';
DELETE FROM exits WHERE room_id = 'the-brocken';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brocken', 'north', 'the-ice-fall', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brocken', 'south', 'the-white-out', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brocken', 'east', 'the-clear-window', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brocken', 'west', 'the-inversion', NULL);

UPDATE rooms SET name = 'The Standing Cloud', description = 'Cloud that forms on this shoulder and stays there while the wind goes through it, so that the air is moving hard and the cloud is not moving at all — condensing on one side, evaporating on the other, holding station. It is the same cloud and it is entirely new every few seconds.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = 3 WHERE id = 'the-standing-cloud';
DELETE FROM exits WHERE room_id = 'the-standing-cloud';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-standing-cloud', 'north', 'the-clear-window', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-standing-cloud', 'south', 'the-cloud-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-standing-cloud', 'west', 'the-white-out', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-standing-cloud', 'up', 'the-high-neve', NULL);

UPDATE rooms SET name = 'The Clear Window', description = 'A hollow in the rock that the cloud does not come into, for reasons to do with the shape of it and the way the air turns, so that there is a pocket of clear cold air here with grey walls on every side of it. It is dry and out of the wind and you can see. All three are rare.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = 2 WHERE id = 'the-clear-window';
DELETE FROM exits WHERE room_id = 'the-clear-window';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-clear-window', 'south', 'the-standing-cloud', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-clear-window', 'west', 'the-brocken', NULL);

UPDATE rooms SET name = 'The Cloud Shelf', description = 'A broad terrace on the cloud line, half in and half out, so that one end of it is in weather and the other end is in sun and you can stand with the boundary crossing you. Things lie up at the sunny end. The wet end is where you come in.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = 4 WHERE id = 'the-cloud-shelf';
DELETE FROM exits WHERE room_id = 'the-cloud-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cloud-shelf', 'north', 'the-standing-cloud', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cloud-shelf', 'west', 'the-grey-nothing', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cloud-shelf', 'up', 'the-drift-foot', NULL);

UPDATE rooms SET name = 'The Cloud Foot', description = 'The bottom of the cloud on the south side, where the ground rises out of the shelves and into the grey, and the last of the plants stop within a few strides of each other in a line you could draw. Above this there is nothing green at all on this whole mountain.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = 6 WHERE id = 'the-cloud-foot';
DELETE FROM exits WHERE room_id = 'the-cloud-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cloud-foot', 'north', 'the-rising-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cloud-foot', 'south', 'the-last-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cloud-foot', 'up', 'the-fan-head', NULL);

UPDATE rooms SET name = 'The Rising Ground', description = 'Steepening rock going up into the cloud, with the way ahead visible for ten paces and no further, and the sense the whole time that you are about to come out on top of something. You are not. There is a great deal more of this than there appears to be, precisely because there is nothing to appear.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = 5 WHERE id = 'the-rising-ground';
DELETE FROM exits WHERE room_id = 'the-rising-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rising-ground', 'north', 'the-grey-nothing', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rising-ground', 'south', 'the-cloud-foot', NULL);

UPDATE rooms SET name = 'The Neve', description = 'The top of the ice, where snow has been falling and packing for longer than anything else on this mountain has been happening, in a smooth white field that goes up at an even angle and out of sight. It is firm in the morning and it is not firm in the afternoon and the difference matters entirely.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = 1 WHERE id = 'the-neve';
DELETE FROM exits WHERE room_id = 'the-neve';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-neve', 'north', 'the-blue-wall', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-neve', 'south', 'the-inversion', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-neve', 'east', 'the-ice-fall', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-neve', 'west', 'the-arete-end', NULL);

UPDATE rooms SET name = 'The Ice Fall', description = 'Where the ice goes over a step in the rock beneath it and breaks up doing it, into a chaos of leaning blocks and towers the size of houses, none of them stable and all of them moving slower than you can see. There is a way through. It is not the same way it was last year.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = 1 WHERE id = 'the-ice-fall';
DELETE FROM exits WHERE room_id = 'the-ice-fall';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-fall', 'north', 'the-crevasse-field', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-fall', 'south', 'the-brocken', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-fall', 'west', 'the-neve', NULL);

UPDATE rooms SET name = 'The Crevasse Field', description = 'The ice here is split into parallel cracks running across the slope, some of them a hand''s width and some of them wide enough to lose a horse, and a good many of them roofed over with snow that will hold a hare and will not hold you. There is no way to tell which is which by looking.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = 0 WHERE id = 'the-crevasse-field';
DELETE FROM exits WHERE room_id = 'the-crevasse-field';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crevasse-field', 'north', 'the-rime', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crevasse-field', 'south', 'the-ice-fall', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crevasse-field', 'east', 'the-cornice', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crevasse-field', 'west', 'the-blue-wall', NULL);

UPDATE rooms SET name = 'The Blue Wall', description = 'A face of bare ice twenty feet high where the field has torn away from itself, and it is BLUE — not white, not grey, a deep and genuine blue that gets stronger the further into the crack you look. It is the colour of the pressure it has been under. Water runs down it all day and freezes on it every night.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = 0 WHERE id = 'the-blue-wall';
DELETE FROM exits WHERE room_id = 'the-blue-wall';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-wall', 'north', 'the-ice-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-wall', 'south', 'the-neve', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-wall', 'east', 'the-crevasse-field', NULL);

UPDATE rooms SET name = 'The Bergschrund', description = 'The gap where the moving ice has pulled away from the rock face it sits against, a trench of unknown depth running along the base of the headwall, floored somewhere below with everything that has fallen into it. Cold air comes out of it. So does a faint constant sound of water, from a long way down.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 92, map_y = -1 WHERE id = 'the-bergschrund';
DELETE FROM exits WHERE room_id = 'the-bergschrund';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bergschrund', 'east', 'the-ice-shelf', NULL);

UPDATE rooms SET name = 'The Ice Shelf', description = 'A level bench of old hard ice under the headwall, swept clean by wind and polished, with stones lying on it that came off the wall and are slowly melting themselves into it. Each stone sits in its own shallow bowl. Walking on this needs something on your boots that you do not have.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = -1 WHERE id = 'the-ice-shelf';
DELETE FROM exits WHERE room_id = 'the-ice-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-shelf', 'south', 'the-blue-wall', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-shelf', 'east', 'the-rime', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-shelf', 'west', 'the-bergschrund', NULL);

UPDATE rooms SET name = 'The Rime', description = 'Every surface up here is furred with ice grown sideways into the wind — feathers of it a hand long, all pointing the same way, on the rocks and the ice and the dead things. It builds at a finger''s width an hour in the right conditions. It is beautiful and it is a very direct statement about what the air is doing.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = -1 WHERE id = 'the-rime';
DELETE FROM exits WHERE room_id = 'the-rime';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rime', 'south', 'the-crevasse-field', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rime', 'east', 'the-cold-crest', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rime', 'west', 'the-ice-shelf', NULL);

UPDATE rooms SET name = 'The Cornice', description = 'The wind has built a lip of snow out over the edge of the crest, curling, unsupported, and reaching a good ten feet past where the ground actually stops. From above there is no way to see where the rock ends. From below you can see exactly, and it is nowhere near where you would have walked.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = 0 WHERE id = 'the-cornice';
DELETE FROM exits WHERE room_id = 'the-cornice';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cornice', 'north', 'the-cold-crest', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cornice', 'west', 'the-crevasse-field', NULL);

UPDATE rooms SET name = 'The Cold Crest', description = 'The top of this tier: a crest of rime-covered rock with the ice below on one side and cloud on the other, and above it the mountain going up again into something you cannot see the shape of. This is as far as the ground you understand goes.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = -1 WHERE id = 'the-cold-crest';
DELETE FROM exits WHERE room_id = 'the-cold-crest';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-crest', 'south', 'the-cornice', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-crest', 'west', 'the-rime', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-crest', 'up', 'the-crest-step', NULL);

UPDATE rooms SET name = 'The Crown Step', description = 'Up off the shattered crown onto the spur, in a step of broken plates with the wind arriving the moment you top it. The spur runs away north and east from here, level and bare and about forty feet wide, with nothing on it and a drop on both sides.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 1 WHERE id = 'the-crown-step';
DELETE FROM exits WHERE room_id = 'the-crown-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crown-step', 'south', 'the-shattered-crown', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crown-step', 'east', 'the-north-rib', NULL);

UPDATE rooms SET name = 'The North Rib', description = 'The spur proper: a rib of the mountain running out into the air, wide enough not to be frightening and narrow enough that you can see over both edges without moving. There is no shelter on it anywhere along its length and you can see that from the start of it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 85, map_y = 1 WHERE id = 'the-north-rib';
DELETE FROM exits WHERE room_id = 'the-north-rib';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-rib', 'east', 'the-spur-walk', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-rib', 'west', 'the-crown-step', NULL);

UPDATE rooms SET name = 'The Spur Walk', description = 'Easy level walking on frost-shattered plates that rock and clink under the boot, so that you are audible for a very long way in every direction and cannot help it. The noise is the ground, not you. There is no quiet way to cross this.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 86, map_y = 1 WHERE id = 'the-spur-walk';
DELETE FROM exits WHERE room_id = 'the-spur-walk';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spur-walk', 'east', 'the-spur-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spur-walk', 'west', 'the-north-rib', NULL);

UPDATE rooms SET name = 'The Spur Head', description = 'The spur widens into a head of ground with the tarn beyond it and the plateau beyond that, and for the first time in a while there is more than one direction to go. It is also the first place on the spur that anything could be standing without your having seen it from half a mile back.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 87, map_y = 1 WHERE id = 'the-spur-head';
DELETE FROM exits WHERE room_id = 'the-spur-head';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spur-head', 'north', 'the-wind-scoop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spur-head', 'east', 'the-cold-plateau', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spur-head', 'west', 'the-spur-walk', NULL);

UPDATE rooms SET name = 'The Wind Scoop', description = 'A hollow blown out of the ground on the lee side, bowl-shaped and floored with the coarse gravel the wind could not lift, and dead calm in the middle of a gale. Everything that lives up here knows this hollow. There is a good deal of sign in it and some of it is fresh.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 87, map_y = 0 WHERE id = 'the-wind-scoop';
DELETE FROM exits WHERE room_id = 'the-wind-scoop';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-scoop', 'south', 'the-spur-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-scoop', 'east', 'the-lee-drift', NULL);

UPDATE rooms SET name = 'The Cold Plateau', description = 'Level ground at a height where level ground has no right to exist, floored in shattered stone with ice in the joints of it that never entirely goes. The plants are lichen and one cushion moss and nothing else. It goes on for further than you would like.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 88, map_y = 1 WHERE id = 'the-cold-plateau';
DELETE FROM exits WHERE room_id = 'the-cold-plateau';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-plateau', 'north', 'the-lee-drift', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-plateau', 'east', 'the-frost-pavement', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-plateau', 'west', 'the-spur-head', NULL);

UPDATE rooms SET name = 'The Frost Pavement', description = 'Flat slabs of rock lying edge to edge like paving, with the cracks between them filled with fine sorted gravel, laid out over acres by nothing but freezing and thawing. It looks so exactly like a made floor that you keep expecting a wall. There has never been a wall.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 88, map_y = 0 WHERE id = 'the-frost-pavement';
DELETE FROM exits WHERE room_id = 'the-frost-pavement';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-pavement', 'north', 'the-tarn-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-pavement', 'east', 'the-stripe-field', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-pavement', 'west', 'the-cold-plateau', NULL);

UPDATE rooms SET name = 'The Stripe Field', description = 'Stone stripes again, as on the shoulder far below, but up here they are enormous — lines of boulders twenty feet apart running dead straight down the slope for a quarter of a mile. The same small process, given more time and worse weather. Walking across the grain of them is slow and walking along them is easy and wrong.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 89, map_y = 0 WHERE id = 'the-stripe-field';
DELETE FROM exits WHERE room_id = 'the-stripe-field';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stripe-field', 'north', 'the-high-tarn', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stripe-field', 'east', 'the-spur-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stripe-field', 'west', 'the-frost-pavement', NULL);

UPDATE rooms SET name = 'The High Tarn', description = 'A pool of meltwater in a hollow of the pavement, three strides across, absolutely clear and absolutely still, with the stones on its bottom as sharp as if there were no water there at all. It freezes solid most nights of the year. Nothing lives in it, which up here has stopped being remarkable.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 89, map_y = -1 WHERE id = 'the-high-tarn';
DELETE FROM exits WHERE room_id = 'the-high-tarn';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-tarn', 'south', 'the-stripe-field', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-tarn', 'west', 'the-tarn-edge', NULL);

UPDATE rooms SET name = 'The Tarn Edge', description = 'A crescent of dry gravel on the sheltered side of the tarn, with a low wall of stacked slabs round the back of it about knee high — not built, or not by anybody; the frost stacks them like that and always has. Whatever the reason, it is out of the wind and there is water, and things use it.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 88, map_y = -1 WHERE id = 'the-tarn-edge';
DELETE FROM exits WHERE room_id = 'the-tarn-edge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tarn-edge', 'south', 'the-frost-pavement', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tarn-edge', 'east', 'the-high-tarn', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tarn-edge', 'west', 'the-lee-drift', NULL);

UPDATE rooms SET name = 'The Spur End', description = 'The spur runs into the main mass and the ground rears up to meet the arete, in a slope of jammed blocks with the ridge line above it. From down on the spur this looked like the end of the walk. It is the beginning of the other one.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 90, map_y = -1 WHERE id = 'the-spur-end';
DELETE FROM exits WHERE room_id = 'the-spur-end';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spur-end', 'south', 'the-arete-walk', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spur-end', 'west', 'the-stripe-field', NULL);

UPDATE rooms SET name = 'The Lee Drift', description = 'Snow banked in the spur''s lee in a long tongue that lasts most of the year, hard, wind-carved into scallops, and with a wet grey line at the foot of it where it is always melting a little. It is the only water on this end of the spur and everything comes to it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 87, map_y = -1 WHERE id = 'the-lee-drift';
DELETE FROM exits WHERE room_id = 'the-lee-drift';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lee-drift', 'south', 'the-cold-plateau', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lee-drift', 'east', 'the-tarn-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lee-drift', 'west', 'the-wind-scoop', NULL);

UPDATE rooms SET name = 'The Shelf Head', description = 'Round onto the south side and the wind goes off you like a coat coming off, and there is grass again — not much, and thin, but green. The shelves run east from here in a series of terraces, each one a little higher, and after the north side they feel like a kindness. They are not a kindness. They are simply where the sun is.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 86, map_y = 10 WHERE id = 'the-shelf-head';
DELETE FROM exits WHERE room_id = 'the-shelf-head';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-head', 'east', 'the-long-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-head', 'down', 'the-mid-shelf', NULL);

UPDATE rooms SET name = 'The Long Shelf', description = 'A terrace running a quarter mile east under a wall, level, dry, and floored with short turf, which up here is close to a road. You can walk it without thinking, which is the first time that has been true since the foot, and it is a habit worth breaking before the shelf ends.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 87, map_y = 8 WHERE id = 'the-long-shelf';
DELETE FROM exits WHERE room_id = 'the-long-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-shelf', 'north', 'the-upper-heather', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-shelf', 'east', 'the-shelf-break', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-shelf', 'west', 'the-shelf-head', NULL);

UPDATE rooms SET name = 'The Shelf Break', description = 'The terrace is cut through by a gully coming down from above, ten feet deep with vertical sides of packed gravel, and you go down into it and up the other side. Things wash down this gully. There is a heap at the bottom of what has washed down it, and it is not all stone.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 88, map_y = 8 WHERE id = 'the-shelf-break';
DELETE FROM exits WHERE room_id = 'the-shelf-break';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-break', 'north', 'the-last-green', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-break', 'east', 'the-sun-buttress', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-break', 'west', 'the-long-shelf', NULL);

UPDATE rooms SET name = 'The Upper Heather', description = 'The last heather on the mountain, prostrate, woody, and no higher than your ankle, growing in a mat that follows every dip in the rock. Below this it stood waist high. It is the same plant. This is what the same plant looks like when it is fifteen hundred feet higher up.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 87, map_y = 7 WHERE id = 'the-upper-heather';
DELETE FROM exits WHERE room_id = 'the-upper-heather';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-heather', 'south', 'the-long-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-heather', 'east', 'the-last-green', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-heather', 'west', 'the-heather-step', NULL);

UPDATE rooms SET name = 'The Last Green', description = 'A patch of real grass, bright and cropped tight, in a hollow where water seeps out and the sun sits all afternoon. It is about the size of a cottage floor. It is the best thing to eat within a mile in any direction, and consequently the most dangerous ground on this side of the tier.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 88, map_y = 7 WHERE id = 'the-last-green';
DELETE FROM exits WHERE room_id = 'the-last-green';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-green', 'south', 'the-shelf-break', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-green', 'east', 'the-stone-run', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-green', 'west', 'the-upper-heather', NULL);

UPDATE rooms SET name = 'The Stone Run', description = 'A river of blocks pouring down between two shelves, each one the size of a chest and all of them locked together, with the gaps going down into blackness between them. Something small lives in there. You can hear it moving under your feet and you will not see it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 89, map_y = 7 WHERE id = 'the-stone-run';
DELETE FROM exits WHERE room_id = 'the-stone-run';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-run', 'south', 'the-sun-buttress', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-run', 'east', 'the-shelf-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-run', 'west', 'the-last-green', NULL);

UPDATE rooms SET name = 'The Sun Buttress', description = 'A rib on the sunny side, warm to the hand well into the evening, with ledges on it at head height where things sit and look out over the whole south country. The droppings on the ledges are white and old and layered, and there are a great many of them.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 89, map_y = 8 WHERE id = 'the-sun-buttress';
DELETE FROM exits WHERE room_id = 'the-sun-buttress';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-buttress', 'north', 'the-stone-run', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-buttress', 'east', 'the-warm-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-buttress', 'west', 'the-shelf-break', NULL);

UPDATE rooms SET name = 'The Warm Gully', description = 'A gully taking the afternoon sun end to end, sheltered from every wind, with the rock hot enough to be uncomfortable to sit on. Nothing at all is moving in here at midday. Wait an hour past the sun going off it and that changes.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 90, map_y = 8 WHERE id = 'the-warm-gully';
DELETE FROM exits WHERE room_id = 'the-warm-gully';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-gully', 'north', 'the-shelf-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-gully', 'east', 'the-high-spring', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-gully', 'west', 'the-sun-buttress', NULL);

UPDATE rooms SET name = 'The Shelf End', description = 'The terrace narrows to a point against a buttress and stops, with the next shelf twenty feet above and no way up at this end. You have to go back and round. It is the third time this tier has made you do that and it will not be the last.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 90, map_y = 7 WHERE id = 'the-shelf-end';
DELETE FROM exits WHERE room_id = 'the-shelf-end';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-end', 'south', 'the-warm-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-end', 'east', 'the-scoop-of-grass', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-end', 'west', 'the-stone-run', NULL);

UPDATE rooms SET name = 'The Scoop of Grass', description = 'A green bowl in the rock, spring-fed, out of the wind, floored with the last real grass on this mountain and looking down the whole south side to the country beyond. Everything on this side of the hill comes here and the grass is cropped to the roots to prove it. It is the most comfortable place on this tier and it is comfortable for the same reason it is dangerous.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 91, map_y = 7 WHERE id = 'the-scoop-of-grass';
DELETE FROM exits WHERE room_id = 'the-scoop-of-grass';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scoop-of-grass', 'south', 'the-high-spring', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scoop-of-grass', 'east', 'the-south-rib', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scoop-of-grass', 'west', 'the-shelf-end', NULL);

UPDATE rooms SET name = 'The High Spring', description = 'Water coming out of the rock at a height where there should be no water left to come out, clear and steady and very cold, running twenty feet and sinking again into the gravel. It has done this without stopping through droughts that emptied the burns below. Nobody knows where it comes from and there is nobody to ask.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 91, map_y = 8 WHERE id = 'the-high-spring';
DELETE FROM exits WHERE room_id = 'the-high-spring';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-spring', 'north', 'the-scoop-of-grass', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-spring', 'east', 'the-dry-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-spring', 'west', 'the-warm-gully', NULL);

UPDATE rooms SET name = 'The Dry Shelf', description = 'A terrace of bare baked gravel with the grass gone entirely, sloping just enough to shed every drop that falls on it. It is the driest ground on the mountain and it is forty yards from the spring. Nothing about this hill distributes anything evenly.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 92, map_y = 8 WHERE id = 'the-dry-shelf';
DELETE FROM exits WHERE room_id = 'the-dry-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-shelf', 'north', 'the-south-rib', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-shelf', 'east', 'the-terrace-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-shelf', 'west', 'the-high-spring', NULL);

UPDATE rooms SET name = 'The South Rib', description = 'A rib running down the sun side with a path worn along the crest of it — a real path, narrow and continuous and beaten into the gravel by generations of something going the same way. It is not a made path. It is the shortest line between the spring and the shelves and everything worked that out.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 92, map_y = 7 WHERE id = 'the-south-rib';
DELETE FROM exits WHERE room_id = 'the-south-rib';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-rib', 'south', 'the-dry-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-rib', 'east', 'the-sun-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-rib', 'west', 'the-scoop-of-grass', NULL);

UPDATE rooms SET name = 'The Sun Notch', description = 'A cleft through the rib, a stride wide and twice your height, which the path goes through because there is nowhere else. It is a choke point and it looks like one. Anything waiting for anything on this side of the mountain waits here, and it has been used that way for a very long time.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = 7 WHERE id = 'the-sun-notch';
DELETE FROM exits WHERE room_id = 'the-sun-notch';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-notch', 'south', 'the-terrace-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-notch', 'east', 'the-last-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-notch', 'west', 'the-south-rib', NULL);

UPDATE rooms SET name = 'The Terrace End', description = 'The last of the wide shelves, running out east into steeper ground with the terrace petering into a series of ledges too narrow to walk. From here the easy country is behind you and it is visibly behind you: you can see the whole line of shelves going back west and down.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = 8 WHERE id = 'the-terrace-end';
DELETE FROM exits WHERE room_id = 'the-terrace-end';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-end', 'north', 'the-sun-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-end', 'east', 'the-shelf-drop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-end', 'west', 'the-dry-shelf', NULL);

UPDATE rooms SET name = 'The Last Shelf', description = 'A ledge under the cloud line with the grey sitting on the rock a few feet above your head, so that the shelf is in daylight and the mountain above it is not. It is the boundary of what you can see, drawn along the ground, and it moves when the cloud does.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = 7 WHERE id = 'the-last-shelf';
DELETE FROM exits WHERE room_id = 'the-last-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-shelf', 'north', 'the-cloud-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-shelf', 'south', 'the-shelf-drop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-shelf', 'west', 'the-sun-notch', NULL);

UPDATE rooms SET name = 'The Shelf Drop', description = 'The shelves end at a drop of two hundred feet onto the tier below, with the ground going over in a clean rounded lip worn smooth by water. You can look straight down onto ground you crossed yesterday and it is a very long way away. There is no way down here and it looks like there might be.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = 8 WHERE id = 'the-shelf-drop';
DELETE FROM exits WHERE room_id = 'the-shelf-drop';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-drop', 'north', 'the-last-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-drop', 'west', 'the-terrace-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-drop', 'up', 'the-shelf-tail', NULL);

UPDATE rooms SET name = 'The Cold Ramp', description = 'A tongue of old snow lying up the back of the rib, hard all day and harder at night, running up at an angle you can just walk if you kick steps and do not stop. It is the shaded side, so the snow never rots, so the ramp is here in every month of the year. It is the only thing on this face that is reliable.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 85, map_y = 2 WHERE id = 'the-cold-ramp';
DELETE FROM exits WHERE room_id = 'the-cold-ramp';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-ramp', 'east', 'the-rib-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-ramp', 'down', 'the-late-field', NULL);

UPDATE rooms SET name = 'The Hot Ledge', description = 'A ledge a stride wide running east across the face above the scree, dry, dusty, and warm enough that the air over it shakes. There is nothing above it but rock and nothing below it for a long way. Everything with hooves on this side of the mountain uses it and the dust is beaten to powder.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 83, map_y = 9 WHERE id = 'the-hot-ledge';
DELETE FROM exits WHERE room_id = 'the-hot-ledge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hot-ledge', 'east', 'the-sun-traverse', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hot-ledge', 'down', 'the-hot-scree', NULL);

UPDATE rooms SET name = 'The Sun Traverse', description = 'The ledge narrows to the width of your boots and holds that width for a hundred paces, with the rock leaning out slightly overhead so that you go along it turned half sideways. The stone is warm through your palms. There is no possibility of turning round on this and nothing to do about anything you meet.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 84, map_y = 9 WHERE id = 'the-sun-traverse';
DELETE FROM exits WHERE room_id = 'the-sun-traverse';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-traverse', 'east', 'the-dry-ledge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-traverse', 'west', 'the-hot-ledge', NULL);

UPDATE rooms SET name = 'The Dry Ledge', description = 'It widens again, and there is grit underfoot, and droppings, old and new and in two sizes. Something eats here regularly and something else waits for it here regularly, and the two of them have been keeping this appointment on a ledge a yard wide for a great many years.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 85, map_y = 9 WHERE id = 'the-dry-ledge';
DELETE FROM exits WHERE room_id = 'the-dry-ledge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-ledge', 'east', 'the-heather-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-ledge', 'west', 'the-sun-traverse', NULL);

UPDATE rooms SET name = 'The Heather Step', description = 'The ledge runs out onto a step of broken ground with the first heather on it, ankle high and woody, and after the traverse the sheer amount of room to stand in is briefly ridiculous. Everything that came along the ledge stops here, and it shows: the heather is beaten into paths going three ways.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 86, map_y = 9 WHERE id = 'the-heather-step';
DELETE FROM exits WHERE room_id = 'the-heather-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heather-step', 'east', 'the-upper-heather', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heather-step', 'west', 'the-dry-ledge', NULL);

UPDATE rooms SET name = 'The Fan Head', description = 'The cloud thins at the corner and the ground ahead falls away into a fan of grey stone running out further than you can see the end of, with everything the mountain has shed lying somewhere on it, sorted by weight. You are standing at the top of it. From here it is all downhill and none of it is walking.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 92, map_y = 6 WHERE id = 'the-fan-head';
DELETE FROM exits WHERE room_id = 'the-fan-head';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fan-head', 'east', 'the-catch-slope', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fan-head', 'down', 'the-cloud-foot', NULL);

UPDATE rooms SET name = 'The Upper Brim', description = 'The top edge of the snowfield, where the white stops and the sky starts, and the line between them is so clean it looks cut. Snow curls over the edge in a lip you cannot see the underside of from here. Standing on the brim you can be seen from every square foot of this tier and from most of the one below it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = -3 WHERE id = 'the-upper-brim';
DELETE FROM exits WHERE room_id = 'the-upper-brim';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-brim', 'south', 'the-snow-brim', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-upper-brim', 'east', 'the-frost-face', NULL);

UPDATE rooms SET name = 'The Frost Face', description = 'A face of old snow standing steeper than snow should stand, grown over in feathers of frost the length of your hand, all of them pointing into the wind. They break off when you touch them and go rattling away downhill for a long time. It is the only sound out here that anything makes on purpose.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = -5 WHERE id = 'the-frost-face';
DELETE FROM exits WHERE room_id = 'the-frost-face';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-face', 'south', 'the-white-slope', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frost-face', 'west', 'the-upper-brim', NULL);

UPDATE rooms SET name = 'The Snow Brim', description = 'Wind-packed snow that takes your weight for four steps out of five, and the fifth drops you to the knee without warning. There is no way to tell them apart by looking. After a while you stop trying and simply walk, and the mountain lets you off four times out of five.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = -2 WHERE id = 'the-snow-brim';
DELETE FROM exits WHERE room_id = 'the-snow-brim';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-brim', 'north', 'the-upper-brim', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-brim', 'south', 'the-high-neve', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-brim', 'east', 'the-white-slope', NULL);

UPDATE rooms SET name = 'The High Neve', description = 'You come out of the cloud into flat white light with no shadow in it anywhere, and the ground and the air are the same colour. This is where last year''s snow becomes next century''s ice, one weight at a time. It is perfectly quiet and enormously bright and there is not one thing to look at.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = 1 WHERE id = 'the-high-neve';
DELETE FROM exits WHERE room_id = 'the-high-neve';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-neve', 'north', 'the-snow-brim', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-neve', 'south', 'the-drift-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-neve', 'east', 'the-wind-slab', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-neve', 'down', 'the-standing-cloud', NULL);

UPDATE rooms SET name = 'The Drift Foot', description = 'The bottom of a drift the size of a village, in the lee where the wind puts down everything it has been carrying. The snow here is deep and soft and slow, and a thing that came down the face this winter is somewhere under it, and will keep until spring, and spring does not come to this height.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = 1 WHERE id = 'the-drift-foot';
DELETE FROM exits WHERE room_id = 'the-drift-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-foot', 'north', 'the-high-neve', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-foot', 'east', 'the-sun-cup', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-foot', 'down', 'the-cloud-shelf', NULL);

UPDATE rooms SET name = 'The White Slope', description = 'A long even slope of white with a single line of tracks going across it, made by something with a stride longer than yours, walking without hurrying, from nowhere in particular to nowhere in particular. The tracks are old enough to have gone hard and stand up in relief where the wind has taken the loose snow off round them.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = -4 WHERE id = 'the-white-slope';
DELETE FROM exits WHERE room_id = 'the-white-slope';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-slope', 'north', 'the-frost-face', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-slope', 'south', 'the-wind-slab', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-slope', 'east', 'the-snow-dome', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-slope', 'west', 'the-snow-brim', NULL);

UPDATE rooms SET name = 'The Wind Slab', description = 'Snow packed into a slab that rings hollow when you step on it, laid over softer stuff that will not hold it. It is stable until it is not, and the change happens all at once and across the whole width. Every step out here is a small argument with the surface about whose weight this is.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = 0 WHERE id = 'the-wind-slab';
DELETE FROM exits WHERE room_id = 'the-wind-slab';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-slab', 'north', 'the-white-slope', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-slab', 'south', 'the-sun-cup', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-slab', 'east', 'the-broken-crust', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-slab', 'west', 'the-high-neve', NULL);

UPDATE rooms SET name = 'The Sun Cup', description = 'The snow has melted into a field of shallow bowls a foot across, each with a ridge of ice standing between it and the next, so the whole surface is a honeycomb you cannot walk across without breaking. It is made by sunlight and it happens where nothing is ever warm. The mountain does this for its own reasons.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = 2 WHERE id = 'the-sun-cup';
DELETE FROM exits WHERE room_id = 'the-sun-cup';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-cup', 'north', 'the-wind-slab', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-cup', 'east', 'the-runnel', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-cup', 'west', 'the-drift-foot', NULL);

UPDATE rooms SET name = 'The Snow Dome', description = 'A rise of snow with no rock in it at all — the ice underneath is deep enough that the shape of the mountain has been forgotten and the shape of the weather has taken over. From the top of it you can see the whole snowfield and everything standing on it, and everything standing on it can see you.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = -4 WHERE id = 'the-snow-dome';
DELETE FROM exits WHERE room_id = 'the-snow-dome';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-dome', 'south', 'the-broken-crust', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-dome', 'east', 'the-hard-pack', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-dome', 'west', 'the-white-slope', NULL);

UPDATE rooms SET name = 'The Broken Crust', description = 'A hard crust over soft snow, broken into plates the size of doors and tipped every way, and something heavy went through it in a straight line not long ago. The holes are the shape of a foot and further apart than a person''s stride. They fill in slowly at this height.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 97, map_y = 0 WHERE id = 'the-broken-crust';
DELETE FROM exits WHERE room_id = 'the-broken-crust';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-crust', 'north', 'the-snow-dome', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-crust', 'south', 'the-runnel', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-crust', 'east', 'the-blue-shadow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-crust', 'west', 'the-wind-slab', NULL);

UPDATE rooms SET name = 'The Runnel', description = 'A channel cut into the snow by meltwater that only runs for an hour a day, waist deep and smooth-walled and running dead straight downhill. In it you are out of the wind and out of sight of everything, which is the first of either since you came out of the cloud. It is also a channel, and things follow channels.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 97, map_y = 1 WHERE id = 'the-runnel';
DELETE FROM exits WHERE room_id = 'the-runnel';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-runnel', 'north', 'the-broken-crust', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-runnel', 'east', 'the-snow-hollow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-runnel', 'west', 'the-sun-cup', NULL);

UPDATE rooms SET name = 'The Hard Pack', description = 'Snow that has been blown on so long it has the texture of stone and will not take a print at all. Nothing crossing here leaves any record of having crossed. The east edge goes over in a cornice and there is no way down onto the ice from it — the drop is the whole height of the glacier''s flank.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = -4 WHERE id = 'the-hard-pack';
DELETE FROM exits WHERE room_id = 'the-hard-pack';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard-pack', 'south', 'the-blue-shadow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard-pack', 'west', 'the-snow-dome', NULL);

UPDATE rooms SET name = 'The Blue Shadow', description = 'The shade under the cornice, where the light comes through the snow instead of onto it and everything in here is the colour of deep water. It is a good deal colder in the blue than four feet away in the white, and things that hunt on the snowfield know precisely where the line is.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 98, map_y = 0 WHERE id = 'the-blue-shadow';
DELETE FROM exits WHERE room_id = 'the-blue-shadow';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-shadow', 'north', 'the-hard-pack', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-shadow', 'south', 'the-snow-hollow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-shadow', 'east', 'the-crevasse-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-shadow', 'west', 'the-broken-crust', NULL);

UPDATE rooms SET name = 'The Snow Hollow', description = 'A scoop dug back into the drift, deeper than weather makes and roofed by the drift above it, with room to sit up and no room to stand. Something dug this, more than once, in more than one winter. There is nothing in it now and nothing follows you into it, and out of the wind at this height that is very nearly everything.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 98, map_y = 1 WHERE id = 'the-snow-hollow';
DELETE FROM exits WHERE room_id = 'the-snow-hollow';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-hollow', 'north', 'the-blue-shadow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-hollow', 'south', 'the-snow-tongue', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-hollow', 'west', 'the-runnel', NULL);

UPDATE rooms SET name = 'The Snow Tongue', description = 'A finger of old snow running down off the field into the rocks, narrow enough to touch both edges, hard enough to walk and steep enough that you would not stop if you sat down. It is the one place the white ground and the grey ground meet without a drop between them, and everything that uses this mountain knows it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 98, map_y = 2 WHERE id = 'the-snow-tongue';
DELETE FROM exits WHERE room_id = 'the-snow-tongue';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-tongue', 'north', 'the-snow-hollow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snow-tongue', 'south', 'the-tongue-foot', NULL);

UPDATE rooms SET name = 'The Tongue Foot', description = 'The snow ends in a wet grey lip a foot thick, undercut, dripping, with black rock showing under it. Below the lip the ground is stones. There is a smell here, faint and not fresh, of something that came down the tongue and did not get up.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 98, map_y = 3 WHERE id = 'the-tongue-foot';
DELETE FROM exits WHERE room_id = 'the-tongue-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tongue-foot', 'north', 'the-snow-tongue', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tongue-foot', 'south', 'the-dry-bones', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tongue-foot', 'east', 'the-red-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tongue-foot', 'west', 'the-grey-run', NULL);

UPDATE rooms SET name = 'The Shelf Tail', description = 'The sun shelves finally run out — the grass gives up, then the moss, then the soil, and what is left is a tail of loose stone spilling east into open ground with nothing growing on it at all. It is the last step out of anywhere that feeds you.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = 7 WHERE id = 'the-shelf-tail';
DELETE FROM exits WHERE room_id = 'the-shelf-tail';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-tail', 'east', 'the-fall-fan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-tail', 'down', 'the-shelf-drop', NULL);

UPDATE rooms SET name = 'The Fall Fan', description = 'The bottom of the fan, where the smallest things end up: grit, chips, the light stuff that bounced furthest. It is soft walking and dull to look at and the only bones in it are small enough to take for gravel until you pick one up.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = 6 WHERE id = 'the-fall-fan';
DELETE FROM exits WHERE room_id = 'the-fall-fan';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fall-fan', 'north', 'the-bone-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fall-fan', 'east', 'the-lower-fan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fall-fan', 'west', 'the-shelf-tail', NULL);

UPDATE rooms SET name = 'The Bone Ground', description = 'Bone, in quantity, lying loose among the stones over an area you could not cross in a minute — ribs, cannon bones, the long spiral of a horn, skulls with the teeth still bedded. None of it is arranged and none of it is fresh. Everything that dies anywhere above here comes to this fan eventually, and this is where the heavy pieces stop rolling.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = 6 WHERE id = 'the-bone-ground';
DELETE FROM exits WHERE room_id = 'the-bone-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-ground', 'north', 'the-catch-slope', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-ground', 'south', 'the-fall-fan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-ground', 'east', 'the-splinter-field', NULL);

UPDATE rooms SET name = 'The Catch Slope', description = 'A slope of fine scree lying at exactly the angle it can hold, which catches what comes off the face above and holds it a while before letting it go again. Things sit here for years. There is a hind''s skull halfway up, sun-bleached on the top and still dark underneath, and nothing has moved it in a long time. The cloud stands in a wall along the western edge of it and the ground goes into that wall and stops being visible rather than stopping.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 93, map_y = 6 WHERE id = 'the-catch-slope';
DELETE FROM exits WHERE room_id = 'the-catch-slope';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-catch-slope', 'south', 'the-bone-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-catch-slope', 'east', 'the-boulder-nose', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-catch-slope', 'west', 'the-fan-head', NULL);

UPDATE rooms SET name = 'The Boulder Nose', description = 'A nose of solid rock standing out of the scree, the only thing on this fan that did not arrive by falling. It splits what comes down into two streams, and everything on one side of it goes west and everything on the other goes east, and the sorting the whole fan does starts here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = 4 WHERE id = 'the-boulder-nose';
DELETE FROM exits WHERE room_id = 'the-boulder-nose';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-nose', 'south', 'the-splinter-field', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-nose', 'east', 'the-grey-run', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boulder-nose', 'west', 'the-catch-slope', NULL);

UPDATE rooms SET name = 'The Splinter Field', description = 'Rock broken into blades and splinters rather than pebbles — frost does this, over and over, until a boulder is a heap of knives lying edge-up. It is bad ground to walk and worse to fall on, and the animals cross it at a specific place because everything crosses it at that place.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = 5 WHERE id = 'the-splinter-field';
DELETE FROM exits WHERE room_id = 'the-splinter-field';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-splinter-field', 'north', 'the-boulder-nose', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-splinter-field', 'south', 'the-lower-fan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-splinter-field', 'east', 'the-rib-cage', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-splinter-field', 'west', 'the-bone-ground', NULL);

UPDATE rooms SET name = 'The Lower Fan', description = 'Where the fan flattens out and stops sorting, and everything that got this far lies mixed together: chips, splinters, one antler, half a jaw. Water runs under it rather than over it and you can hear that, faintly, through the stones.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = 5 WHERE id = 'the-lower-fan';
DELETE FROM exits WHERE room_id = 'the-lower-fan';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-fan', 'north', 'the-splinter-field', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-fan', 'east', 'the-scoured-flat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-fan', 'west', 'the-fall-fan', NULL);

UPDATE rooms SET name = 'The Grey Run', description = 'A chute of grey stone worn smooth down the middle by everything that has come down it, running from the foot of the snow tongue out onto the fan. Standing in it is standing in the path. Nothing has come down it while you have been here, which is not the same as nothing coming down it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 97, map_y = 3 WHERE id = 'the-grey-run';
DELETE FROM exits WHERE room_id = 'the-grey-run';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-run', 'south', 'the-rib-cage', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-run', 'east', 'the-tongue-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-run', 'west', 'the-boulder-nose', NULL);

UPDATE rooms SET name = 'The Rib Cage', description = 'The ribcage of something the size of a horse, lying on its side, picked absolutely clean and gone the colour of the stones around it. The bones are still articulated and the arch of them makes a space underneath a person can lie in out of the weather. Nothing comes in here. Whatever cleaned this did it a very long time ago and has not been back.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 97, map_y = 4 WHERE id = 'the-rib-cage';
DELETE FROM exits WHERE room_id = 'the-rib-cage';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rib-cage', 'north', 'the-grey-run', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rib-cage', 'south', 'the-scoured-flat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rib-cage', 'east', 'the-dry-bones', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rib-cage', 'west', 'the-splinter-field', NULL);

UPDATE rooms SET name = 'The Scoured Flat', description = 'A flat of packed grit swept bare by the wind that comes down the face every afternoon, so clean it looks swept on purpose. Bones that lie here do not stay — they go on down the fan. Only the heaviest thing in sight stays put, and the heaviest thing in sight is a vertebra the width of a dinner plate.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 97, map_y = 5 WHERE id = 'the-scoured-flat';
DELETE FROM exits WHERE room_id = 'the-scoured-flat';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scoured-flat', 'north', 'the-rib-cage', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scoured-flat', 'east', 'the-last-fan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scoured-flat', 'west', 'the-lower-fan', NULL);

UPDATE rooms SET name = 'The Dry Bones', description = 'Bone that has been up here long enough to stop being bone in any useful sense: chalky, light as cork, crumbling at a touch and blowing away as powder. The mountain finishes everything eventually. Something has still been chewing on the ends of these, which is the only reason anything comes to this room.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 98, map_y = 4 WHERE id = 'the-dry-bones';
DELETE FROM exits WHERE room_id = 'the-dry-bones';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-bones', 'north', 'the-tongue-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-bones', 'south', 'the-last-fan', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-bones', 'east', 'the-red-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-bones', 'west', 'the-rib-cage', NULL);

UPDATE rooms SET name = 'The Last Fan', description = 'The eastern edge of the bone ground, where the grey stone gives out and the ground under your boots starts to have colour in it. The change happens across about ten feet. Behind you everything is the colour of ash; ahead of you everything is the colour of old blood, and neither of them grows anything.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 98, map_y = 5 WHERE id = 'the-last-fan';
DELETE FROM exits WHERE room_id = 'the-last-fan';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-fan', 'north', 'the-dry-bones', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-fan', 'east', 'the-rust-slope', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-fan', 'west', 'the-scoured-flat', NULL);

UPDATE rooms SET name = 'The Red Edge', description = 'The top edge of the red ground, a band of rust-coloured rock running along the hill as straight as a drawn line. Above it grey, below it red, and no gradual anything. It looks like the warmest ground on the mountain from any distance and is the coldest to stand on, because there is nothing here to hold a day''s heat.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 99, map_y = 3 WHERE id = 'the-red-edge';
DELETE FROM exits WHERE room_id = 'the-red-edge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-edge', 'south', 'the-red-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-edge', 'east', 'the-oxide-flat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-edge', 'west', 'the-tongue-foot', NULL);

UPDATE rooms SET name = 'The Oxide Flat', description = 'A flat pavement of red rock furred over in a bloom of rust that comes off on your hands and does not wash off. Water lying in the hollows is the colour of tea and tastes of iron and pennies. Nothing drinks it. Nothing up here can afford to be that thirsty.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 100, map_y = 3 WHERE id = 'the-oxide-flat';
DELETE FROM exits WHERE room_id = 'the-oxide-flat';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oxide-flat', 'south', 'the-iron-band', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oxide-flat', 'east', 'the-burnt-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oxide-flat', 'west', 'the-red-edge', NULL);

UPDATE rooms SET name = 'The Burnt Ground', description = 'Ground that looks scorched and never has been — the red goes almost black here, in patches with clean edges, and the rock rings differently underfoot from one patch to the next. The glacier''s toe comes down into the north side of it and the meeting of grey ice and black-red stone is the strangest-looking thing on this mountain.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 101, map_y = 3 WHERE id = 'the-burnt-ground';
DELETE FROM exits WHERE room_id = 'the-burnt-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burnt-ground', 'north', 'the-glacier-toe', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burnt-ground', 'south', 'the-ochre-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burnt-ground', 'east', 'the-high-red', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burnt-ground', 'west', 'the-oxide-flat', NULL);

UPDATE rooms SET name = 'The High Red', description = 'The top corner of the red ground, high enough to look back over the whole of it, and from here you can see it is not a slope but a bowl — everything drains to the middle and the middle drains nowhere. Whatever gets in has to come out the way it came in.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = 3 WHERE id = 'the-high-red';
DELETE FROM exits WHERE room_id = 'the-high-red';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-red', 'south', 'the-scree-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-red', 'west', 'the-burnt-ground', NULL);

UPDATE rooms SET name = 'The Red Scree', description = 'Loose red stone at the exact angle it will hold, which is to say it is not holding, it is failing slowly the whole time you stand on it. Every step starts a small collapse that runs away downhill and gets quieter and never quite stops. There is no such thing as arriving here silently.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 99, map_y = 4 WHERE id = 'the-red-scree';
DELETE FROM exits WHERE room_id = 'the-red-scree';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-scree', 'north', 'the-red-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-scree', 'south', 'the-rust-slope', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-scree', 'east', 'the-iron-band', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-scree', 'west', 'the-dry-bones', NULL);

UPDATE rooms SET name = 'The Iron Band', description = 'A seam of something harder standing proud of the scree, black-red and heavy and cold enough to take the skin off wet fingers. It rings when struck, which nothing else up here does. There are chips off it lying about, and the chips have edges you could cut with.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 100, map_y = 4 WHERE id = 'the-iron-band';
DELETE FROM exits WHERE room_id = 'the-iron-band';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-iron-band', 'north', 'the-oxide-flat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-iron-band', 'south', 'the-stained-run', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-iron-band', 'east', 'the-ochre-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-iron-band', 'west', 'the-red-scree', NULL);

UPDATE rooms SET name = 'The Ochre Shelf', description = 'A shelf of soft yellow-red stone that crumbles under a boot into powder the colour of a brick, and everything that has crossed it recently has left a print with a clean edge. There are a lot of prints. Only two kinds, and both of them are the kind with claws.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 101, map_y = 4 WHERE id = 'the-ochre-shelf';
DELETE FROM exits WHERE room_id = 'the-ochre-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ochre-shelf', 'north', 'the-burnt-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ochre-shelf', 'south', 'the-red-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ochre-shelf', 'east', 'the-scree-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ochre-shelf', 'west', 'the-iron-band', NULL);

UPDATE rooms SET name = 'The Scree Head', description = 'The head of the gully that drains the whole red bowl, where all the loose stuff on this hillside is queuing to go down one channel. It is like standing at the top of an hourglass. Everything about the ground here is on its way somewhere and only stopped because the ones underneath have not moved yet.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = 4 WHERE id = 'the-scree-head';
DELETE FROM exits WHERE room_id = 'the-scree-head';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-head', 'north', 'the-high-red', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-head', 'south', 'the-gully-top', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-head', 'west', 'the-ochre-shelf', NULL);

UPDATE rooms SET name = 'The Rust Slope', description = 'A long slope of small red stones with nothing whatever growing on it, running down out of sight to the south. The colour is so even and so total that after a while your eyes give up looking for detail and you find you have walked a long way without noticing anything at all, which is how ground like this gets people.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 99, map_y = 5 WHERE id = 'the-rust-slope';
DELETE FROM exits WHERE room_id = 'the-rust-slope';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rust-slope', 'north', 'the-red-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rust-slope', 'east', 'the-stained-run', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rust-slope', 'west', 'the-last-fan', NULL);

UPDATE rooms SET name = 'The Stained Run', description = 'Where water has run down the red rock for long enough to stain a stripe darker than the ground either side, twenty feet wide and running the whole length of the slope. It is dry now. It is dry for eleven months and it moves the entire hillside in the twelfth.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 100, map_y = 5 WHERE id = 'the-stained-run';
DELETE FROM exits WHERE room_id = 'the-stained-run';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stained-run', 'north', 'the-iron-band', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stained-run', 'east', 'the-red-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stained-run', 'west', 'the-rust-slope', NULL);

UPDATE rooms SET name = 'The Red Gully', description = 'A gully cut deep into the red, walls above head height, floor of loose stone, and everything that comes off this side of the mountain funnels into it. Down here you can see nothing but the two walls and the strip of sky. Something has been sleeping against the west wall, in the dry, and the shape of it is still in the grit.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 101, map_y = 5 WHERE id = 'the-red-gully';
DELETE FROM exits WHERE room_id = 'the-red-gully';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-gully', 'north', 'the-ochre-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-gully', 'east', 'the-gully-top', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-gully', 'west', 'the-stained-run', NULL);

UPDATE rooms SET name = 'The Gully Top', description = 'The gully''s head narrows to a slot you could touch both sides of, and above it the ground simply stops — the whole drainage of the red bowl comes through a gap the width of a door. Everything up here that moves has to come through this, or go round the entire hillside.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = 5 WHERE id = 'the-gully-top';
DELETE FROM exits WHERE room_id = 'the-gully-top';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-top', 'north', 'the-scree-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-top', 'west', 'the-red-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gully-top', 'up', 'the-red-tail', NULL);

UPDATE rooms SET name = 'The Crest Step', description = 'The permanent ice ends and rock begins, and the rock is a step up onto the crest of a ridge that runs away east as far as you can see it. Both sides fall away immediately. From this step on there is no such thing as walking round anything.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = -2 WHERE id = 'the-crest-step';
DELETE FROM exits WHERE room_id = 'the-crest-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-step', 'north', 'the-first-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-step', 'east', 'the-knife', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-step', 'down', 'the-cold-crest', NULL);

UPDATE rooms SET name = 'The First Notch', description = 'A gap in the crest where the ridge dips and the wind comes through from the far side hard enough to lean on. Standing in the notch you can see down the north face, which nobody has any reason to look at twice: it is black, it is vertical, and there is nothing on it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 94, map_y = -3 WHERE id = 'the-first-notch';
DELETE FROM exits WHERE room_id = 'the-first-notch';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-notch', 'south', 'the-crest-step', NULL);

UPDATE rooms SET name = 'The Knife', description = 'The ridge narrows to the width of a plank of stone with air on both sides and a very long way down on each. There is no wind shelter, no wide place and nothing to hold. The only way to do this is to keep going at a steady pace and not stop in the middle to think about it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = -2 WHERE id = 'the-knife';
DELETE FROM exits WHERE room_id = 'the-knife';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-knife', 'north', 'the-north-drop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-knife', 'east', 'the-second-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-knife', 'west', 'the-crest-step', NULL);

UPDATE rooms SET name = 'The North Drop', description = 'A step off the north side of the ridge onto a ledge the size of a table, which is the only place on this whole crest a person can sit down. It ends in nothing. Birds have been using it: the rock is white with them, and there are pellets, and the pellets are full of small bones.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 95, map_y = -3 WHERE id = 'the-north-drop';
DELETE FROM exits WHERE room_id = 'the-north-drop';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-drop', 'south', 'the-knife', NULL);

UPDATE rooms SET name = 'The Second Notch', description = 'Another dip in the crest, deeper than the first, with old snow lying in the bottom of it that never sees sun. Something crossed the snow within the last day or so. The prints go over the ridge and down the north side, which is not something with four legs should be able to do.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = -2 WHERE id = 'the-second-notch';
DELETE FROM exits WHERE room_id = 'the-second-notch';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-notch', 'north', 'the-gendarme', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-notch', 'east', 'the-ridge-walk', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-notch', 'west', 'the-knife', NULL);

UPDATE rooms SET name = 'The Gendarme', description = 'A tower of rock standing on the ridge like a post, twice your height, that everything has to go round. There is a worn line round its base on the south side where everything has gone round it, and the wear is deep enough to be a path in its own right. Nothing has ever gone round it on the north.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = -3 WHERE id = 'the-gendarme';
DELETE FROM exits WHERE room_id = 'the-gendarme';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gendarme', 'south', 'the-second-notch', NULL);

UPDATE rooms SET name = 'The Ridge Walk', description = 'Broad enough here to walk two abreast, and after the knife that feels like a road. The rock is shattered into loose plates that slide against each other under your weight and make a noise like crockery. You are audible from a very long way off along a ridge, in both directions.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 97, map_y = -2 WHERE id = 'the-ridge-walk';
DELETE FROM exits WHERE room_id = 'the-ridge-walk';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-walk', 'north', 'the-wind-tooth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-walk', 'east', 'the-third-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-walk', 'west', 'the-second-notch', NULL);

UPDATE rooms SET name = 'The Wind Tooth', description = 'A blade of rock standing off the north side, undercut by the wind until it is thinner at the bottom than the top. It hums. Not loudly, and not always, but in a steady wind the whole tooth resonates and you can feel it through the soles of your boots before you can hear it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 97, map_y = -3 WHERE id = 'the-wind-tooth';
DELETE FROM exits WHERE room_id = 'the-wind-tooth';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-tooth', 'south', 'the-ridge-walk', NULL);

UPDATE rooms SET name = 'The Third Notch', description = 'The last dip, and the widest, filled to the brim with hard old snow so that the ridge appears to be continuous when it is in fact a gap with snow in it. How much of the snow is standing on rock and how much is standing on itself is not a question this notch will answer from up here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 98, map_y = -2 WHERE id = 'the-third-notch';
DELETE FROM exits WHERE room_id = 'the-third-notch';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-notch', 'north', 'the-lean', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-notch', 'east', 'the-ridge-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-notch', 'west', 'the-ridge-walk', NULL);

UPDATE rooms SET name = 'The Lean', description = 'A slab the size of a barn door that came off the ridge and did not fall — it leaned against what it came off and stopped, leaving a triangular gap underneath, dry and dark and out of the wind. There are old droppings in the back of it, dried to nothing, and a smell that has almost gone.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 98, map_y = -3 WHERE id = 'the-lean';
DELETE FROM exits WHERE room_id = 'the-lean';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lean', 'south', 'the-third-notch', NULL);

UPDATE rooms SET name = 'The Ridge End', description = 'The crest broadens, loses its edge, and dies into a shoulder of broken rock. After a mile of having nothing on either side of you, ground that goes on in more than one direction is briefly disorienting, and you will stand here longer than you need to.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 99, map_y = -2 WHERE id = 'the-ridge-end';
DELETE FROM exits WHERE room_id = 'the-ridge-end';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-end', 'north', 'the-last-tooth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-end', 'south', 'the-ridge-drop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-end', 'west', 'the-third-notch', NULL);

UPDATE rooms SET name = 'The Last Tooth', description = 'The final pinnacle on the crest, and the only one you can get on top of. From up here the whole tier lies out below — the white of the snowfield, the grey fan, the red bowl, the ice — and above all of them the swept ground, and past that the shape you cannot see the top of.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 99, map_y = -3 WHERE id = 'the-last-tooth';
DELETE FROM exits WHERE room_id = 'the-last-tooth';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-tooth', 'south', 'the-ridge-end', NULL);

UPDATE rooms SET name = 'The Ridge Drop', description = 'The shoulder drops away to the glacier''s head, and between the rock and the ice there is a gap running the whole width of it — the ice has pulled away from the mountain and gone on downhill without it. There is one snow bridge across, and one is enough, and it is not a thing to stand about on.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 99, map_y = -1 WHERE id = 'the-ridge-drop';
DELETE FROM exits WHERE room_id = 'the-ridge-drop';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-drop', 'north', 'the-ridge-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-drop', 'south', 'the-white-tower', NULL);

UPDATE rooms SET name = 'The Serac Field', description = 'The ice has gone over a step in the rock beneath it and broken into towers and blocks the size of houses, leaning every way, with lanes of shadow between them. Some of these will fall this year. Nothing about looking at them tells you which, and the lanes between them are the only way through.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 97, map_y = -4 WHERE id = 'the-serac-field';
DELETE FROM exits WHERE room_id = 'the-serac-field';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-serac-field', 'south', 'the-ice-blocks', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-serac-field', 'east', 'the-white-tower', NULL);

UPDATE rooms SET name = 'The Ice Blocks', description = 'Fallen towers lying where they landed, already rounding off at the corners, some of them clear enough to see a foot into and some of them white as chalk. Between two of them there is a gap you go through sideways and it is the coldest air on the mountain.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = -4 WHERE id = 'the-ice-blocks';
DELETE FROM exits WHERE room_id = 'the-ice-blocks';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-blocks', 'north', 'the-serac-field', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-blocks', 'south', 'the-crevasse-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-blocks', 'east', 'the-blue-ice', NULL);

UPDATE rooms SET name = 'The Crevasse Lip', description = 'The edge of a crack across the whole glacier, wide enough to swallow a cart, with walls that go from white to blue to a blue so dark it reads as black. There is no bottom visible. Things that go in here come out at the toe, later, a great deal later, and in the condition they went in.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 99, map_y = 0 WHERE id = 'the-crevasse-lip';
DELETE FROM exits WHERE room_id = 'the-crevasse-lip';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crevasse-lip', 'north', 'the-ice-blocks', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crevasse-lip', 'south', 'the-glacier-bend', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crevasse-lip', 'east', 'the-slot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crevasse-lip', 'west', 'the-blue-shadow', NULL);

UPDATE rooms SET name = 'The Glacier Bend', description = 'The ice turns a corner round a buttress of rock, and turning has torn it: the whole flank is a fan of cracks, none of them wide, all of them deep. Walking it is a matter of stepping over things you cannot see the end of, one after another, for longer than is comfortable.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 99, map_y = 1 WHERE id = 'the-glacier-bend';
DELETE FROM exits WHERE room_id = 'the-glacier-bend';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-bend', 'north', 'the-crevasse-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-bend', 'east', 'the-melt-lip', NULL);

UPDATE rooms SET name = 'The White Tower', description = 'A serac standing alone at the head of the ice, taller than the rest and gone chalk-white with age, leaning very slightly downhill the way they all do just before. Under it the snow bridge from the ridge comes in. This is the head of the glacier and everything on the glacier started here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 98, map_y = -1 WHERE id = 'the-white-tower';
DELETE FROM exits WHERE room_id = 'the-white-tower';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-tower', 'north', 'the-ridge-drop', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-tower', 'south', 'the-blue-ice', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-tower', 'east', 'the-ice-plain', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-tower', 'west', 'the-serac-field', NULL);

UPDATE rooms SET name = 'The Blue Ice', description = 'Bare ice with no snow on it at all, polished by wind, hard as glass and the colour of a deep pool. You can see down into it a long way, and about four feet under the surface there is something dark and about the size of a dog, and it is going to be another century getting to the bottom.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 97, map_y = -1 WHERE id = 'the-blue-ice';
DELETE FROM exits WHERE room_id = 'the-blue-ice';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-ice', 'north', 'the-white-tower', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-ice', 'south', 'the-slot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-ice', 'east', 'the-drift-hollow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-ice', 'west', 'the-ice-blocks', NULL);

UPDATE rooms SET name = 'The Slot', description = 'A crevasse so narrow you could step across it without thinking, and that is the danger of it — it is bridged over by a foot of snow along most of its length and the bridge looks exactly like the ground either side. Where it is open you can see it goes down further than the wide ones do.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = -1 WHERE id = 'the-slot';
DELETE FROM exits WHERE room_id = 'the-slot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slot', 'north', 'the-blue-ice', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slot', 'south', 'the-melt-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slot', 'east', 'the-glacier-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slot', 'west', 'the-crevasse-lip', NULL);

UPDATE rooms SET name = 'The Melt Lip', description = 'The ice ends in a wall twice your height, undercut by its own meltwater into an overhanging lip with a cave under it, and the cave breathes cold and drips steadily. Nothing hangs about under a lip like this. The ice above it is standing on the air it has melted out from under itself.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 97, map_y = 2 WHERE id = 'the-melt-lip';
DELETE FROM exits WHERE room_id = 'the-melt-lip';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-lip', 'north', 'the-slot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-lip', 'south', 'the-melt-run', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-lip', 'east', 'the-moulin', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-lip', 'west', 'the-glacier-bend', NULL);

UPDATE rooms SET name = 'The Ice Plain', description = 'Flat ice under an inch of dry snow, the smoothest ground on the whole mountain, running for what looks like half a mile. It is a pleasure to walk on, which is the trap: there is nothing to hold your attention here and you will not notice the surface stop being ice and start being roof.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 100, map_y = -2 WHERE id = 'the-ice-plain';
DELETE FROM exits WHERE room_id = 'the-ice-plain';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-plain', 'south', 'the-drift-hollow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-plain', 'east', 'the-stone-desert', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ice-plain', 'west', 'the-white-tower', NULL);

UPDATE rooms SET name = 'The Drift Hollow', description = 'A hollow in the lee of a rock frozen into the ice, drifted over into a chamber with a floor of dry snow and a doorway a person has to crawl through. It is out of the wind entirely and nothing bigger than you can get in. There are no tracks going in. There are none coming out either.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 100, map_y = -1 WHERE id = 'the-drift-hollow';
DELETE FROM exits WHERE room_id = 'the-drift-hollow';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-hollow', 'north', 'the-ice-plain', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-hollow', 'south', 'the-glacier-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-hollow', 'east', 'the-swept-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drift-hollow', 'west', 'the-blue-ice', NULL);

UPDATE rooms SET name = 'The Glacier Head', description = 'Where the ice comes hard against the rock of the upper mountain and buckles against it, thrown up into a ridge of broken white along the join. Everything that falls off the scoured ground above lands somewhere along this line, and the line is a mile long, and you can walk it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 100, map_y = 0 WHERE id = 'the-glacier-head';
DELETE FROM exits WHERE room_id = 'the-glacier-head';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-head', 'north', 'the-drift-hollow', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-head', 'south', 'the-moulin', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-head', 'east', 'the-pavement', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-head', 'west', 'the-slot', NULL);

UPDATE rooms SET name = 'The Moulin', description = 'A round shaft in the ice, six feet across and perfectly circular, with a stream going into it and no sound of the stream arriving anywhere. The walls are ribbed and blue and turn out of sight within twenty feet. Snow at the lip is packed hard by something that has stood here and looked in, more than once.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 100, map_y = 1 WHERE id = 'the-moulin';
DELETE FROM exits WHERE room_id = 'the-moulin';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moulin', 'north', 'the-glacier-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moulin', 'east', 'the-cold-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moulin', 'west', 'the-melt-lip', NULL);

UPDATE rooms SET name = 'The Melt Run', description = 'A channel of grey stone under the lip of the ice, running with meltwater in the afternoon and dry by dark, floored in silt so fine it takes a print like wax. The prints in it now are from this morning. There are three sets and they are all going the same way.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 96, map_y = 3 WHERE id = 'the-melt-run';
DELETE FROM exits WHERE room_id = 'the-melt-run';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-run', 'north', 'the-melt-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-melt-run', 'east', 'the-glacier-toe', NULL);

UPDATE rooms SET name = 'The Glacier Toe', description = 'The end of the ice, filthy with the rock it has carried, giving back the things it took in at the top — stones, gravel, a scatter of bone, all of it in the same condition it went in and none of it from any animal that has been up here in living memory. This is the only place the ice and the red ground touch.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 101, map_y = 2 WHERE id = 'the-glacier-toe';
DELETE FROM exits WHERE room_id = 'the-glacier-toe';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-toe', 'south', 'the-burnt-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glacier-toe', 'west', 'the-melt-run', NULL);

UPDATE rooms SET name = 'The Stone Desert', description = 'Bare rock from here to the skyline, broken into flat plates and swept clean of every loose thing, with wind coming across it that has not touched anything since the sea. There is no snow. There is no ice. There is nothing here for anything, and the completeness of it is what you notice.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 101, map_y = -2 WHERE id = 'the-stone-desert';
DELETE FROM exits WHERE room_id = 'the-stone-desert';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-desert', 'south', 'the-swept-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-desert', 'east', 'the-cold-plain', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-desert', 'west', 'the-ice-plain', NULL);

UPDATE rooms SET name = 'The Swept Ground', description = 'Stone pavement blown so clean that a stone the size of a fist looks like it was placed. Below this the whole mountain is either producing something or eating something. This is the first ground on the climb that is doing neither, and after four tiers of a hillside busy with living the silence of it is the loudest thing about it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 101, map_y = -1 WHERE id = 'the-swept-ground';
DELETE FROM exits WHERE room_id = 'the-swept-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-ground', 'north', 'the-stone-desert', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-ground', 'south', 'the-pavement', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-ground', 'east', 'the-wind-cut', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-ground', 'west', 'the-drift-hollow', NULL);

UPDATE rooms SET name = 'The Pavement', description = 'Frost has broken the rock into slabs with straight cracks between them, laid out in a pattern that looks made from a distance and looks like nothing at all from on top of it. Water gets in the cracks, freezes, and takes the rock apart another notch, every night of every year, forever.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 101, map_y = 0 WHERE id = 'the-pavement';
DELETE FROM exits WHERE room_id = 'the-pavement';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pavement', 'north', 'the-swept-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pavement', 'south', 'the-cold-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pavement', 'east', 'the-approach', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pavement', 'west', 'the-glacier-head', NULL);

UPDATE rooms SET name = 'The Cold Terrace', description = 'A terrace under the swept ground, lower and out of the main of the wind, where the loose stuff the pavement sheds collects in a strip along the back wall. It is the last ground on this tier with any shelter in it at all, and it is where anything that intends to be up here for a night is going to be.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 101, map_y = 1 WHERE id = 'the-cold-terrace';
DELETE FROM exits WHERE room_id = 'the-cold-terrace';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-terrace', 'north', 'the-pavement', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-terrace', 'east', 'the-shelf-under', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-terrace', 'west', 'the-moulin', NULL);

UPDATE rooms SET name = 'The Cold Plain', description = 'A plain of frost-shattered rock with a sky over it that is a darker blue than sky is at any height you have stood at before. There is nothing between you and it. The cold up here is not the wet cold of the corries — it is dry, and it takes the moisture out of you without ever once feeling like weather.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = -2 WHERE id = 'the-cold-plain';
DELETE FROM exits WHERE room_id = 'the-cold-plain';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-plain', 'south', 'the-wind-cut', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-plain', 'west', 'the-stone-desert', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-plain', 'north', 'the-north-step', NULL);

UPDATE rooms SET name = 'The Wind Cut', description = 'A trench worn into solid rock by nothing but moving air and the grit it carries, a foot deep and running dead straight for two hundred paces. The stone in the bottom of it is polished. Whatever the wind does up here, it has been doing since before there was anything on this mountain to watch it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = -1 WHERE id = 'the-wind-cut';
DELETE FROM exits WHERE room_id = 'the-wind-cut';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-cut', 'north', 'the-cold-plain', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-cut', 'south', 'the-approach', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-cut', 'east', 'the-last-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-cut', 'west', 'the-swept-ground', NULL);

UPDATE rooms SET name = 'The Approach', description = 'The ground begins to rise again after a mile of not rising, and rises evenly, and the evenness is the odd part — everything else on this mountain is broken. Nothing is growing, nothing is living, and there is not one bone here, which after the ground you have come across is the thing you notice.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = 0 WHERE id = 'the-approach';
DELETE FROM exits WHERE room_id = 'the-approach';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-approach', 'north', 'the-wind-cut', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-approach', 'south', 'the-shelf-under', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-approach', 'east', 'the-summit-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-approach', 'west', 'the-pavement', NULL);

UPDATE rooms SET name = 'The Shelf Under', description = 'A shelf under the approach, wide and level, that ought to be a nesting ledge — it faces the sun, it is out of the wind, it has a wall at its back. It has been used as one. The old nests are still on it, three of them, packed with sticks carried up from four tiers down, and every one of them is empty and has been for years.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = 1 WHERE id = 'the-shelf-under';
DELETE FROM exits WHERE room_id = 'the-shelf-under';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-under', 'north', 'the-approach', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-under', 'east', 'the-under-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-under', 'west', 'the-cold-terrace', NULL);

UPDATE rooms SET name = 'The Last Ground', description = 'The last of the flat, and the ground here has been swept in a way the wind does not sweep: the loose stone is pushed to the edges of the room in a rough band, and the middle of it is bare rock over an area the size of a barn. The wind at this height comes from one direction. Whatever cleared this did not.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 103, map_y = -1 WHERE id = 'the-last-ground';
DELETE FROM exits WHERE room_id = 'the-last-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-ground', 'south', 'the-summit-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-ground', 'west', 'the-wind-cut', NULL);

UPDATE rooms SET name = 'The Summit Foot', description = 'The foot of the last rise, where the mountain stops being a mountain you walk up and becomes a thing standing over you. The rock changes here — it is darker, and glazed, and in places it has run and set again. Nothing on this tier has an explanation for that. Nothing on this tier comes up here either: no tracks, no droppings, no bones, nothing.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 103, map_y = 0 WHERE id = 'the-summit-foot';
DELETE FROM exits WHERE room_id = 'the-summit-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-summit-foot', 'north', 'the-last-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-summit-foot', 'south', 'the-under-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-summit-foot', 'east', 'the-way-up', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-summit-foot', 'west', 'the-approach', NULL);

UPDATE rooms SET name = 'The Under-Shelf', description = 'A shelf tucked under the summit foot, out of sight from above, and the ground in it is a foot deep in bone chips — small ones, all of them cracked, all of them the same size, as though everything larger had been sorted out and taken away. Whatever eats here does not eat here. It brings it down.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 103, map_y = 1 WHERE id = 'the-under-shelf';
DELETE FROM exits WHERE room_id = 'the-under-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-shelf', 'north', 'the-summit-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-shelf', 'west', 'the-shelf-under', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-shelf', 'south', 'the-under-step', NULL);

UPDATE rooms SET name = 'The Way Up', description = 'A ramp of dark rock running up out of the last ground into the cloud that stands on the summit whatever the weather is doing anywhere else. It is scoured bare and it is warm underfoot — genuinely warm, in a place where the shade never rises above freezing — and it goes up out of sight. Nothing follows you onto it. Not one thing on this mountain will set foot on this.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = 0 WHERE id = 'the-way-up';
DELETE FROM exits WHERE room_id = 'the-way-up';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-way-up', 'west', 'the-summit-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-way-up', 'up', 'the-ramp-head', NULL);

UPDATE rooms SET name = 'The Ramp Head', description = 'The ramp levels out and the ground you are standing on is warm through your boots. Not sunlit — warm, on its own account, on the shaded side of a mountain, at a height where the shade has not been above freezing in a century. Everything about this is wrong and none of it is dangerous, which is worse.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 103, map_y = -2 WHERE id = 'the-ramp-head';
DELETE FROM exits WHERE room_id = 'the-ramp-head';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ramp-head', 'north', 'the-glazed-slab', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ramp-head', 'south', 'the-warm-flags', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ramp-head', 'east', 'the-black-glass', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ramp-head', 'down', 'the-way-up', NULL);

UPDATE rooms SET name = 'The Glazed Slab', description = 'A slab of rock with a surface like a cracked pot glaze, black-brown, shining, catching the light in a way stone does not. Frost has not touched it. Run a hand over it and it is smooth in ropes and runs, as though it was liquid and stopped being liquid quickly, and the ropes all run the same way, downhill.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 103, map_y = -3 WHERE id = 'the-glazed-slab';
DELETE FROM exits WHERE room_id = 'the-glazed-slab';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glazed-slab', 'north', 'the-first-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glazed-slab', 'south', 'the-ramp-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glazed-slab', 'east', 'the-run-stone', NULL);

UPDATE rooms SET name = 'The Warm Flags', description = 'Flat rock laid like paving, dry and warm and swept clear of the grit that is over everything else at this height. Lying down on it you would be comfortable for the first time since the shore. Nothing is lying on it. Nothing on this mountain sleeps here, and there is no reason for that you can see.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = -2 WHERE id = 'the-warm-flags';
DELETE FROM exits WHERE room_id = 'the-warm-flags';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-flags', 'north', 'the-ramp-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-flags', 'south', 'the-warm-under', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-flags', 'east', 'the-heat-shimmer', NULL);

UPDATE rooms SET name = 'The Black Glass', description = 'Where the glaze is thickest it has gone properly to glass: black, conchoidal, breaking to an edge sharper than any blade anybody ever ground. There are chips of it lying loose. A person could arm themselves out of this room in a minute and it would cut anything on this mountain and shatter on the second stroke.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = -3 WHERE id = 'the-black-glass';
DELETE FROM exits WHERE room_id = 'the-black-glass';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-glass', 'north', 'the-run-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-glass', 'south', 'the-heat-shimmer', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-glass', 'east', 'the-scald', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-glass', 'west', 'the-ramp-head', NULL);

UPDATE rooms SET name = 'The Run Stone', description = 'Rock that ran downhill and set again in lobes with the front edges still curled over, the way cooling honey stops. It is a shape nothing else on this mountain has and the whole of the rest of the mountain is broken instead. Something did this in one afternoon; the frost has been at the ordinary rock for ten thousand years and only ever made gravel.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = -4 WHERE id = 'the-run-stone';
DELETE FROM exits WHERE room_id = 'the-run-stone';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-run-stone', 'north', 'the-shoulder-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-run-stone', 'south', 'the-black-glass', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-run-stone', 'west', 'the-glazed-slab', NULL);

UPDATE rooms SET name = 'The Heat Shimmer', description = 'The air over this ground shakes. Looking across it, the terraces beyond are unreliable — they lift and swim and settle, and things standing on them appear to move when they have not. It is impossible to judge distance through it and impossible to be certain of anything you see.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = -1 WHERE id = 'the-heat-shimmer';
DELETE FROM exits WHERE room_id = 'the-heat-shimmer';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-shimmer', 'north', 'the-black-glass', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-shimmer', 'south', 'the-heat-under', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-shimmer', 'east', 'the-basking-flags', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-shimmer', 'west', 'the-warm-flags', NULL);

UPDATE rooms SET name = 'The Scald', description = 'A patch of ground fifty feet across where the rock is scorched pale and everything in it is cracked into small flakes that lift and rock underfoot. The pattern of it has an edge — sharp, curved, as though the heat came from one place and stopped where it stopped. Standing at the edge you can put one boot on either side of it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 105, map_y = -3 WHERE id = 'the-scald';
DELETE FROM exits WHERE room_id = 'the-scald';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scald', 'south', 'the-basking-flags', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scald', 'west', 'the-black-glass', NULL);

UPDATE rooms SET name = 'The Basking Flags', description = 'Warm flat stone, and on it, arranged with a great deal of care and no interest in you whatever, adders. Adders, at this height, above the snow line, in country where a cold-blooded thing should have died out four tiers down. They are here because the rock is warm and the rock is warm for a reason nothing on this hillside will explain.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 105, map_y = -2 WHERE id = 'the-basking-flags';
DELETE FROM exits WHERE room_id = 'the-basking-flags';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-flags', 'north', 'the-scald', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-flags', 'south', 'the-sun-trap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-flags', 'east', 'the-crack-line', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-basking-flags', 'west', 'the-heat-shimmer', NULL);

UPDATE rooms SET name = 'The Crack Line', description = 'A crack running the width of the ground, a hand across, with warm air coming steadily out of it and the rock either side dry when everything else at this height is wet. Grass grows along the lip of it — actual grass, green, in a line, four tiers above the last of it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 106, map_y = -2 WHERE id = 'the-crack-line';
DELETE FROM exits WHERE room_id = 'the-crack-line';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crack-line', 'south', 'the-warm-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crack-line', 'east', 'the-adder-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crack-line', 'west', 'the-basking-flags', NULL);

UPDATE rooms SET name = 'The Adder Shelf', description = 'A shelf of broken warm rock with holes in it going back further than an arm, and it is full. You cannot see them all and there is no way to count them. They are not aggressive and they do not need to be: there is nowhere to put a foot here that is more than a stride from one.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 107, map_y = -2 WHERE id = 'the-adder-shelf';
DELETE FROM exits WHERE room_id = 'the-adder-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-adder-shelf', 'south', 'the-thin-crack', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-adder-shelf', 'east', 'the-first-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-adder-shelf', 'west', 'the-crack-line', NULL);

UPDATE rooms SET name = 'The Sun Trap', description = 'A bowl of rock that holds the day''s heat and adds it to whatever the ground is already doing, so the air in here is genuinely hot and smells of dry stone and, faintly, of something that has been dead for a while somewhere close.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 105, map_y = -1 WHERE id = 'the-sun-trap';
DELETE FROM exits WHERE room_id = 'the-sun-trap';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-trap', 'north', 'the-basking-flags', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-trap', 'south', 'the-vent', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-trap', 'east', 'the-warm-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sun-trap', 'west', 'the-heat-under', NULL);

UPDATE rooms SET name = 'The Warm Scree', description = 'Loose stone that is warm all the way down — dig into it with a boot and the stones two hands deep are warmer than the ones on top. Things have been lying in it. There are body-shaped hollows scooped out of the scree, a dozen of them, and none of them is the shape of anything you have met.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 106, map_y = -1 WHERE id = 'the-warm-scree';
DELETE FROM exits WHERE room_id = 'the-warm-scree';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-scree', 'north', 'the-crack-line', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-scree', 'south', 'the-under-warmth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-scree', 'east', 'the-thin-crack', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-scree', 'west', 'the-sun-trap', NULL);

UPDATE rooms SET name = 'The Thin Crack', description = 'A crack too narrow to enter, breathing out warm air with a faint reek in it, and around the mouth of it the rock is stained a pale yellow-white in a crust you can crumble between finger and thumb. It smells of struck matches. It is not a smell this world has anywhere else.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 107, map_y = -1 WHERE id = 'the-thin-crack';
DELETE FROM exits WHERE room_id = 'the-thin-crack';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-crack', 'north', 'the-adder-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-crack', 'south', 'the-dry-heat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-crack', 'east', 'the-drag-mark', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-crack', 'west', 'the-warm-scree', NULL);

UPDATE rooms SET name = 'The Vent', description = 'A hole in the rock the width of a barrel with warm dry air coming steadily up out of it, and a floor of clean sand round the mouth, out of the wind, out of the weather, and warm all night. It is the most comfortable place on this mountain by a very long way. Nothing follows you in here, and there is nothing in here to follow.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 105, map_y = 0 WHERE id = 'the-vent';
DELETE FROM exits WHERE room_id = 'the-vent';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-vent', 'north', 'the-sun-trap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-vent', 'east', 'the-under-warmth', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-vent', 'west', 'the-lower-warm', NULL);

UPDATE rooms SET name = 'The Under-Warmth', description = 'Ground that steams gently on a cold morning across its whole width, in threads, out of a hundred small cracks. From the tier below this whole hillside would look like it was burning. There is nobody on the tier below to see it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 106, map_y = 0 WHERE id = 'the-under-warmth';
DELETE FROM exits WHERE room_id = 'the-under-warmth';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-warmth', 'north', 'the-warm-scree', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-warmth', 'east', 'the-dry-heat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-warmth', 'west', 'the-vent', NULL);

UPDATE rooms SET name = 'The Dry Heat', description = 'Bone dry, dusty, and hot enough that the sweat is off you before it forms. There is a scatter of small bones here, all of them cracked open lengthwise, and they are dry the way nothing at this altitude gets to be dry: not weathered, baked.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 107, map_y = 0 WHERE id = 'the-dry-heat';
DELETE FROM exits WHERE room_id = 'the-dry-heat';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-heat', 'north', 'the-thin-crack', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-heat', 'south', 'the-under-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-heat', 'east', 'the-tallow-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-heat', 'west', 'the-under-warmth', NULL);

UPDATE rooms SET name = 'The First Terrace', description = 'A level shelf a hundred feet across, and on it a red deer hind, opened along the belly, most of her still there and nothing yet at her. She did not walk up here. There is no route to this shelf that a deer could take, and the ground where she is lying has no drag mark leading onto it from any direction at all.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 108, map_y = -2 WHERE id = 'the-first-terrace';
DELETE FROM exits WHERE room_id = 'the-first-terrace';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-terrace', 'north', 'the-eyrie-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-terrace', 'south', 'the-drag-mark', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-terrace', 'east', 'the-second-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-terrace', 'west', 'the-adder-shelf', NULL);

UPDATE rooms SET name = 'The Second Terrace', description = 'The same again, and used far longer: the rock is stained black in patches that go down into the stone, and the stains are layered, and the layers are years. Something has been bringing things to this exact shelf since before anybody alive was born.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 109, map_y = -2 WHERE id = 'the-second-terrace';
DELETE FROM exits WHERE room_id = 'the-second-terrace';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-terrace', 'south', 'the-scatter', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-terrace', 'east', 'the-third-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-terrace', 'west', 'the-first-terrace', NULL);

UPDATE rooms SET name = 'The Third Terrace', description = 'Bones by the hundred, sorted by nothing, from every animal on this mountain and several you cannot place. Among them, twice, the long bones of something that had to have stood taller than a horse, and there is nothing that size in this country and has not been for a very long time.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 110, map_y = -2 WHERE id = 'the-third-terrace';
DELETE FROM exits WHERE room_id = 'the-third-terrace';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-terrace', 'south', 'the-gorge-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-terrace', 'east', 'the-last-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-terrace', 'west', 'the-second-terrace', NULL);

UPDATE rooms SET name = 'The Last Terrace', description = 'The end of the shelves, and the cleanest of them — swept, or as near swept as makes no difference, with the bones pushed to the edges in a bank and the middle of it bare. Something keeps this floor clear. The wind here comes from one direction and this has been cleared from all of them.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 111, map_y = -2 WHERE id = 'the-last-terrace';
DELETE FROM exits WHERE room_id = 'the-last-terrace';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-terrace', 'south', 'the-picked-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-terrace', 'west', 'the-third-terrace', NULL);

UPDATE rooms SET name = 'The Drag Mark', description = 'A groove worn into the rock, two feet wide, polished, running from the edge of the terrace above out and away over the lip and into open air. Things have been pulled along it, many times, and every one of them was pulled the same way: not up onto the shelf, and not down off it. Off the edge, into nothing.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 108, map_y = -1 WHERE id = 'the-drag-mark';
DELETE FROM exits WHERE room_id = 'the-drag-mark';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drag-mark', 'north', 'the-first-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drag-mark', 'south', 'the-tallow-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drag-mark', 'east', 'the-scatter', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drag-mark', 'west', 'the-thin-crack', NULL);

UPDATE rooms SET name = 'The Scatter', description = 'Where the terrace above sheds what it does not want, over the lip and down, so that this ground is deep in hide, hair, hooves and the ends of things. Everything on this tier that eats works this room at some hour of the day, and they take each other''s turn without much argument, because there is more here than any of them can finish.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 109, map_y = -1 WHERE id = 'the-scatter';
DELETE FROM exits WHERE room_id = 'the-scatter';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scatter', 'north', 'the-second-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scatter', 'east', 'the-gorge-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scatter', 'west', 'the-drag-mark', NULL);

UPDATE rooms SET name = 'The Gorge Ground', description = 'Flat, open, and covered in birds, and they do not go up as you come in — they shuffle sideways, keeping the distance they have decided on, and go back to it. There are enough of them that the noise is constant and the smell arrives before you do.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 110, map_y = -1 WHERE id = 'the-gorge-ground';
DELETE FROM exits WHERE room_id = 'the-gorge-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gorge-ground', 'north', 'the-third-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gorge-ground', 'east', 'the-picked-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gorge-ground', 'west', 'the-scatter', NULL);

UPDATE rooms SET name = 'The Picked Ground', description = 'What is left when the birds have had a day at it: skeletons in their proper order, absolutely clean, lying where they lay. It is very quiet in here compared with the room next door. There is nothing left on any of this and everything knows it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 111, map_y = -1 WHERE id = 'the-picked-ground';
DELETE FROM exits WHERE room_id = 'the-picked-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picked-ground', 'north', 'the-last-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picked-ground', 'south', 'the-white-heap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picked-ground', 'west', 'the-gorge-ground', NULL);

UPDATE rooms SET name = 'The Tallow Stone', description = 'A boulder with fat rendered into its surface over years until the stone itself has gone waxy and yellow and takes a thumbprint. It is the one thing up here that has got richer rather than poorer. Insects work it in the warm hours, in a haze, and there is nothing else at this height for them to be doing.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 108, map_y = 0 WHERE id = 'the-tallow-stone';
DELETE FROM exits WHERE room_id = 'the-tallow-stone';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tallow-stone', 'north', 'the-drag-mark', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tallow-stone', 'east', 'the-grease-flat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tallow-stone', 'west', 'the-dry-heat', NULL);

UPDATE rooms SET name = 'The Grease Flat', description = 'Rock gone dark and slick underfoot, treacherous in a way wet rock is not — it does not dry, and it does not wash off, and a boot goes out from under you on it without any warning at all. The whole floor slopes gently towards the drop.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 109, map_y = 0 WHERE id = 'the-grease-flat';
DELETE FROM exits WHERE room_id = 'the-grease-flat';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grease-flat', 'east', 'the-crack-heap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grease-flat', 'west', 'the-tallow-stone', NULL);

UPDATE rooms SET name = 'The Crack Heap', description = 'A heap of bones every one of which has been split lengthwise and emptied — a season''s work, in one place, done by something with the patience to carry each one up and drop it on the same rock. The rock is under the heap and is white with it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 110, map_y = 0 WHERE id = 'the-crack-heap';
DELETE FROM exits WHERE room_id = 'the-crack-heap';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crack-heap', 'east', 'the-white-heap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crack-heap', 'west', 'the-grease-flat', NULL);

UPDATE rooms SET name = 'The White Heap', description = 'The oldest of the leavings, gone chalky and light and blowing away a little more each year, heaped against the foot of the wall in a bank you would take for snow from any distance. It is not snow. It has been building here for a great deal longer than the snow has been going.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 111, map_y = 0 WHERE id = 'the-white-heap';
DELETE FROM exits WHERE room_id = 'the-white-heap';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-heap', 'north', 'the-picked-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-heap', 'west', 'the-crack-heap', NULL);

UPDATE rooms SET name = 'The Eyrie Foot', description = 'The bottom of a face that has ledges on it all the way up, every one of them white, every one of them used. Bones lie thick along the base where they have been dropped from above over years. The scale of what is up there is the thing you notice: these are not small ledges and they are not carrying small birds.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 108, map_y = -3 WHERE id = 'the-eyrie-foot';
DELETE FROM exits WHERE room_id = 'the-eyrie-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-foot', 'north', 'the-guano-face', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-foot', 'south', 'the-first-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-foot', 'east', 'the-eyrie-ledge', NULL);

UPDATE rooms SET name = 'The Eyrie Ledge', description = 'A ledge wide enough for four people to stand abreast, and on it a nest — a platform of sticks and bone six feet across, packed and trodden and built up in layers for so many seasons that the bottom of it has gone to peat. There is a bird on it and the bird is not the size of anything that should be able to build this.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 109, map_y = -3 WHERE id = 'the-eyrie-ledge';
DELETE FROM exits WHERE room_id = 'the-eyrie-ledge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-ledge', 'north', 'the-white-wall', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-ledge', 'east', 'the-nest-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-ledge', 'west', 'the-eyrie-foot', NULL);

UPDATE rooms SET name = 'The Nest Shelf', description = 'Three more of them along the same shelf, all in use, all filthy, all enormous, and the noise from the young in them carries the length of the tier and does not stop. Anything walking along this ledge is walking past four sets of parents at the range of a raised arm.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 110, map_y = -3 WHERE id = 'the-nest-shelf';
DELETE FROM exits WHERE room_id = 'the-nest-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nest-shelf', 'north', 'the-updraught', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nest-shelf', 'east', 'the-eyrie-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nest-shelf', 'west', 'the-eyrie-ledge', NULL);

UPDATE rooms SET name = 'The Eyrie Head', description = 'The end of the ledge system, and the biggest nest of all — abandoned, older than the rest by a long way, and built to a size that the birds on the shelves below could not manage between them. Whatever raised young in this was not a vulture. Nothing has been in it for decades and nothing has taken it over either.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 111, map_y = -3 WHERE id = 'the-eyrie-head';
DELETE FROM exits WHERE room_id = 'the-eyrie-head';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-head', 'north', 'the-lookout', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyrie-head', 'west', 'the-nest-shelf', NULL);

UPDATE rooms SET name = 'The Guano Face', description = 'The wall below the ledges, white from top to bottom and streaked in runnels, and it stinks in a way that makes your eyes water within a minute. Nothing grows on it. It is the only surface on this mountain that has been comprehensively ruined by living things, and it took them centuries.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 108, map_y = -4 WHERE id = 'the-guano-face';
DELETE FROM exits WHERE room_id = 'the-guano-face';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-guano-face', 'south', 'the-eyrie-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-guano-face', 'east', 'the-white-wall', NULL);

UPDATE rooms SET name = 'The White Wall', description = 'Sheer, white, and the one line of holds up it goes straight through the middle, which means climbing it with your face six inches from the worst of it. At the top the ground opens out onto the perches. Everything with wings takes the other route.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 109, map_y = -4 WHERE id = 'the-white-wall';
DELETE FROM exits WHERE room_id = 'the-white-wall';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-wall', 'north', 'the-high-perch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-wall', 'south', 'the-eyrie-ledge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-wall', 'east', 'the-updraught', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-white-wall', 'west', 'the-guano-face', NULL);

UPDATE rooms SET name = 'The Updraught', description = 'Air comes up this section of face all day, steadily, hard enough to lift a coat, and the birds use it: they drop off the ledges above, take it, and are two hundred feet higher without a wingbeat. Standing here you get the whole smell of the eyrie delivered continuously.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 110, map_y = -4 WHERE id = 'the-updraught';
DELETE FROM exits WHERE room_id = 'the-updraught';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-updraught', 'south', 'the-nest-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-updraught', 'east', 'the-lookout', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-updraught', 'west', 'the-white-wall', NULL);

UPDATE rooms SET name = 'The Lookout', description = 'The corner of the face, with a view down the whole east side of the mountain and out over ground no map in this world covers. There is always a bird on this corner. It is never the same bird twice and it is never not there.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 111, map_y = -4 WHERE id = 'the-lookout';
DELETE FROM exits WHERE room_id = 'the-lookout';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lookout', 'south', 'the-eyrie-head', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lookout', 'west', 'the-updraught', NULL);

UPDATE rooms SET name = 'The High Perch', description = 'A knuckle of rock above the eyrie, worn smooth on top and white round the base, where the big ones sit out the middle of the day with their wings half open. It is worn smooth because so many of them have sat here. There is room on it for two and there are usually two.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 109, map_y = -5 WHERE id = 'the-high-perch';
DELETE FROM exits WHERE room_id = 'the-high-perch';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-perch', 'north', 'the-swept-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-perch', 'south', 'the-white-wall', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-perch', 'east', 'the-wind-post', NULL);

UPDATE rooms SET name = 'The Wind Post', description = 'A pillar standing off the ridge with a flat top and a permanent wind over it, and the top is scoured clean of everything, including the white. Nothing perches here. It faces the threshold and everything that ever tried to sit on it has decided against it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 110, map_y = -5 WHERE id = 'the-wind-post';
DELETE FROM exits WHERE room_id = 'the-wind-post';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-post', 'north', 'the-ash-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-post', 'west', 'the-high-perch', NULL);

UPDATE rooms SET name = 'The First Step', description = 'The ridge starts again here, going east in a series of steps, and the rock changes under your hand within a stride: cold, ordinary, frost-shattered, exactly like the whole mountain below and nothing at all like the ground you have just come off.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 103, map_y = -4 WHERE id = 'the-first-step';
DELETE FROM exits WHERE room_id = 'the-first-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-step', 'south', 'the-glazed-slab', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-step', 'east', 'the-shoulder-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-step', 'west', 'the-lee-side', NULL);

UPDATE rooms SET name = 'The Shoulder Stone', description = 'A hump of rock on the crest with a hollow worn in the top of it that holds water after rain, and the water is the last drinkable thing on the mountain. Everything up here comes to this hollow. The ground round it is beaten to dust by feet in five different sizes.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = -5 WHERE id = 'the-shoulder-stone';
DELETE FROM exits WHERE room_id = 'the-shoulder-stone';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-stone', 'north', 'the-north-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-stone', 'south', 'the-run-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-stone', 'east', 'the-tower-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-stone', 'west', 'the-first-step', NULL);

UPDATE rooms SET name = 'The Tower Foot', description = 'The foot of the first tower, which stands off the crest like a chimney and is climbed round rather than over, on a ledge that goes anticlockwise and is out of sight of everything for most of its length. Things wait on this ledge. There are droppings on it that are not old.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 105, map_y = -5 WHERE id = 'the-tower-foot';
DELETE FROM exits WHERE room_id = 'the-tower-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tower-foot', 'north', 'the-cold-side', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tower-foot', 'east', 'the-black-tower', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tower-foot', 'west', 'the-shoulder-stone', NULL);

UPDATE rooms SET name = 'The Black Tower', description = 'A tower of rock gone black on the east face only — not glazed, not run, just burnt, in a hard-edged shadow-shape as though something extremely bright had stood beside it once and gone away again. The west face is grey and ordinary and lichened like any other rock in the world.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 106, map_y = -5 WHERE id = 'the-black-tower';
DELETE FROM exits WHERE room_id = 'the-black-tower';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-tower', 'north', 'the-shadow-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-tower', 'east', 'the-tower-gap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-tower', 'west', 'the-tower-foot', NULL);

UPDATE rooms SET name = 'The Tower Gap', description = 'The gap between the last two towers, floored with rubble and roofed with sky, and the wind funnels through it hard enough that you go through leaning. On the far side the ground rises to the notch and the notch is the only way east from here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 107, map_y = -5 WHERE id = 'the-tower-gap';
DELETE FROM exits WHERE room_id = 'the-tower-gap';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tower-gap', 'north', 'the-high-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tower-gap', 'west', 'the-black-tower', NULL);

UPDATE rooms SET name = 'The North Lip', description = 'The north edge of the crest, where the ground goes over into shadow and stays there. There is old ice in the cracks along the whole lip. Fifty paces south of here the rock is warm enough to sleep on; standing on this line you can feel both at once.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = -6 WHERE id = 'the-north-lip';
DELETE FROM exits WHERE room_id = 'the-north-lip';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-lip', 'north', 'the-crest-gap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-lip', 'south', 'the-shoulder-stone', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-lip', 'east', 'the-cold-side', NULL);

UPDATE rooms SET name = 'The Cold Side', description = 'Permanently shaded ground, hard frozen, with rime standing on the north face of every stone. Nothing lives on this strip and nothing crosses it if there is any other way round, which there is, forty feet south, and everything knows it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 105, map_y = -6 WHERE id = 'the-cold-side';
DELETE FROM exits WHERE room_id = 'the-cold-side';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-side', 'north', 'the-crown-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-side', 'south', 'the-tower-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-side', 'east', 'the-shadow-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-side', 'west', 'the-north-lip', NULL);

UPDATE rooms SET name = 'The Shadow Step', description = 'A step down into shade so total that after the glare off the crest you stand still for a while and wait for your eyes. Everything in here is grey and blue and cold. There are things standing in it. There always are, because it is the one piece of cover between the towers and the notch.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 106, map_y = -6 WHERE id = 'the-shadow-step';
DELETE FROM exits WHERE room_id = 'the-shadow-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shadow-step', 'north', 'the-last-crest', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shadow-step', 'south', 'the-black-tower', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shadow-step', 'east', 'the-high-notch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shadow-step', 'west', 'the-cold-side', NULL);

UPDATE rooms SET name = 'The High Notch', description = 'The last gap in the ridge, narrow, floored in scoured rock, and it looks east onto the threshold. From here you can see the whole of the empty ground and the door at the far end of it and everything else on the ridge behind you, and nothing at all in between.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 107, map_y = -6 WHERE id = 'the-high-notch';
DELETE FROM exits WHERE room_id = 'the-high-notch';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-notch', 'south', 'the-tower-gap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-notch', 'east', 'the-scorched-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-notch', 'west', 'the-shadow-step', NULL);

UPDATE rooms SET name = 'The Crown Edge', description = 'The north brow of the ridge, level and exposed, with the whole world laid out below on that side: the cloud line under you like a floor, and the sea somewhere past the edge of it, and no ground anywhere in sight that is higher than this except what is behind you.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 105, map_y = -7 WHERE id = 'the-crown-edge';
DELETE FROM exits WHERE room_id = 'the-crown-edge';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crown-edge', 'south', 'the-cold-side', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crown-edge', 'east', 'the-last-crest', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crown-edge', 'west', 'the-crest-gap', NULL);

UPDATE rooms SET name = 'The Last Crest', description = 'The end of the ridge proper, a heap of shattered blocks with nothing beyond them but the drop and the threshold ground away to the east. The blocks are cracked in the way frost cracks things, and one of them is cracked in a way frost does not: through, cleanly, and the two halves are eighteen feet apart.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 106, map_y = -7 WHERE id = 'the-last-crest';
DELETE FROM exits WHERE room_id = 'the-last-crest';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-crest', 'south', 'the-shadow-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-crest', 'west', 'the-crown-edge', NULL);

UPDATE rooms SET name = 'The Scorched Step', description = 'Through the notch and onto ground that is different immediately: pale, cracked shallow, and swept clean of every loose thing. There is nothing living here. Not a bird, not a print, not a dropping, and after four tiers of a mountain busy with animals the absence has a shape and an edge and you are standing on it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 108, map_y = -6 WHERE id = 'the-scorched-step';
DELETE FROM exits WHERE room_id = 'the-scorched-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scorched-step', 'north', 'the-quiet-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scorched-step', 'east', 'the-swept-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scorched-step', 'west', 'the-high-notch', NULL);

UPDATE rooms SET name = 'The Swept Terrace', description = 'A terrace of bare rock, wide and level and blown clear — except the wind at this height comes from one direction, and this ground has been cleared from all of them, and the loose stone is heaped round the edges in a rough ring as though something large had settled here and turned round more than once.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 109, map_y = -6 WHERE id = 'the-swept-terrace';
DELETE FROM exits WHERE room_id = 'the-swept-terrace';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-terrace', 'north', 'the-bare-place', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-terrace', 'south', 'the-high-perch', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-terrace', 'east', 'the-ash-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swept-terrace', 'west', 'the-scorched-step', NULL);

UPDATE rooms SET name = 'The Ash Ground', description = 'Grey-white grit lying over the rock, fine as flour, and it takes a print perfectly and holds it. There are no prints. Yours are the first and they will be the only ones. Nothing on this mountain has walked across this room since the last time it rained here.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 110, map_y = -6 WHERE id = 'the-ash-ground';
DELETE FROM exits WHERE room_id = 'the-ash-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-ground', 'north', 'the-threshold', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-ground', 'south', 'the-wind-post', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-ground', 'east', 'the-hot-flags', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-ground', 'west', 'the-swept-terrace', NULL);

UPDATE rooms SET name = 'The Hot Flags', description = 'The end of the terrace, and the flags here are hot — not warm; hot enough that you would not sit down on them and not so hot that you cannot stand. The heat is coming up through the rock from underneath, evenly, across the whole floor, and it is not coming from the sun because it is exactly the same after dark.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 111, map_y = -6 WHERE id = 'the-hot-flags';
DELETE FROM exits WHERE room_id = 'the-hot-flags';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hot-flags', 'west', 'the-ash-ground', NULL);

UPDATE rooms SET name = 'The Quiet Ground', description = 'Bare rock, no wind in it despite the height, and no sound of any kind. On a mountain there is always something — grit moving, water somewhere, a bird a mile off — and here there is not, and the silence is not peaceful. It is the silence of a room that everything has left.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 108, map_y = -7 WHERE id = 'the-quiet-ground';
DELETE FROM exits WHERE room_id = 'the-quiet-ground';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quiet-ground', 'south', 'the-scorched-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quiet-ground', 'east', 'the-bare-place', NULL);

UPDATE rooms SET name = 'The Bare Place', description = 'Flat stone, entirely clean, and warm. Standing in the middle of it you are the largest thing in sight and the most exposed you have been anywhere in this world. It is a hundred paces to any cover in any direction and the cover is behind you.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 109, map_y = -7 WHERE id = 'the-bare-place';
DELETE FROM exits WHERE room_id = 'the-bare-place';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-place', 'south', 'the-swept-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-place', 'east', 'the-threshold', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bare-place', 'west', 'the-quiet-ground', NULL);

UPDATE rooms SET name = 'The Threshold', description = 'The ground narrows between two walls of rock into an approach forty feet wide, floored in the same swept ash and rising gently east. There is a smell here, strong, and it is the smell of the crack-line four hundred paces back multiplied by a very great deal: struck matches, hot stone, and something underneath that is meat.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 110, map_y = -7 WHERE id = 'the-threshold';
DELETE FROM exits WHERE room_id = 'the-threshold';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-threshold', 'south', 'the-ash-ground', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-threshold', 'east', 'the-last-shelter', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-threshold', 'west', 'the-bare-place', NULL);

UPDATE rooms SET name = 'The Last Shelter', description = 'A hole under a fallen block, dry, dark, and just big enough, with a floor of clean grit and a view east through the gap of a slot of pale sky. It is warm in here and out of the wind and nothing follows you in. It is also thirty feet from ground nothing on this mountain will set foot on, and both of those things are true at once.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 111, map_y = -7 WHERE id = 'the-last-shelter';
DELETE FROM exits WHERE room_id = 'the-last-shelter';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-shelter', 'east', 'the-summit-gate', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-shelter', 'west', 'the-threshold', NULL);

UPDATE rooms SET name = 'The Summit Gate', description = 'The approach ends at a wall of rock with a gap in it, and the gap is the way through, and beyond it there is nothing to see but light. Warm air comes out steadily. The ground at the gap is swept absolutely clean and the sweeping stops in a line you could draw with a ruler, and on this side of the line the grit is undisturbed for as far back as you can see.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 112, map_y = -7 WHERE id = 'the-summit-gate';
DELETE FROM exits WHERE room_id = 'the-summit-gate';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-summit-gate', 'west', 'the-last-shelter', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-summit-gate', 'up', 'the-summit', NULL);

UPDATE rooms SET name = 'The Red Tail', description = 'The red ground runs out in a tail of rust-coloured grit that thins to nothing across a hundred paces, and the rock under it goes grey, then dark, then warm. It is the gentlest way onto this tier and the longest, and everything that walks up here rather than flying takes it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 99, map_y = 2 WHERE id = 'the-red-tail';
DELETE FROM exits WHERE room_id = 'the-red-tail';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-tail', 'east', 'the-low-traverse', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-red-tail', 'down', 'the-gully-top', NULL);

UPDATE rooms SET name = 'The Low Traverse', description = 'A shelf running east under the whole south side, level and easy, with the tier''s business going on somewhere above you and out of sight. It is the only ground on this mountain where you can walk for a while and think about something else, and that is exactly what makes it worth being careful on.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 100, map_y = 2 WHERE id = 'the-low-traverse';
DELETE FROM exits WHERE room_id = 'the-low-traverse';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-traverse', 'east', 'the-south-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-traverse', 'west', 'the-red-tail', NULL);

UPDATE rooms SET name = 'The South Shelf', description = 'The shelf widens and there are dwarf plants growing along the back of it in a strip, brown and woody and barely alive, watered by something seeping out of the rock behind. It is the last growing thing on the mountain and it covers about the area of a table.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = 2 WHERE id = 'the-south-shelf';
DELETE FROM exits WHERE room_id = 'the-south-shelf';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-shelf', 'east', 'the-warm-gutter', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-shelf', 'west', 'the-low-traverse', NULL);

UPDATE rooms SET name = 'The Warm Gutter', description = 'A gutter of smooth rock carrying warm air rather than water, running the length of the shelf, and the grit in it is dry and fine and full of prints going both ways. Every animal on this tier uses this and none of them is trying to hide the fact.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 103, map_y = 2 WHERE id = 'the-warm-gutter';
DELETE FROM exits WHERE room_id = 'the-warm-gutter';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-gutter', 'east', 'the-lower-flags', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-gutter', 'west', 'the-south-shelf', NULL);

UPDATE rooms SET name = 'The Lower Flags', description = 'Flat warm paving under an overhang, out of the weather and out of the sight of anything above. Things have lain here: hollows, hair, and in one place the whole print of something that was here long enough for its warmth to have dried the grit under it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = 2 WHERE id = 'the-lower-flags';
DELETE FROM exits WHERE room_id = 'the-lower-flags';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-flags', 'east', 'the-south-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-flags', 'west', 'the-warm-gutter', NULL);

UPDATE rooms SET name = 'The South Step', description = 'The shelf ends against a step of solid rock the height of two people, split by a chimney you can get up with your back on one side and your boots on the other. Everything on four legs stops here. It is the reason the low traverse is quiet and the ground above it is not.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 105, map_y = 2 WHERE id = 'the-south-step';
DELETE FROM exits WHERE room_id = 'the-south-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-step', 'north', 'the-step-up', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-step', 'east', 'the-south-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-step', 'west', 'the-lower-flags', NULL);

UPDATE rooms SET name = 'The Step Up', description = 'The top of the chimney, on a ledge with the terraces'' noise suddenly close and the whole warm side of the tier opening out east. Coming up here you arrive in the middle of everything with no warning at all and no way to look first.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 105, map_y = 1 WHERE id = 'the-step-up';
DELETE FROM exits WHERE room_id = 'the-step-up';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-step-up', 'south', 'the-south-step', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-step-up', 'east', 'the-terrace-foot', NULL);

UPDATE rooms SET name = 'The South Gully', description = 'A gully running up into the terraces, choked with loose stone and everything that has been washed or dropped down it, and it is the drain for the whole kill ground above. What is in it is not pleasant and there is a great deal of it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 106, map_y = 2 WHERE id = 'the-south-gully';
DELETE FROM exits WHERE room_id = 'the-south-gully';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-gully', 'north', 'the-terrace-foot', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-gully', 'west', 'the-south-step', NULL);

UPDATE rooms SET name = 'The Terrace Foot', description = 'The foot of the terrace wall, in the shade of it, with bones lying about that came off the top and a strip of clear ground along the base that everything uses as a road. It is the only shade on the warm side and everything up here spends part of its day in it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 106, map_y = 1 WHERE id = 'the-terrace-foot';
DELETE FROM exits WHERE room_id = 'the-terrace-foot';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-foot', 'south', 'the-south-gully', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-foot', 'east', 'the-under-terrace', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-terrace-foot', 'west', 'the-step-up', NULL);

UPDATE rooms SET name = 'The Under-Terrace', description = 'Under the lip of the terraces proper, where what falls off them lands and stays, and it is deep. You are walking on it rather than over it. Something has dug into the pile in three places and dug down a long way, and the diggings are recent.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 107, map_y = 1 WHERE id = 'the-under-terrace';
DELETE FROM exits WHERE room_id = 'the-under-terrace';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-terrace', 'north', 'the-dry-heat', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-terrace', 'west', 'the-terrace-foot', NULL);

UPDATE rooms SET name = 'The North Step', description = 'Up off the cold plain onto the north shoulder of the last ridge, and the wind arrives the moment you top the step and does not let up again. The rock here is ordinary and cold and there is nothing warm anywhere on this side.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = -3 WHERE id = 'the-north-step';
DELETE FROM exits WHERE room_id = 'the-north-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-step', 'south', 'the-cold-plain', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-step', 'east', 'the-cold-shoulder', NULL);

UPDATE rooms SET name = 'The Cold Shoulder', description = 'A broad cold shoulder of frost-shattered rock with rime standing on the north side of everything, and the sun does not reach it at any hour. It is the coldest ground on the mountain and it is four hundred paces from the warmest.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = -4 WHERE id = 'the-cold-shoulder';
DELETE FROM exits WHERE room_id = 'the-cold-shoulder';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shoulder', 'east', 'the-shoulder-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-shoulder', 'west', 'the-north-step', NULL);

UPDATE rooms SET name = 'The Shoulder End', description = 'The shoulder narrows and ends against the crest, with a choice of going up onto it or dropping into the lee on the south side. From here the ridge ahead is in profile, tower after tower, and you can count them and know exactly how long the rest of this is going to take.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = -5 WHERE id = 'the-shoulder-end';
DELETE FROM exits WHERE room_id = 'the-shoulder-end';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-end', 'north', 'the-north-crest', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-end', 'south', 'the-lee-side', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shoulder-end', 'west', 'the-cold-shoulder', NULL);

UPDATE rooms SET name = 'The Lee Side', description = 'A hollow in the south side of the shoulder, out of the wind entirely, floored with dry grit and walled on three sides — the last ordinary shelter on this mountain, the kind a cold hillside makes anywhere in the world. Nothing follows you in. It is not warm and there is nothing strange about it, and after the ground east of here that is worth something.', is_entry = 0, is_safe = 1,
  region = 'mountain', is_spawn = 0, map_x = 101, map_y = -5 WHERE id = 'the-lee-side';
DELETE FROM exits WHERE room_id = 'the-lee-side';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lee-side', 'north', 'the-shoulder-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lee-side', 'east', 'the-first-step', NULL);

UPDATE rooms SET name = 'The North Crest', description = 'On top of the crest, in the full weight of the wind, with the north face dropping away on your left into cloud that is a long way below you now. The crest runs east in a clean line. There is nothing to hold on to for its whole length and nothing that needs holding on to unless it is blowing, and it is blowing.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 102, map_y = -6 WHERE id = 'the-north-crest';
DELETE FROM exits WHERE room_id = 'the-north-crest';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-crest', 'south', 'the-shoulder-end', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-crest', 'east', 'the-crest-walk', NULL);

UPDATE rooms SET name = 'The Crest Walk', description = 'Level walking on a crest three paces wide, which after everything below it is nearly pleasant. The rock is scoured, the wind is steady, and you can see the towers ahead and the eyrie beyond them and, past all of it, the pale ground at the end that has nothing on it.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 103, map_y = -6 WHERE id = 'the-crest-walk';
DELETE FROM exits WHERE room_id = 'the-crest-walk';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-walk', 'east', 'the-crest-gap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-walk', 'west', 'the-north-crest', NULL);

UPDATE rooms SET name = 'The Crest Gap', description = 'A break in the crest where the rock has fallen away on both sides at once, leaving a saddle you go down into and up out of. There is old snow in the bottom of it, grey and hard, and it is the last snow on this mountain — everything east of here is either cold rock or warm rock and there is none of it left.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = -7 WHERE id = 'the-crest-gap';
DELETE FROM exits WHERE room_id = 'the-crest-gap';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-gap', 'south', 'the-north-lip', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-gap', 'east', 'the-crown-edge', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crest-gap', 'west', 'the-crest-walk', NULL);

UPDATE rooms SET name = 'The Under-Step', description = 'Down off the shelves and in under the whole east side, on a line that runs below everything. It is dark in here for the height, with the tier hanging over you, and the first thing you notice is that the rock has stopped being cold.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 103, map_y = 3 WHERE id = 'the-under-step';
DELETE FROM exits WHERE room_id = 'the-under-step';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-step', 'north', 'the-under-shelf', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-step', 'east', 'the-shelf-walk', NULL);

UPDATE rooms SET name = 'The Shelf Walk', description = 'A walk under the overhang, floored in dry grit, roofed by rock, with the light coming in from the side in a long strip. Bones lie along the back wall where things have carried them in to work on them out of sight of the birds.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = 3 WHERE id = 'the-shelf-walk';
DELETE FROM exits WHERE room_id = 'the-shelf-walk';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-walk', 'east', 'the-warm-under', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelf-walk', 'west', 'the-under-step', NULL);

UPDATE rooms SET name = 'The Warm Under', description = 'The rock overhead is warm and the ground is warm and the air is still, and it smells of dust and animals. Things sleep here. There are hollows worn in the grit in a row along the back, all of them used, and none of them belonging to anything small.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 104, map_y = 1 WHERE id = 'the-warm-under';
DELETE FROM exits WHERE room_id = 'the-warm-under';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-under', 'north', 'the-warm-flags', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-under', 'east', 'the-heat-under', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warm-under', 'west', 'the-shelf-walk', NULL);

UPDATE rooms SET name = 'The Heat Under', description = 'Where the overhang narrows and the warmth concentrates, and it is properly hot: dry, still, and thick. It is unpleasant to be in for long and it is full of things that are not finding it unpleasant at all.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 101, map_y = -3 WHERE id = 'the-heat-under';
DELETE FROM exits WHERE room_id = 'the-heat-under';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-under', 'north', 'the-heat-shimmer', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-under', 'south', 'the-lower-warm', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-under', 'east', 'the-sun-trap', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heat-under', 'west', 'the-warm-under', NULL);

UPDATE rooms SET name = 'The Lower Warm', description = 'The low corner of the warm ground, where it runs out over the edge and the cold comes back up at you from below. Standing on the line you have warm air on your face and cold air round your knees and the whole of the tier below laid out under the second of them.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 100, map_y = -3 WHERE id = 'the-lower-warm';
DELETE FROM exits WHERE room_id = 'the-lower-warm';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-warm', 'north', 'the-heat-under', NULL);
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lower-warm', 'east', 'the-vent', NULL);

UPDATE rooms SET name = 'The Summit', description = 'The wall opens and the top of the mountain is a bowl of bare rock perhaps two hundred paces across, and there is nothing in it: no snow, no ice, no lichen, no bone. The floor is swept and it is warm. Off the middle of it the rock has run and set in ropes and lobes with the front edges curled over, in a rough ring, and inside the ring the stone is glazed and black and worn smooth in the way a doorstep is worn. The whole sky is here. There is no higher ground anywhere you can see in any direction, and nothing between you and any of it. Whatever made this ring is not small and does not need to be anywhere else, and the wind that has been on you for five tiers has stopped, because there is nothing up here for it to come round.', is_entry = 0, is_safe = 0,
  region = 'mountain', is_spawn = 0, map_x = 111, map_y = -8 WHERE id = 'the-summit';
DELETE FROM exits WHERE room_id = 'the-summit';
INSERT OR REPLACE INTO exits (room_id, dir, to_room, key_item) VALUES ('the-summit', 'down', 'the-summit-gate', NULL);
